window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0003", [{"word":"adopt","ipa_uk":"/əˈdɒpt/","ipa_us":"/əˈdɑːpt/","definition_zh":"采用；收养","definition_en":"to take something as one's own by choice — a method, a child, an animal, a role, or a view","core_image":"把原本不属于自己的东西，主动挑过来抱进怀里","scene":"After months of testing, the lab adopted the new safety protocol for every experiment.","sceneCN":"这里 adopt 是「采用、采纳」（第 1 个义项：把方法或制度收为己用）；句意：经过数月测试，实验室在每次实验中都采用了新的安全规程。图中可辨识物件：实验台、护目镜、写着 NEW PROTOCOL 的流程牌、签字的记录表。","pos":[{"tag":"vt.","zh":"采用；采纳；收养；领养；承担；选用"},{"tag":"vi.","zh":"采取（某种做法）；收养（与 into 连用）"}],"collocations":[{"phrase":"adopt a policy","zh":"采纳一项政策"},{"phrase":"adopt a child","zh":"收养一个孩子"},{"phrase":"adopt an approach","zh":"采用一种方法"},{"phrase":"adopt a resolution","zh":"通过一项决议"}],"forms":[{"label":"三单（he/she/it）","form":"adopts"},{"label":"过去式（已经发生）","form":"adopted"},{"label":"过去分词（完成／被动）","form":"adopted"},{"label":"现在分词（进行体）","form":"adopting"}],"derivatives":[{"word":"adoption","pos":"n.","zh":"收养；采用；通过"},{"word":"adoptive","pos":"adj.","zh":"收养关系的；采用的"},{"word":"adoptee","pos":"n.","zh":"被收养者"},{"word":"adopter","pos":"n.","zh":"收养人；采用者"}],"senses":[{"no":"01","title":"Adopt a method or system","titleCN":"采用一种方法或制度","definition":"to decide to use a particular method, system, or policy and begin to follow it","definitionCN":"决定采用某种方法、制度或政策，并开始照此执行","example":"The school adopted a new reading program this year.","exampleCN":"学校今年采用了一套新的阅读课程。","why":"adoptare is ad- 'to' plus optare 'choose'. The word starts with a deliberate pick: one method is selected out of several and brought into one's own practice.","whyCN":"adoptare 是 ad-“向”加 optare“选择”。这个词的起点是一次有意的挑选：从若干方法中选出一个，拉进自己的做法里。"},{"no":"02","title":"Adopt a rule or standard","titleCN":"采纳规则或标准","definition":"to formally accept and start using a rule, policy, or standard","definitionCN":"正式接受并开始执行某项规则、政策或标准","example":"The city adopted stricter building codes after the earthquake.","exampleCN":"地震之后，这座城市采用了更严格的建筑规范。","why":"A rule is not inherited; it is chosen and put into force. The collective choice makes it binding on everyone inside the group.","whyCN":"规则不是继承来的，而是被选中并开始生效的。这个集体选择让规则对群体内所有人都有约束力。"},{"no":"03","title":"Adopt a child","titleCN":"依法收养孩子","definition":"to take another person's child legally as one's own and raise the child as a family member","definitionCN":"依法把别人的孩子收为自己的孩子并抚养成人","example":"They adopted a girl from the local orphanage.","exampleCN":"他们从当地孤儿院收养了一个女孩。","why":"The legal sense is the most literal extension of taking to oneself: a child is chosen, brought into the family, and given its name and care.","whyCN":"法律义是“收归己有”的最直接延伸：孩子被选中、带进家庭，并获得这个家庭的姓氏与照料。"},{"no":"04","title":"Adopt a pet","titleCN":"领养动物","definition":"to take a homeless or rescued animal into one's home and care for it","definitionCN":"把流浪或被救助的动物带回家并负责照料","example":"We adopted a stray cat from the shelter last spring.","exampleCN":"去年春天，我们从收容所领养了一只流浪猫。","why":"The same gesture moves from a child to a creature: it is lifted out of a cage and made part of the household.","whyCN":"同一个动作从孩子移到动物身上：把它从笼子里抱出来，变成家庭的一员。"},{"no":"05","title":"Adopt a role or duty","titleCN":"承担角色或职责","definition":"to accept and begin to carry out a role, duty, or responsibility that was not originally yours","definitionCN":"接受并开始履行原本不属于自己的角色、职责或责任","example":"When the coach left, she adopted the role of team leader.","exampleCN":"教练离开后，她承担起了队长的角色。","why":"A role is put on like a coat. The choosing remains, but what is taken on is now an obligation that others expect you to keep.","whyCN":"角色像外套一样被穿在身上。挑选仍在，但被接过来的东西已经变成别人期待你守住的义务。"},{"no":"06","title":"Adopt a name or title","titleCN":"取用名字或称号","definition":"to begin to use a particular name, title, or pen name for oneself","definitionCN":"开始使用某个名字、称号或笔名","example":"The writer adopted a pen name before publishing her first novel.","exampleCN":"这位作家在出版第一部小说前取了一个笔名。","why":"A name is worn publicly. Adopting one means selecting a new label and letting the old one fall away.","whyCN":"名字是公开穿在身上的标签。采用一个名字，就是选中新标签，同时让旧标签退到身后。"},{"no":"07","title":"Adopt a view or belief","titleCN":"采纳观点或信念","definition":"to accept a particular opinion, attitude, or belief as one's own","definitionCN":"接受某种观点、态度或信念，并把它当作自己的立场","example":"The committee adopted the view that the plan was too risky.","exampleCN":"委员会采纳了“这个计划风险过大”的观点。","why":"An opinion is held the way an object is held. Adopting it means choosing it and making it part of your own position.","whyCN":"观点像物件一样被握在手里。采纳它，就是选中它，并把它变成自己立场的一部分。"},{"no":"08","title":"Adopt a tone or manner","titleCN":"采用某种语气或举止","definition":"to take on a particular tone, accent, or manner of speaking, sometimes artificially","definitionCN":"采用某种语气、口音或说话方式，有时带有刻意模仿的意味","example":"He adopted a calm, reassuring tone when speaking to the children.","exampleCN":"和孩子们说话时，他换上了一副平静、令人安心的语气。","why":"Tone is a garment for the voice. It can be put on for a situation, and the word quietly suggests that it may not be the speaker's natural voice.","whyCN":"语气是声音的外衣，可以为了某个场合穿上；这个词也悄悄暗示，它未必是说话者本来的声音。"},{"no":"09","title":"Adopt a proposal or budget","titleCN":"正式通过提案或预算","definition":"of a group or assembly, to accept a proposal, report, or budget formally and put it into effect","definitionCN":"指团体或议会正式接受提案、报告或预算，并使其生效","example":"The board adopted the budget after a short debate.","exampleCN":"董事会经过简短辩论后通过了预算。","why":"Here the choice becomes official and collective. What was proposed from outside is now taken in by the group as its own decision.","whyCN":"这里的挑选变成正式而集体的行为。原本由外部提出的东西，现在被团体接进来，成为自己的决定。"},{"no":"10","title":"Adopt a candidate","titleCN":"选定候选人","definition":"of a party or convention, to select a person as its official candidate","definitionCN":"指政党或代表大会选定某人为正式候选人","example":"The party adopted him as its candidate for the coming election.","exampleCN":"该党选定他为下届选举的候选人。","why":"The party chooses a person and brings him under its own banner. Selection and public ownership of the choice are both present.","whyCN":"政党选中一个人，并把他带到自己的旗帜下。这里同时有“挑选”和“公开认领”两层动作。"}],"etymology":{"intro":{"en":"Adopt entered English around 1500 as a back-formation from adoption, or through Old French adopter and Latin adoptare. Its Latin core is a choice, but the deeper origin of optare is uncertain.","cn":"adopt 约在 1500 年进入英语，可能由 adoption 逆构而来，也可能经古法语 adopter 或直接来自拉丁语 adoptare。它的拉丁核心是“选择”，但 optare 的更深来源并不确定。"},"items":[{"era":"C. 1500","en":"First recorded as an English verb meaning 'take to oneself, make one's own by selection'. It was formed as a back-formation from adoption, or borrowed from Old French adopter (14c.) or directly from Latin adoptare.","cn":"最早记录为英语动词，意为“收归己有、经挑选而成为自己的”。它由 adoption 逆构而来，或借自 14 世纪古法语 adopter，或直接来自拉丁语 adoptare。"},{"era":"OLD FRENCH","en":"Old French adopter (14c.) meant 'to adopt as a child'. Originally English used adopt of friends, fathers, citizens and children alike, not only of legal adoption.","cn":"古法语 adopter（14 世纪）意为“收养为子”。早期英语的 adopt 可用于朋友、父辈、公民和孩子，并不只限于法律收养。"},{"era":"LATIN","en":"Latin adoptare meant 'choose for oneself, take by choice, select', especially 'take into a family as a child'. It joins ad- 'to' and optare 'choose, wish, desire'.","cn":"拉丁语 adoptare 意为“为自己挑选、按选择取得、选中”，尤指“收养为家庭成员”。它由 ad-“向”与 optare“选择、希望、渴望”组成。"},{"era":"PROTO-ITALIC","en":"The origin of optare is uncertain. De Vaan derives it from Proto-Italic *opeje- 'to choose, grab', possibly from PIE *hopeie-, and compares Hittite epp/app- 'take, grab'. The deeper root is source uncertain.","cn":"optare 的来源不确定。De Vaan 认为它来自原始意大利语 *opeje-“选择、抓取”，可能上溯到原始印欧语 *hopeie-，并可比赫梯语 epp/app-“拿、抓”。更深的词根来源不确定。"},{"era":"16C.–17C.","en":"The specific senses 'legally take as one's own child' and 'embrace a practice or method' are both recorded from about 1600. From there the word spreads to policies, names, roles and candidates.","cn":"“依法收养自己的孩子”和“接受某种做法或方法”这两个具体义项都约在 1600 年出现。此后这个词扩展到政策、名字、角色和候选人。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the double life of adopt: a private, warm act (adopting a child or pet) and a public, procedural act (adopting a budget, rule or candidate). Both are still 'taking something in by choice'.","cn":"现代英语保留了 adopt 的双重生活：一方面是私人的、温暖的动作（收养孩子或宠物），另一方面是公共的、程序性的动作（通过预算、规则或候选人）。两者都仍是“经选择而收进来”。"}]},"similar":{"note":{"en":"The first group separates words that look or sound close; the second group separates words with a nearby meaning. Form is checked before meaning.","cn":"第一组区分形近、音近的词；第二组区分意思相近的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adapt","ipa":"/əˈdæpt/","tag":"spelling","definition":"to make something suitable for a new use or situation; to change a book for film. It differs from adopt by one vowel and comes from aptare 'fit'.","definitionCN":"使适应；改编。它与 adopt 只差一个元音，来自 aptare“使合适”。"},{"word":"adept","ipa":"/əˈdept/","tag":"spelling","definition":"very skilled at something. The similar shape hides a different Latin source, adipsci 'obtain'.","definitionCN":"熟练的；内行。形近但词源不同，来自 adipsci“获得”。"},{"word":"adoptive","ipa":"/əˈdɒptɪv/","tag":"derived form","definition":"relating to adoption, especially an adoptive parent or home. It is the adjective of adopt, not a separate root.","definitionCN":"收养关系的；采用的。它是 adopt 的形容词，不是另一个词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"embrace","ipa":"/ɪmˈbreɪs/","tag":"eager acceptance","definition":"to accept an idea, change, or method willingly and enthusiastically. It adds warmth that adopt may lack.","definitionCN":"欣然接受观点、变化或方法，比 adopt 多一层热情。"},{"word":"assume","ipa":"/əˈsjuːm/","tag":"role or duty","definition":"to take on a role, duty, or power. It stresses beginning to hold the position, not choosing a method.","definitionCN":"承担角色、职责或权力；强调开始执掌，而不是挑选方法。"},{"word":"endorse","ipa":"/ɪnˈdɔːs/","tag":"public support","definition":"to say publicly that you support or approve of something. It is about public backing more than personal use.","definitionCN":"公开赞同、背书；强调公开支持，而不是自己拿来用。"},{"word":"take up","ipa":"/teɪk ʌp/","tag":"phrasal verb","definition":"to start doing or accepting something. It is plainer and more conversational than adopt.","definitionCN":"开始从事、接受；比 adopt 更口语、更轻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"ad- means 'to' and optare means 'choose', so adopt is literally 'choose toward oneself'.","cn":"ad- 表示“向”，optare 表示“选择”，所以 adopt 字面上就是“朝着自己选过来”。"},{"en":"adoption is the noun most people meet first, in legal, social and political news.","cn":"大多数人最先遇到的是名词 adoption，见于法律、社会和政治新闻。"},{"en":"adopt a policy is one of the most common collocations in newspaper English.","cn":"adopt a policy 是新闻英语里最常见的搭配之一。"},{"en":"adopt a child and adopt a pet share the same warm gesture of taking someone in.","cn":"adopt a child 与 adopt a pet 共享同一个温暖动作：把某个生命接进家门。"},{"en":"option, opt and optional all hide the same 'choose' root, so adopt contains a quiet option.","cn":"option、opt、optional 都藏着同一个“选择”词根，所以 adopt 里也藏着一个安静的 option。"}],"abstract":[{"en":"Picture a hand reaching across a table and pulling a sheet toward itself. The sheet can be a rule, a child's hand, a role badge, or an opinion.","cn":"想象一只手越过桌面，把一张纸拉向自己。这张纸可以是规则、孩子的手、角色徽章，或一个观点。"},{"en":"The word always has two halves: an outward choice and an inward ownership. Without the second half, it is only 'pick'; with it, it becomes 'adopt'.","cn":"这个词始终有两半：向外的挑选，和向内的认领。没有后半，它只是“挑”；有了后半，才成为“采用、收养”。"},{"en":"A private adoption changes a family; a public adoption changes a rulebook. The same verb covers both because both mean 'we have taken this as ours'.","cn":"私人的收养改变一个家庭，公共的“通过”改变一本规则手册。同一个动词能覆盖两者，因为两者都意味着“我们把它认作自己的了”。"}]},"examples":[{"en":"The company adopted a four-day workweek for the summer.","cn":"公司在夏季采用了四天工作制。"},{"en":"They adopted their son when he was three.","cn":"他们的儿子三岁时被他们收养。"},{"en":"The city adopted the proposal to plant more trees.","cn":"这座城市通过了多植树的提案。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿多普特”——阿多一把“扑”过去，把流浪猫抱回家 → adopt 收养、采用","word":"adopt"},"root":"源自拉丁语 adoptare“挑选过来归为己有”，ad-“向”+ optare“选择”；核心是“主动挑中并收入自己这一边”。","sensesIntro":{"en":"Ten senses of adopt, all built on one gesture: something outside is chosen, pulled in, and then carried as one's own — a method, a child, an animal, a duty, a name, a belief, a tone, a budget, or a candidate.","cn":"adopt 的十个义项都建立在同一个动作上：从外面挑中一样东西，拉进自己的范围，然后当作自己的来承担——方法、孩子、动物、职责、名字、信念、语气、预算或候选人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand reaches out, chooses one thing, and pulls it into its own circle.","cn":"核心意象：一只手伸出去，挑中一样东西，把它拉进自己的圈子里。"},"chain":["OUTSIDE","CHOOSE","PULL IN","MAKE IT OURS","CARE FOR IT","MAKE IT OFFICIAL"],"branches":[{"senses":"01 · 02 · 09","en":"METHODS AND RULES: a practice or policy is selected from alternatives and made binding inside the group.","cn":"方法与规则：做法或政策从若干选项中选出，并在群体内部取得约束力。"},{"senses":"03 · 04","en":"PEOPLE AND ANIMALS: a child or animal is taken into the family circle and given care and a name.","cn":"人与动物：孩子或动物被带进家庭圈子，得到照料和一个名字。"},{"senses":"05 · 10","en":"ROLES AND CANDIDATES: a person is chosen to carry a duty or a party banner, and the choice becomes public.","cn":"角色与候选人：一个人被选中来承担职责或举起政党旗帜，挑选随之公开。"},{"senses":"06 · 08","en":"NAMES AND TONES: a label or manner is put on like clothing and worn in public.","cn":"名字与语气：标签或举止像衣服一样被穿上，并在公众面前展示。"},{"senses":"07","en":"BELIEFS: an opinion is picked up and held as part of one's own position.","cn":"信念：观点被拾起并握住，成为自己立场的一部分。"}]},"affixes":{"intro":{"en":"adopt is a finished Latin verb in English. The prefix ad- is no longer felt as a living English prefix; the suffixes below attach to the whole verb or to its noun adoption.","cn":"adopt 在英语里是一个已经凝固的拉丁动词。前缀 ad- 已不再被当作活的英语前缀；下面的后缀都附着在整个动词或其名词 adoption 上。"},"latinIntro":{"en":"The Latin family of optare 'choose' is real and productive: option, optional, optative and the rare verb opt all carry the idea of choosing. The deeper origin of optare itself is uncertain.","cn":"optare“选择”的拉丁词族真实存在且能产：option、optional、optative 以及罕用动词 opt 都带着“选择”的意思。optare 本身的更深来源不确定。"},"items":[{"word":"adopted","structure":"adopt + -ed (past participle / adjective)","meaning":"taken in by choice; also used of a country, method or child","meaningCN":"被收养的；被采用的（-ed 构成过去分词或形容词）","example":"The adopted child soon felt at home.","exampleCN":"那个被收养的孩子很快有了家的感觉。"},{"word":"adopting","structure":"adopt + -ing (present participle / gerund)","meaning":"the act of taking something as one's own","meaningCN":"收养；采用（-ing 构成进行体或动名词）","example":"Adopting a new system takes time.","exampleCN":"采用新制度需要时间。"},{"word":"adoption","structure":"adopt + -ion (noun of action)","meaning":"the act or legal process of adopting","meaningCN":"收养；采用；通过（-ion 构成行为名词）","example":"The adoption was finalized in June.","exampleCN":"收养手续在六月办妥。"},{"word":"adoptive","structure":"adopt + -ive (adjective)","meaning":"relating to adoption or an adopted relationship","meaningCN":"收养关系的；采用的（-ive 构成形容词）","example":"She met her adoptive parents at the age of two.","exampleCN":"她两岁时遇到了养父母。"},{"word":"adopter","structure":"adopt + -er (person who does)","meaning":"a person who adopts a child, animal or idea","meaningCN":"收养人；采用者（-er 表示做该动作的人）","example":"The shelter interviews every adopter carefully.","exampleCN":"收容所会认真面试每一位领养人。"},{"word":"adoptee","structure":"adopt + -ee (person who is acted on)","meaning":"a person who has been adopted","meaningCN":"被收养者（-ee 表示动作的承受者）","example":"The adoptee later searched for her birth family.","exampleCN":"这位被收养者后来寻找自己的原生家庭。"},{"word":"adoptable","structure":"adopt + -able (can be ...ed)","meaning":"suitable or available to be adopted","meaningCN":"可收养的；可采用的（-able 表示“能够被……”）","example":"Older dogs are often just as adoptable as puppies.","exampleCN":"年纪大的狗往往和小狗一样适合领养。"},{"word":"adoptability","structure":"adoptable + -ity (quality)","meaning":"the quality of being suitable for adoption","meaningCN":"可收养性；可采用性（-ity 构成性质名词）","example":"The report rated each child's adoptability.","exampleCN":"报告评估了每个孩子的可收养程度。"},{"word":"unadopted","structure":"un- (not) + adopted","meaning":"not yet adopted or formally accepted","meaningCN":"尚未被收养的；尚未被采用的（un- 表示否定）","example":"The plan remains unadopted after two votes.","exampleCN":"两次投票后，该计划仍未获通过。"},{"word":"adoptionism","structure":"adoption + -ism (doctrine or system)","meaning":"a Christian theological view that Jesus was adopted as the Son of God","meaningCN":"收养说（基督教神学观点，认为耶稣被收养为神子）（-ism 表示学说、主义）","example":"Adoptionism was debated in the early church.","exampleCN":"早期教会曾辩论过收养说。"},{"word":"adoptionist","structure":"adoptionism + -ist (person or adherent)","meaning":"a supporter of adoptionism","meaningCN":"收养说信徒（-ist 表示信奉某学说的人）","example":"An adoptionist reading was later rejected as heresy.","exampleCN":"收养说的解读后来被定为异端。"}],"latinEntries":[{"word":"option","structure":"optare 'choose' + -ion","meaning":"a choice or the power to choose","meaningCN":"选项；选择权"},{"word":"optional","structure":"option + -al","meaning":"not required; left to one's choice","meaningCN":"可选的；非强制的"},{"word":"opt","structure":"optare 'choose'","meaning":"to choose or decide; a short verb","meaningCN":"选择；决定（动词 opt）"},{"word":"optative","structure":"optare 'wish' + -ative","meaning":"expressing a wish, especially in grammar","meaningCN":"祈愿的；（语法）祈愿语气"}]}},{"word":"advance","ipa_uk":"/ədˈvɑːns/","ipa_us":"/ədˈvæns/","definition_zh":"前进；推进","definition_en":"to move forward, push something forward, or move an event or payment earlier than usual","core_image":"队伍向前迈出一步，把原来的位置留在身后","scene":"The rescue team advanced slowly through the flooded street, checking every doorway.","sceneCN":"这里 advance 是「向前推进、前进」（第 1 个义项：人或队伍向前移动）；句意：救援队在被淹的街道上缓慢前进，逐一检查每扇门。图中可辨识物件：及膝的水、手电筒、救援队员、被水淹没的门框。","pos":[{"tag":"vi.","zh":"前进；向前移动"},{"tag":"vt.","zh":"推进；促进；提前；预付；提升"},{"tag":"n.","zh":"前进；进步；预付款；（复数）示好、主动表示"}],"collocations":[{"phrase":"advance a plan","zh":"推进一项计划"},{"phrase":"in advance","zh":"提前；预先"},{"phrase":"advance warning","zh":"提前警告"},{"phrase":"advance payment","zh":"预付款"}],"forms":[{"label":"三单（he/she/it，动词）","form":"advances"},{"label":"过去式（已经发生）","form":"advanced"},{"label":"过去分词（完成／被动）","form":"advanced"},{"label":"现在分词（进行体）","form":"advancing"},{"label":"复数（名词）","form":"advances"}],"derivatives":[{"word":"advancement","pos":"n.","zh":"进步；晋升；推进"},{"word":"advanced","pos":"adj.","zh":"先进的；高级的"},{"word":"advancing","pos":"adj.","zh":"前进的；不断发展的"},{"word":"advancer","pos":"n.","zh":"推进者；提出者"}],"senses":[{"no":"01","title":"Move forward in space","titleCN":"向前移动","definition":"to move forward, especially as a person, group, or force","definitionCN":"向前移动，尤指人或队伍向前行进","example":"The rescue team advanced slowly through the flooded street.","exampleCN":"救援队在被淹的街道上缓慢前进。","why":"The Latin base is abante 'from before'. To advance is to move toward what is in front and leave the old position behind.","whyCN":"拉丁语基础是 abante“从前方”。advance 就是朝着前方的目标移动，把原来的位置留在身后。"},{"no":"02","title":"Advance troops or a line","titleCN":"军队或阵线推进","definition":"to move troops or a boundary forward, often against opposition","definitionCN":"使军队或阵线向前推进，常指面对阻力前进","example":"The infantry advanced under cover of darkness.","exampleCN":"步兵在夜色掩护下推进。","why":"When a whole line moves forward, the movement is collective and strategic. The enemy is in front, so the direction is both spatial and military.","whyCN":"当整条阵线向前移动时，动作是集体而有策略的。敌人就在前方，所以这个方向同时是空间上的和军事上的。"},{"no":"03","title":"Push a plan or cause forward","titleCN":"推进计划或事业","definition":"to help a plan, idea, or cause develop or succeed","definitionCN":"帮助计划、想法或事业向前发展并取得成功","example":"The grant advanced the research by several years.","exampleCN":"这笔资助让研究向前推进了好几年。","why":"A plan is imagined as a road. Advancing it means moving it along that road, so abstract progress borrows the same physical step.","whyCN":"计划被想象成一条路。推进计划就是让它在路上往前走，因此抽象的进展借用了同一个物理迈步。"},{"no":"04","title":"Promote someone to a higher rank","titleCN":"提升某人的职位","definition":"to raise someone to a higher rank or position","definitionCN":"把某人提升到更高的级别或职位","example":"After the campaign, he was advanced to captain.","exampleCN":"那场战役之后，他被提升为上尉。","why":"A person who moves up a hierarchy is literally moved forward along a ladder. The spatial step becomes social rank.","whyCN":"在等级体系中往上走的人，确实是在梯子上向前挪了一格。空间上的迈步于是变成了社会等级上的晋升。"},{"no":"05","title":"Move an event to an earlier time","titleCN":"把日程提前","definition":"to change the time of an event so that it happens earlier","definitionCN":"把某个事件的时间改早，使其提前发生","example":"The meeting was advanced from Friday to Tuesday.","exampleCN":"会议从周五提前到了周二。","why":"On a timeline, moving a date forward means bringing it closer. English treats time as a line, so 'earlier' is also 'forward'.","whyCN":"在时间线上，把日期往前移就是让它更靠近现在。英语把时间当成一条线，所以“更早”也说成“向前”。"},{"no":"06","title":"Make progress in knowledge or skill","titleCN":"在知识或技能上进步","definition":"to improve or develop in knowledge, technology, or skill","definitionCN":"在知识、技术或技能上取得进步、向前发展","example":"Medical science has advanced rapidly in this century.","exampleCN":"医学在本世纪发展得很快。","why":"Progress is a movement from a lower or older state to a higher or newer one. The forward step is now measured in understanding, not distance.","whyCN":"进步是从较低、较旧的状态走向更高、更新的状态。这里的“向前一步”衡量的不是距离，而是理解程度。"},{"no":"07","title":"Pay money before it is due","titleCN":"提前付款","definition":"to pay money before the agreed time, or to lend money ahead of need","definitionCN":"在约定时间之前付款，或提前支取、借出款项","example":"The publisher advanced her half the royalty before publication.","exampleCN":"出版方在出版前预付了她一半版税。","why":"Money paid ahead of time is money moved forward on the calendar. The same word covers time and cash because both are being shifted earlier.","whyCN":"提前支付的钱，就是在日历上被向前挪动的钱。同一个词能覆盖时间与现金，因为两者都是被提前了。"},{"no":"08","title":"Noun: forward movement or progress","titleCN":"名词：前进、进步","definition":"a forward movement, or an improvement in a situation","definitionCN":"向前的移动，或局势、事业上的进展","example":"The report describes a major advance in battery technology.","exampleCN":"报告描述了电池技术的一项重大进展。","why":"The noun turns the action into a countable thing. Each advance is one completed step that can be named, measured or reported.","whyCN":"名词把动作变成可计数的事物。每一次 advance 都是一个可以命名、衡量和报告的完整步骤。"},{"no":"09","title":"Noun: money paid ahead of time","titleCN":"名词：预付款","definition":"money paid or lent before the work or sale is completed","definitionCN":"在工作或交易完成之前支付或借出的钱","example":"They asked for an advance of two thousand dollars.","exampleCN":"他们要求预付两千美元。","why":"As a noun, the payment is treated as a thing that has been moved forward in time. It is still money, but its timing has changed.","whyCN":"作名词时，这笔钱被当作“在时间上被提前的东西”。它仍是钱，只是支付时点变了。"},{"no":"10","title":"Advances: friendly or romantic approaches","titleCN":"名词复数：主动示好、追求","definition":"formal or polite attempts to begin a relationship, often romantic","definitionCN":"正式或礼貌地尝试建立关系，常指浪漫追求","example":"She politely rejected his advances.","exampleCN":"她礼貌地拒绝了他的追求。","why":"An advance is a step toward someone. In social life, moving forward means moving closer to another person, so the word becomes an approach.","whyCN":"advance 是朝某人迈出的一步。在社交生活里，向前就是向另一个人靠近，于是这个词变成了“主动接近”。"}],"etymology":{"intro":{"en":"Advance comes from Old French avancier and Late Latin abante 'from before'. The English -d- was inserted in the 16th century by mistake, after the model of Latin ad- words.","cn":"advance 来自古法语 avancier 和晚期拉丁语 abante“从前方”。英语中的 -d- 是 16 世纪仿照拉丁语 ad- 词误加进去的。"},"items":[{"era":"MID-13C.","en":"First recorded as avauncen, transitive, 'improve something, further its development'. The intransitive sense 'move forward' appears by mid-14c.","cn":"最早记录为 avauncen，作及物动词，意为“改善某事、促进其发展”。不及物义“向前移动”到 14 世纪中期出现。"},{"era":"OLD FRENCH","en":"Old French avancir/avancier (12c., Modern French avancer) meant 'move forward, go forward, set forward'. French avant 'before' belongs to the same family.","cn":"古法语 avancir/avancier（12 世纪，现代法语 avancer）意为“向前移动、前进、推进”。法语 avant“在前”属于同一词族。"},{"era":"VULGAR LATIN","en":"The French verb rests on Vulgar Latin *abanteare, from Late Latin abante 'from before'. Abante joins ab 'from' and ante 'before, in front of'.","cn":"法语动词基于通俗拉丁语 *abanteare，再往上为晚期拉丁语 abante“从前方”。abante 由 ab“从”与 ante“在前、在……前面”组成。"},{"era":"LATIN / PIE","en":"Latin ante goes back to PIE *ant- 'front, forehead'. The same root lies behind anterior, anticipate and the French avant.","cn":"拉丁语 ante 可追溯到原始印欧语 *ant-“前面、额头”。anterior、anticipate 和法语 avant 都出自这个词根。"},{"era":"16C.","en":"The unetymological -d- was inserted in the 16th century on the mistaken idea that the first syllable came from Latin ad-. The spelling has kept the error ever since.","cn":"16 世纪时，人们误以为第一个音节来自拉丁语 ad-，于是加进了一个并非词源的 -d-。这个拼写错误此后一直保留。"},{"era":"MODERN ENGLISH","en":"The noun develops from 'advancement in rank' (early 15c.) to 'forward movement' (1670s), 'money paid beforehand' (1680s) and 'friendly approaches' (1706). The adjective in advance warning is recorded from 1843.","cn":"名词从“地位晋升”（15 世纪初）发展到“向前移动”（17 世纪 70 年代）、“预付款”（17 世纪 80 年代）和“主动示好”（1706 年）。advance warning 中的形容词用法记录于 1843 年。"}]},"similar":{"note":{"en":"The first group separates spelling neighbours; the second group separates words that also suggest forward movement or progress.","cn":"第一组区分拼写相近的词；第二组区分同样表达“向前、进展”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advanced","ipa":"/ədˈvɑːnst/","tag":"derived form","definition":"far developed or ahead of others; the past-participle adjective of advance.","definitionCN":"先进的；高级的；advance 的过去分词形容词。"},{"word":"advent","ipa":"/ˈædvənt/","tag":"spelling","definition":"the arrival of an important person or event. It looks close but comes from ad + venire 'come'.","definitionCN":"重要人物或事件的到来。形近但来自 ad + venire“来”。"},{"word":"advice","ipa":"/ədˈvaɪs/","tag":"spelling","definition":"an opinion about what someone should do. It is unrelated in origin despite the shared ad- look.","definitionCN":"建议、意见。虽然也以 ad- 开头，但词源无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"progress","ipa":"/prəˈɡres/","tag":"steady movement","definition":"to move forward or improve over time. It stresses a continuing process rather than a single step.","definitionCN":"持续前进、逐步改善；强调连续过程，而不是迈出一步。"},{"word":"proceed","ipa":"/prəˈsiːd/","tag":"formal continue","definition":"to continue or move on, especially after a pause. It is formal and often procedural.","definitionCN":"继续进行、往下走，尤指停顿之后；偏正式、偏程序。"},{"word":"promote","ipa":"/prəˈməʊt/","tag":"cause or rank","definition":"to help something develop or move someone to a higher position. It focuses on the result of advancement.","definitionCN":"促进发展或提升职位；着眼于推进的结果。"},{"word":"forward","ipa":"/ˈfɔːwəd/","tag":"direction","definition":"toward the front, or to send something on. It is the bare direction word behind advance.","definitionCN":"向前；转发。它是 advance 背后最朴素的方向词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"French avant means 'before', and avant-garde is literally the 'advance guard'.","cn":"法语 avant 意为“在前”，avant-garde 字面就是“前卫、先遣队”。"},{"en":"in advance is the everyday phrase for anything done before the due time.","cn":"in advance 是日常表达“提前”的固定短语。"},{"en":"advance payment and advance warning both use the same 'before' idea.","cn":"advance payment 和 advance warning 都用了同一个“提前”的意思。"},{"en":"advanced technology is technology that has moved further along than the rest.","cn":"advanced technology 就是比别人走得更远的技术。"},{"en":"An advance man in politics travels ahead of a candidate to prepare an event.","cn":"政治中的 advance man 会先于候选人到场，为活动做准备。"}],"abstract":[{"en":"Picture a line of people on a road: the front foot lifts, lands, and the old footprint is left behind. Every sense repeats that one step.","cn":"想象路上的一列人：前脚抬起、落下，旧脚印留在身后。每个义项都在重复这一步。"},{"en":"Time and money can be put on the same line. Moving a date or a payment 'forward' means pulling it closer to now.","cn":"时间和金钱都能放在同一条线上。把日期或付款“向前挪”，就是把它拉近现在。"},{"en":"A career, a research field and an army all climb the same imagined slope; advance is the verb for every climb.","cn":"职业、研究领域和军队都在爬同一座想象中的坡；advance 就是所有“向上走”的动词。"}]},"examples":[{"en":"The army advanced toward the river at dawn.","cn":"军队在黎明时向河边推进。"},{"en":"Could we advance the meeting by one day?","cn":"我们能把会议提前一天吗？"},{"en":"You should book the tickets in advance.","cn":"你应该提前订票。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“额的万斯”——额头上顶着“万”字，还要往前迈 → advance 前进、推进","word":"advance"},"root":"源自拉丁语 abante“从前方”，经古法语 avancier 进入英语；核心是“向前迈、把原位置留在身后”。","sensesIntro":{"en":"Ten senses of advance, all one step forward: an army moves, a plan moves, a date moves, a career moves, money moves, and finally a person moves toward another person.","cn":"advance 的十个义项都是同一步“向前”：军队向前、计划向前、日期向前、职业向前、金钱向前，最后是一个人向另一个人靠近。"},"semanticMap":{"core":{"en":"CORE IMAGE: one foot lifts and lands ahead; the old position is left behind.","cn":"核心意象：一只脚抬起，落在更前方；原来的位置被留在身后。"},"chain":["BEHIND","STEP","MOVE FORWARD","GAIN GROUND","ARRIVE EARLIER","APPROACH"],"branches":[{"senses":"01 · 02","en":"SPACE AND FORCE: a person, line or army physically moves toward the front.","cn":"空间与武力：人、阵线或军队在物理上向前移动。"},{"senses":"03 · 04 · 06","en":"PLANS, RANK AND KNOWLEDGE: progress is a road or ladder, and moving along it is advancement.","cn":"计划、等级与知识：进展被想象成路或梯子，沿着它走就是推进。"},{"senses":"05 · 07 · 09","en":"TIME AND MONEY: a date or payment is pulled closer to the present.","cn":"时间与金钱：日期或款项被拉近现在。"},{"senses":"08","en":"NOUN OF PROGRESS: each completed step becomes a countable advance.","cn":"进展名词：每一个完成的步骤都成为可计数的 advance。"},{"senses":"10","en":"SOCIAL APPROACH: moving toward a person becomes an overture or romantic advance.","cn":"社交接近：朝某人移动，变成主动示好或追求。"}]},"affixes":{"intro":{"en":"advance is a verb and noun with a productive English family. Its compounds mostly keep the literal 'forward' or 'beforehand' meaning.","cn":"advance 兼作动词和名词，在英语中有能产的词族。它的复合词大多保留“向前”或“事先”的字面意思。"},"latinIntro":{"en":"The Latin ante 'before' family is real: anterior, anticipate and ante itself all carry the 'front' idea. The English -d- in advance is not from ad- and is a historical spelling error.","cn":"拉丁语 ante“在前”的词族真实存在：anterior、anticipate 和 ante 本身都带着“前方”的意思。advance 中的英语 -d- 并非来自 ad-，而是历史上的拼写错误。"},"items":[{"word":"advanced","structure":"advance + -ed (past participle / adjective)","meaning":"far ahead in development or level","meaningCN":"先进的；高级的（-ed 构成过去分词或形容词）","example":"The hospital uses advanced imaging equipment.","exampleCN":"这家医院使用先进的成像设备。"},{"word":"advancing","structure":"advance + -ing (present participle / adjective)","meaning":"moving forward or developing","meaningCN":"前进的；不断发展的（-ing 构成进行体或形容词）","example":"The advancing fire forced everyone to leave.","exampleCN":"不断逼近的大火迫使所有人撤离。"},{"word":"advancement","structure":"advance + -ment (noun of action or state)","meaning":"the process of progressing or being promoted","meaningCN":"进步；晋升；推进（-ment 构成行为或状态名词）","example":"She works hard for her own advancement.","exampleCN":"她为自己的晋升而努力工作。"},{"word":"advancer","structure":"advance + -er (person or thing that advances)","meaning":"a person who proposes or pushes something forward","meaningCN":"推进者；提出者（-er 表示做该动作的人或物）","example":"He was an early advancer of the reform.","exampleCN":"他是这场改革的早期推动者。"},{"word":"unadvanced","structure":"un- (not) + advanced","meaning":"not advanced; still at an earlier stage","meaningCN":"未发展的；尚未推进的（un- 表示否定）","example":"The region remains economically unadvanced.","exampleCN":"该地区在经济上仍不发达。"},{"word":"advanceable","structure":"advance + -able (can be ...ed)","meaning":"able to be moved forward or paid ahead","meaningCN":"可提前的；可预付的（-able 表示“能够被……”）","example":"The date is advanceable if the hall is free.","exampleCN":"如果场地空闲，日期可以提前。"},{"word":"advance guard","structure":"advance + guard (compound)","meaning":"the unit that goes ahead of the main force","meaningCN":"先遣队；前卫（advance + guard 复合）","example":"The advance guard reached the bridge first.","exampleCN":"先遣队最先到达桥边。"},{"word":"advance man","structure":"advance + man (compound)","meaning":"a person sent ahead to prepare for a public figure's visit","meaningCN":"先遣人员；打前站的人（advance + man 复合）","example":"The advance man checked every stop on the tour.","exampleCN":"先遣人员检查了巡访的每一站。"},{"word":"advance payment","structure":"advance + payment (compound)","meaning":"money paid before goods or work are delivered","meaningCN":"预付款（advance + payment 复合）","example":"The supplier asks for a 20% advance payment.","exampleCN":"供应商要求支付 20% 的预付款。"},{"word":"advance warning","structure":"advance + warning (compound)","meaning":"a warning given before something happens","meaningCN":"提前警告（advance + warning 复合）","example":"The storm gave us little advance warning.","exampleCN":"这场风暴几乎没有给我们提前警告。"},{"word":"advance directive","structure":"advance + directive (compound)","meaning":"a written statement of medical wishes made before a person becomes unable to decide","meaningCN":"预立医疗指示（advance + directive 复合）","example":"She signed an advance directive before surgery.","exampleCN":"她在手术前签署了预立医疗指示。"}],"latinEntries":[{"word":"ante","structure":"Latin ante 'before, in front of'","meaning":"a prefix or root meaning 'before'","meaningCN":"前缀或词根，表示“在前、在……之前”"},{"word":"anterior","structure":"ante 'before' + -ior (comparative)","meaning":"situated at or toward the front","meaningCN":"前部的；位于前面的"},{"word":"anticipate","structure":"ante 'before' + capere 'take'","meaning":"to take or deal with something before it happens","meaningCN":"预期；提前处理"},{"word":"antique","structure":"ante 'before' + -ique","meaning":"belonging to an earlier period; an old object","meaningCN":"古老的；古董"}]}},{"word":"advantage","ipa_uk":"/ədˈvɑːntɪdʒ/","ipa_us":"/ədˈvæntɪdʒ/","definition_zh":"优势；有利条件","definition_en":"a condition or position that puts someone ahead of others, or a benefit that comes from it","core_image":"站在比别人更靠前的一块高地上，看得更远，出手更早","scene":"With two quiet hours before the exam, Maya had a clear advantage over classmates still stuck in traffic.","sceneCN":"这里 advantage 是「有利条件、优势」（第 3 个义项：任何有利于成功的条件）；句意：考试前有两个安静的钟头，玛雅比还堵在路上的同学有明显优势。图中可辨识物件：摊开的笔记、墙上的钟、窗外堵住的车流、亮着的台灯。","pos":[{"tag":"n.","zh":"优势；有利条件；好处；长处；（网球）占先"},{"tag":"vt.","zh":"（正式、罕用）有利于；使处于有利地位"}],"collocations":[{"phrase":"take advantage of","zh":"利用（机会）；占……的便宜"},{"phrase":"competitive advantage","zh":"竞争优势"},{"phrase":"have the advantage of","zh":"比……有优势"},{"phrase":"to one's advantage","zh":"对某人有利"},{"phrase":"at an advantage","zh":"处于有利地位"}],"forms":[{"label":"复数（名词）","form":"advantages"},{"label":"三单（动词，罕用）","form":"advantages"},{"label":"过去式（动词，罕用）","form":"advantaged"},{"label":"过去分词（动词，罕用）","form":"advantaged"},{"label":"现在分词（动词，罕用）","form":"advantaging"}],"derivatives":[{"word":"advantageous","pos":"adj.","zh":"有利的；有益的"},{"word":"disadvantage","pos":"n./v.","zh":"不利条件；使处于不利地位"},{"word":"advantaged","pos":"adj.","zh":"条件优越的；处于有利地位的"},{"word":"vantage","pos":"n.","zh":"有利位置； vantage point 制高点"}],"senses":[{"no":"01","title":"Position ahead of another","titleCN":"领先的位置","definition":"the position of being physically in front of or ahead of another person or group","definitionCN":"在物理空间上处在别人前面、比别人更靠前的位置","example":"The taller runner held an advantage from the first stride.","exampleCN":"那个更高的跑者从第一步起就占据领先位置。","why":"The earliest recorded meaning, early 14c. avantage, is literally 'position of being in advance of another'. Old French avant means 'before', so the word begins as a fact about bodies on a road, not about feelings or luck.","whyCN":"最早记录的义项（14 世纪初 avantage）字面就是“处在别人前面的位置”。古法语 avant 意为“在前”，所以这个词最初讲的是道路上两具身体的位置，而不是感受或运气。"},{"no":"02","title":"Superiority in a contest","titleCN":"竞争中的上风","definition":"a position of superiority over a rival in a game, election, or struggle","definitionCN":"在比赛、选举或争斗中压过对手的地位","example":"The home team went into the second half with a one-goal advantage.","exampleCN":"主队带着一球领先进入下半场。","why":"Once two people move along the same road, being in front becomes winning. The spatial lead is converted into a score, a seat count, or a margin.","whyCN":"两个人沿同一条路前进时，“在前”就变成“赢”。空间上的领先被换算成分数、席位数或差距。"},{"no":"03","title":"A favorable condition","titleCN":"有利条件、有利因素","definition":"any circumstance that makes success more likely","definitionCN":"任何使成功更有可能发生的外部条件","example":"Living near the library was a real advantage during exam week.","exampleCN":"考试周住在图书馆旁边是实实在在的有利条件。","why":"From the late 15c. the word means 'any condition favorable to success'. The high ground is no longer a place you stand on; it becomes a feature of the situation that lifts you above others.","whyCN":"从 15 世纪末起，这个词表示“任何有利于成功的条件”。高地不再是你站立的地点，而变成了把你抬到别人之上的环境特征。"},{"no":"04","title":"A personal strength","titleCN":"长处、优点","definition":"a quality or skill in a person that makes them stronger than others","definitionCN":"一个人身上使自己比别人更强的品质或技能","example":"Her greatest advantage is that she listens before she speaks.","exampleCN":"她最大的长处是先听完再开口。","why":"A strength is an internal high ground. The comparison stays, but the ground has moved inside the person: a skill, a trait, a habit others do not have.","whyCN":"长处是一座内在的高地。比较仍然存在，但“高地”移到了人身上：一项技能、一种特质、一个别人没有的习惯。"},{"no":"05","title":"Benefit or profit","titleCN":"好处、利益","definition":"a benefit or profit that comes from doing something or from a situation","definitionCN":"因做某事或某种处境而得到的好处、收益","example":"The new bridge brought real advantage to local farmers.","exampleCN":"新桥给当地农民带来了实实在在的好处。","why":"The word shifts from the position to what the position gives you. Being ahead is valuable because it yields goods, time, or money; that yield is also called an advantage.","whyCN":"词义从“位置”转到“位置给你什么”。领先之所以有价值，是因为它能带来货物、时间或金钱；这些收益也被称作 advantage。"},{"no":"06","title":"Take advantage of an opportunity","titleCN":"利用机会","definition":"in the phrase take advantage of, to use a chance or situation for one's own benefit","definitionCN":"在短语 take advantage of 中，指抓住机会或利用某种情况为自己谋利","example":"She took advantage of the free evening to finish her essay.","exampleCN":"她利用这个空闲的晚上把论文写完了。","why":"An advantage is a forward position; to take it is to seize that ground while it is open. The phrase keeps the old military idea of occupying favorable terrain before someone else does.","whyCN":"advantage 是一个靠前的位置；take it 就是在它敞开时抢占这块地。这个短语保留了古老的军事想法：赶在别人之前占据有利地形。"},{"no":"07","title":"Take advantage of a person","titleCN":"占便宜、欺负","definition":"in the phrase take advantage of, to treat someone unfairly for one's own gain","definitionCN":"在短语 take advantage of 中，指为了自己的利益不公平地对待某人","example":"The salesman took advantage of the elderly couple's trust.","exampleCN":"那个销售员利用了这对老夫妇的信任。","why":"The same phrase turns predatory: one person's forward position is now taken from another person's weakness. English uses one phrase for both opportunity and exploitation, and only the object tells you which is meant.","whyCN":"同一个短语转向掠夺性：一个人的“靠前”现在是踩着另一个人的软弱取得的。英语用同一个短语覆盖“利用机会”和“占人便宜”，只有宾语能告诉你是哪一种。"},{"no":"08","title":"Tennis advantage score","titleCN":"网球占先分","definition":"in tennis, the point scored after deuce that puts a player one point from winning the game","definitionCN":"网球中平分之后取得的一分，使球员再得一分即可赢下该局","example":"At advantage, she served wide and won the game.","exampleCN":"在占先时，她发了一个外角球，赢下了这一局。","why":"The score sense appears in the 1640s. In tennis, one point of lead after deuce is exactly 'ahead of your opponent', so the general idea of being one step in front is applied to a countable point.","whyCN":"这个比分义出现在 17 世纪 40 年代。网球中平分后领先一分，正是“比对手靠前”，于是“领先一步”的一般概念被用在一个可数的分数上。"},{"no":"09","title":"Have the advantage of someone","titleCN":"胜过某人、比某人强","definition":"in the phrase have the advantage of, to be in a stronger position than another named person","definitionCN":"在短语 have the advantage of 中，指相对某个具体的人处于更强的位置","example":"As a native speaker, he had the advantage of her in the interview.","exampleCN":"作为母语者，他在面试中比她更有优势。","why":"The phrase is recorded from the 1560s. Here the comparison is explicit: the high ground is measured against one named rival, not against the whole field.","whyCN":"这个短语记录于 16 世纪 60 年代。这里的比较是明确的：高地是相对一个被点名的对手来衡量的，而不是相对整个赛场。"},{"no":"10","title":"Vantage ground","titleCN":"制高点、有利地形","definition":"a place or position that gives a clear view or a strategic lead","definitionCN":"能让人看清全局或取得战略领先的地点、位置","example":"From the ridge, the scouts had the advantage of seeing the whole valley.","exampleCN":"从山脊上，侦察兵占据看得见整个山谷的有利位置。","why":"The oldest image surfaces here: high ground that lets you see and act first. English vantage is advantage with the initial ad- worn away, and both name a commanding position.","whyCN":"这里浮现出最古老的意象：让你先看见、先行动的高地。英语 vantage 是磨掉了开头 ad- 的 advantage，两者都指居高临下的位置。"}],"etymology":{"intro":{"en":"Advantage came into English in the early 14th century from Old French avantage, built on avant 'before'. Its Latin stepping-stone is probably an unrecorded *abantaticum from abante 'from before'; the middle link is not attested, so it is marked uncertain.","cn":"advantage 在 14 世纪初从古法语 avantage 进入英语，其基础是 avant“在前”。它在拉丁语中的中间形态大概是未被记录的 *abantaticum，再往上为 abante“从前方”；这一中间环节没有文献佐证，因此标为存疑。"},"items":[{"era":"EARLY 14C.","en":"First recorded as avantage, 'position of being in advance of another'. The modern spelling with -d- appears later.","cn":"最早记录为 avantage，意为“处在别人前面的位置”。带 -d- 的现代拼写出现得更晚。"},{"era":"OLD FRENCH","en":"Old French avantage (12c.) meant 'advantage, profit; superiority'. It was built on avant 'before', the same word that gives avant-garde its first element.","cn":"古法语 avantage（12 世纪）意为“优势、利益、优越”。它建立在 avant“在前”之上，而 avant-garde 的第一个成分也来自这个词。"},{"era":"LATE / MEDIEVAL LATIN","en":"The French noun probably rests on an unrecorded Late or Medieval Latin *abantaticum, from Late Latin abante 'from before'. Because *abantaticum is reconstructed and never found in a text, this link is source uncertain.","cn":"这个法语名词可能基于一个未被记录的晚期或中世纪拉丁语 *abantaticum，再往上为晚期拉丁语 abante“从前方”。由于 *abantaticum 是重构形式、从未在文献中出现，这一环的来源不确定。"},{"era":"LATIN / PIE","en":"Abante joins ab 'from' and ante 'before, in front of, against'. Latin ante goes back to PIE *ant- 'front, forehead', the same reconstructed root behind anterior and anticipate.","cn":"abante 由 ab“从”与 ante“在前、在……前面、对着”组成。拉丁语 ante 可追溯到原始印欧语 *ant-“前面、额头”，anterior 和 anticipate 背后也是这个重构词根。"},{"era":"16C.","en":"An unetymological -d- was inserted in the 16th century on the analogy of the many English words beginning with Latin ad-. The spelling error stuck, just as it did in advance.","cn":"16 世纪时，人们仿照大量以拉丁语 ad- 开头的英语词，加进了一个并非词源的 -d-。这个拼写错误固定下来，和 advance 的情况一样。"},{"era":"LATE 15C.–MODERN","en":"The sense 'any condition favorable to success' is from the late 15c.; the tennis score sense is from the 1640s; take advantage of is recorded from the late 14c. in both the 'use' and the 'impose upon' meanings.","cn":"“任何有利于成功的条件”这一义项来自 15 世纪末；网球比分义来自 17 世纪 40 年代；take advantage of 从 14 世纪末就有记录，同时具备“利用”和“占便宜”两种意思。"}]},"similar":{"note":{"en":"The first group separates words that share the same Latin ancestry or a similar shape; the second group separates words that also mean a lead or a benefit.","cn":"第一组区分同源或形近的词；第二组区分同样表示“领先、好处”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advance","ipa":"/ədˈvɑːns/","tag":"same family","definition":"to move forward. It shares the Latin abante 'from before' source, but it is the act of moving, while advantage is the position gained.","definitionCN":"前进。它与 advantage 同出拉丁语 abante“从前方”，但 advance 是移动的动作，advantage 是移动后得到的位置。"},{"word":"vantage","ipa":"/ˈvɑːntɪdʒ/","tag":"shortened form","definition":"a better position for seeing or acting; the old word advantage after the first syllable was worn away.","definitionCN":"更有利的观察或行动位置；是 advantage 磨掉开头音节后的旧形式。"},{"word":"adventure","ipa":"/ədˈventʃə/","tag":"spelling","definition":"an unusual or exciting experience. It looks close but comes from Latin adventura 'things about to happen', not from avant.","definitionCN":"冒险；奇遇。形近但来自拉丁语 adventura“即将发生之事”，并非来自 avant。"}]},{"heading":"NEAR MEANING","entries":[{"word":"benefit","ipa":"/ˈbenɪfɪt/","tag":"general good","definition":"a good result or advantage from something. It is the plain, general word for the profit side.","definitionCN":"好处、益处；是表达“收益”一侧最朴素、最通用的词。"},{"word":"edge","ipa":"/edʒ/","tag":"competitive lead","definition":"a small advantage over a rival. It is informal and often used in sport and business.","definitionCN":"微弱优势；比对手强一点，偏口语，常用于体育和商业。"},{"word":"privilege","ipa":"/ˈprɪvəlɪdʒ/","tag":"special right","definition":"a special right or benefit granted to a person or group. It stresses what one is allowed to have, not a lead in a contest.","definitionCN":"特权；特惠。强调被允许拥有什么，而不是在竞争中领先。"},{"word":"upper hand","ipa":"/ˌʌpə ˈhænd/","tag":"idiomatic control","definition":"the position of control or superiority in a situation. It is a phrase, and it stresses power more than benefit.","definitionCN":"上风、控制权；是短语，强调权力胜过强调收益。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"avant in French means 'before', so advantage begins as 'the state of being in front'.","cn":"法语 avant 意为“在前”，所以 advantage 最初就是“处在前面这种状态”。"},{"en":"take advantage of is one phrase with two faces: seize an opening, or exploit a person.","cn":"take advantage of 是同一个短语的两张脸：抓住机会，或占人便宜。"},{"en":"advantage, disadvantage and vantage all descend from the same 'in front' image.","cn":"advantage、disadvantage 和 vantage 都来自同一个“在前”的意象。"},{"en":"advantageous is simply advantage plus -ous, the adjective born in the 1590s.","cn":"advantageous 就是 advantage 加 -ous，这个形容词诞生于 16 世纪 90 年代。"},{"en":"A vantage point is literally a point of advantage: high ground for the eyes.","cn":"vantage point 字面上就是“优势之点”：给眼睛用的高地。"}],"abstract":[{"en":"Picture a hill beside a road. Everyone walks the same road, but the person on the hill sees the bend first and chooses when to move.","cn":"想象路边有一座小山。所有人走同一条路，但站在山上的人先看见拐弯，也能选择何时动身。"},{"en":"The word moves outward from that hill: the hill is a place, then a lead in a game, then any favorable condition, then the profit it produces.","cn":"这个词从这座山向外扩展：山是地点，然后是比赛中的领先，再是任何有利条件，最后是它带来的收益。"},{"en":"Every sense keeps a comparison hidden inside it. There is always someone else lower on the road, even when the sentence never names them.","cn":"每个义项里都藏着一个比较。即使句子里没有点名，路上总有一个位置更低的人。"}]},"examples":[{"en":"Small classes give students a real advantage in discussion.","cn":"小班让学生在讨论中拥有真正的优势。"},{"en":"We took advantage of the quiet morning to finish the report.","cn":"我们利用安静的早晨完成了报告。"},{"en":"The offer is generous, but it works to their advantage, not ours.","cn":"这个报价很慷慨，但对他们有利，不是对我们。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德万泰吉”——阿德万太急，抢先一步站到前面的高地上 → advantage 优势、有利条件","word":"advantage"},"root":"源自拉丁语 abante“从前方”，经古法语 avantage 进入英语，核心是“处在别人前面的位置”；中间的拉丁形态为重构，来源不确定。","sensesIntro":{"en":"Ten senses of advantage, all built on one hill: stand further forward than others, and that forward position becomes a lead, a favorable condition, a strength, a profit, or a chance to be seized.","cn":"advantage 的十个义项都建在同一座小山上：站得比别人靠前，而这个靠前的位置会变成领先、有利条件、长处、收益，或一个可以被抓住的机会。"},"semanticMap":{"core":{"en":"CORE IMAGE: one person stands on higher ground, further along the road than the others.","cn":"核心意象：一个人站在更高的地面上，在路的更前方。"},"chain":["BEHIND","HIGH GROUND","LEAD","FAVORABLE CONDITION","PROFIT","SEIZE THE OPENING"],"branches":[{"senses":"01 · 10","en":"SPACE AND TERRAIN: the original hill — a literal position in front, or high ground that lets you see first.","cn":"空间与地形：最初的小山——字面上处在前面，或让你先看见的高地。"},{"senses":"02 · 08 · 09","en":"MEASURED LEAD: in a contest the forward position becomes a score, a point, or a named comparison with a rival.","cn":"可量化的领先：在竞争中，靠前的位置变成比分、占先分，或与某个对手的明确比较。"},{"senses":"03 · 04","en":"FAVORABLE CONDITIONS: the high ground leaves the road and becomes a circumstance or a personal strength.","cn":"有利条件：高地离开道路，变成一种环境条件，或一个人身上的长处。"},{"senses":"05","en":"PROFIT: what the forward position yields — goods, time, money, benefit.","cn":"收益：靠前的位置所带来的东西——货物、时间、金钱、好处。"},{"senses":"06 · 07","en":"SEIZING: take advantage of either grabs an opening or grabs at a weaker person; one phrase, two moral directions.","cn":"抢占：take advantage of 要么抓住机会，要么向弱者伸手；同一个短语，两种道德方向。"}]},"affixes":{"intro":{"en":"advantage is a noun with a productive English family. Its suffixes build the adjective, adverb and abstract noun; dis- reverses the whole idea.","cn":"advantage 是名词，在英语中有能产的词族。后缀构成形容词、副词和抽象名词；dis- 则把整个意思反过来。"},"latinIntro":{"en":"The Latin family behind the word is ante 'before, in front of', which also gives anterior and anticipate, and abante, which gives advance. The *abantaticum link to advantage itself is reconstructed, not attested.","cn":"这个词背后的拉丁词族是 ante“在前、在……前面”，它也生出 anterior 和 anticipate；abante 则生出 advance。连接 advantage 本身的 *abantaticum 是重构形式，并无文献佐证。"},"items":[{"word":"disadvantageousness","structure":"disadvantageous + -ness (quality)","meaning":"the quality of being disadvantageous or likely to cause harm","meaningCN":"不利性；容易造成损害的性质（-ness 构成性质名词）","example":"The disadvantageousness of the site became clear after the first flood.","exampleCN":"第一次洪水之后，这块场地的不利之处就显露出来了。"},{"word":"advantaged","structure":"advantage + -ed (having the quality)","meaning":"having favorable conditions; often used of social background","meaningCN":"条件优越的；处于有利地位的（-ed 构成形容词）","example":"Children from advantaged homes had more books.","exampleCN":"条件优越家庭的孩子书更多。"},{"word":"advantageous","structure":"advantage + -ous (full of, having)","meaning":"giving an advantage; favorable","meaningCN":"有利的；有益的（-ous 构成“充满、具有”的形容词）","example":"A smaller class is advantageous for discussion.","exampleCN":"小班对讨论更有利。"},{"word":"advantageously","structure":"advantageous + -ly (in a ... manner)","meaning":"in a way that gives an advantage","meaningCN":"有利地；有益地（-ly 构成副词）","example":"The house is advantageously placed near the station.","exampleCN":"这房子位置有利，靠近车站。"},{"word":"advantageousness","structure":"advantageous + -ness (quality noun)","meaning":"the quality of being favorable","meaningCN":"有利性；有益性（-ness 构成性质名词）","example":"They compared the advantageousness of the two sites.","exampleCN":"他们比较了两个选址的有利程度。"},{"word":"disadvantage","structure":"dis- (opposite, away) + advantage","meaning":"an unfavorable condition; to put at a disadvantage","meaningCN":"不利条件；使处于不利地位（dis- 表示相反、取消）","example":"The lack of parking is a disadvantage.","exampleCN":"缺少停车位是一个不利条件。"},{"word":"disadvantaged","structure":"disadvantage + -ed (having the quality)","meaning":"lacking the advantages others have","meaningCN":"处于不利地位的；贫困的（-ed 构成形容词）","example":"The program helps disadvantaged students.","exampleCN":"这个项目帮助处境不利的学生。"},{"word":"disadvantageous","structure":"disadvantage + -ous (full of, having)","meaning":"unfavorable; likely to cause loss","meaningCN":"不利的；有害的（-ous 构成形容词）","example":"The terms were disadvantageous to the buyer.","exampleCN":"这些条款对买方不利。"},{"word":"disadvantageously","structure":"disadvantageous + -ly (in a ... manner)","meaning":"in a way that creates a disadvantage","meaningCN":"不利地（-ly 构成副词）","example":"The treaty was disadvantageously worded for smaller states.","exampleCN":"这份条约的措辞对小国不利。"},{"word":"vantage","structure":"aphetic form of advantage (initial ad- lost)","meaning":"a position that gives a better view or a lead","meaningCN":"有利位置；优势（由 advantage 脱落开头音节而来）","example":"From this vantage we could see the whole field.","exampleCN":"从这个位置我们能看见整片田野。"},{"word":"vantage point","structure":"vantage + point (compound)","meaning":"a place that offers a clear view or a strategic lead","meaningCN":"制高点；有利观察点（vantage + point 复合）","example":"Choose a vantage point before the parade starts.","exampleCN":"游行开始前先选好一个制高点。"}],"latinEntries":[{"word":"antique","structure":"ante 'before' + -ique","meaning":"belonging to an earlier period; an old object","meaningCN":"古老的；古董"},{"word":"anterior","structure":"ante 'before' + -ior (comparative)","meaning":"placed at or toward the front","meaningCN":"前部的；位于前面的"},{"word":"anticipate","structure":"ante 'before' + capere 'take'","meaning":"to take beforehand; to expect","meaningCN":"预期；提前处理"},{"word":"advance","structure":"abante 'from before' via Old French avancier","meaning":"to move forward; a forward step","meaningCN":"前进；推进"}]}},{"word":"adverse","ipa_uk":"/ˈædvɜːs/","ipa_us":"/ædˈvɜːrs/","definition_zh":"不利的；有害的","definition_en":"turned against someone or something, acting in the opposite direction, and usually causing harm","core_image":"一股风从正前方逆向吹来，把人和事往后退","scene":"The drug trial was paused when three patients showed an adverse reaction to the new compound.","sceneCN":"这里 adverse 是「不利的、有害的」（第 5 个义项：医学上的不良反应）；句意：三名患者对新化合物出现不良反应后，药物试验暂停了。图中可辨识物件：病床、输液架、写着 TRIAL PAUSED 的告示、记录副作用的表格。","pos":[{"tag":"adj.","zh":"不利的；有害的；相反的；敌对的；逆向的"}],"collocations":[{"phrase":"adverse effect","zh":"不利影响；副作用"},{"phrase":"adverse reaction","zh":"不良反应"},{"phrase":"adverse conditions","zh":"不利条件"},{"phrase":"adverse weather","zh":"恶劣天气"},{"phrase":"adverse impact","zh":"负面影响"}],"forms":[{"label":"比较级（more）","form":"more adverse"},{"label":"最高级（most）","form":"most adverse"}],"derivatives":[{"word":"adversely","pos":"adv.","zh":"不利地；有害地"},{"word":"adversity","pos":"n.","zh":"逆境；厄运；困难"},{"word":"adversary","pos":"n.","zh":"对手；敌手"},{"word":"adversarial","pos":"adj.","zh":"对抗性的；敌对的"}],"senses":[{"no":"01","title":"Blowing from the opposite direction","titleCN":"逆向的、迎面而来的","definition":"moving or coming from the opposite direction, as a wind or current","definitionCN":"以相反方向移动或迎面而来的，如风、水流","example":"The small boat struggled against an adverse tide.","exampleCN":"小船逆着不利的潮水艰难前行。","why":"Latin adversus is the past participle of advertere 'turn toward'. A wind that has turned toward your face is literally adverse. The physical opposition comes first, before any idea of harm.","whyCN":"拉丁语 adversus 是 advertere“转向”的过去分词。一阵转过来正对你脸的风，字面上就是 adverse。物理上的对立先出现，然后才有“有害”的念头。"},{"no":"02","title":"Unfavorable and harmful","titleCN":"不利的、有害的","definition":"unfavorable and likely to cause harm to a person, plan, or process","definitionCN":"不利的，并可能对人、计划或过程造成损害","example":"Poor sleep has an adverse effect on memory.","exampleCN":"睡眠不足对记忆有不利影响。","why":"What blows against you does not merely block motion; it damages what you are trying to build. The opposition moves from direction to consequence, which is the modern everyday sense.","whyCN":"逆着你吹的东西不只是挡住移动，还会破坏你正在建的东西。对立从方向层面转到后果层面，这就是现代最日常的义项。"},{"no":"03","title":"Contrary to something","titleCN":"与……相反的、相抵触的","definition":"contrary to or opposed to something, especially in formal or legal usage","definitionCN":"与某事物相反或相抵触，尤用于正式或法律语境","example":"Any change adverse to the terms of the contract must be approved in writing.","exampleCN":"任何与合同条款相抵触的变更都必须以书面形式批准。","why":"Here the word names a direction of relation, not yet a harm: one clause is turned against another. This is the oldest 'contrary' sense recorded in late 14c.","whyCN":"这里命名的是一种关系方向，还不是伤害：一条条款“转向”另一条的对立面。这是 14 世纪末记录的最古老“相反”义。"},{"no":"04","title":"Hostile or unfriendly","titleCN":"敌对的、不友善的","definition":"hostile or unfriendly toward a person, group, or proposal","definitionCN":"对某人、某群体或某提议怀有敌意、不友善","example":"The proposal met with adverse criticism from the committee.","exampleCN":"这项提议遭到委员会的敌意批评。","why":"A person who turns against you becomes an opponent. The wind metaphor survives in social life: the attitude of the room blows the other way, and you feel it as resistance.","whyCN":"转过来反对你的人就成了对手。风的比喻在社会生活里延续：全场的态度朝相反方向吹，你感到的是一种阻力。"},{"no":"05","title":"Medical: a harmful reaction","titleCN":"医学：不良反应的","definition":"of a physical reaction, harmful and unwanted, especially to a drug or treatment","definitionCN":"指身体反应有害且非预期，尤指对药物或治疗的反应","example":"Three patients showed an adverse reaction to the compound.","exampleCN":"三名患者对这种化合物出现了不良反应。","why":"Medicine borrowed the word for the body turning against a substance. The reaction is not merely different from the expected one; it works against the patient's own interest.","whyCN":"医学借这个词表示身体对某物质“转过来对抗”。这种反应不只是与预期不同，而是在和病人自身的利益作对。"},{"no":"06","title":"Severe and unfavorable weather","titleCN":"恶劣的天气条件","definition":"of weather or natural conditions, severe and working against travel or work","definitionCN":"指天气或自然条件恶劣，阻碍出行或作业","example":"The flight was delayed by adverse weather over the mountains.","exampleCN":"航班因山区恶劣天气而延误。","why":"Weather is the original outdoor adversary. Adverse weather is not just bad weather; it is weather blowing against the journey, which is why aviation and shipping use the phrase.","whyCN":"天气是最初的户外对手。adverse weather 不只是坏天气，而是逆着行程吹的天气，所以航空和航运特别常用这个说法。"},{"no":"07","title":"Economic conditions working against growth","titleCN":"经济上不利的","definition":"of market or economic conditions, working against growth, balance, or profit","definitionCN":"指市场或经济条件不利于增长、平衡或利润","example":"The company warned of adverse market conditions next quarter.","exampleCN":"公司警告下个季度市场条件不利。","why":"Markets are imagined as currents. An adverse trend is a current running against the business, pushing profit down even when the firm has done nothing wrong.","whyCN":"市场被想象成水流。adverse trend 就是逆着企业流动的水，即使公司本身没做错什么，也会把利润往下压。"},{"no":"08","title":"Legal: unfavorable to one party","titleCN":"法律：对一方不利的","definition":"of a court ruling, finding, or inference, unfavorable to one party in a case","definitionCN":"指法院裁决、认定或推定对案件中的一方不利","example":"The insurer appealed against the adverse ruling.","exampleCN":"保险公司对这项不利裁决提出上诉。","why":"A ruling that turns toward the other side takes ground from you. Legal usage keeps the old spatial, zero-sum feel: what one party gains, the other loses.","whyCN":"一项“转向”对方的裁决，就是从你这边拿走地盘。法律用法保留了古老的、零和的空间感：一方得到的，正是另一方失去的。"},{"no":"09","title":"Unfriendly fate or fortune","titleCN":"不吉利的、厄运的","definition":"of fate or fortune, unfriendly and bringing misfortune","definitionCN":"指命运不友善、带来厄运","example":"He blamed adverse fortune for the failure of his shop.","exampleCN":"他把店铺的失败归咎于厄运。","why":"Fortune was once pictured as a force that could turn its face toward you or away. Adverse fortune has turned its hostile face toward the shop; the wind image returns as fate.","whyCN":"命运曾被想象成一股力量，可以把脸转向你，也可以转开。adverse fortune 就是把敌意的脸转向了这家店；风的意象在这里化成了命运。"}],"etymology":{"intro":{"en":"Adverse entered English in the late 14th century from Old French advers, earlier avers, and ultimately from Latin adversus, the past participle of advertere 'to turn toward'. Its core is not 'bad' but 'turned against'.","cn":"adverse 在 14 世纪末从古法语 advers（更早写作 avers）进入英语，最终来自拉丁语 adversus，即 advertere“转向”的过去分词。它的核心不是“坏”，而是“转过来对抗”。"},"items":[{"era":"LATE 14C.","en":"First recorded as 'contrary, opposing'. The word arrives through French in the language of argument and opposition, not yet as a general word for harm.","cn":"最早记录为“相反的、对立的”。这个词经法语进入英语，最初用于论辩和对立语境，还不是泛指“有害”。"},{"era":"OLD FRENCH","en":"Old French advers, earlier avers (13c., Modern French adverse), meant 'antagonistic, unfriendly, contrary, foreign'. The earlier form had no -d-, exactly like averse.","cn":"古法语 advers，更早写作 avers（13 世纪，现代法语 adverse），意为“敌对的、不友善的、相反的、外来的”。更早的形式没有 -d-，和 averse 一样。"},{"era":"LATIN","en":"Latin adversus meant 'turned against, turned toward, fronting, facing', and figuratively 'hostile, adverse, unfavorable'. It is the past participle of advertere 'to turn toward', from ad- 'to' and vertere 'to turn'.","cn":"拉丁语 adversus 意为“转向对立面、朝向、面对”，引申为“敌对的、不利的”。它是 advertere“转向”的过去分词，由 ad-“向”与 vertere“转”组成。"},{"era":"PIE","en":"Latin vertere goes back to PIE *wer- (2) 'to turn, bend', a reconstructed root. The same root is generally considered to lie behind versus, reverse and convert; reconstructed roots are not directly attested.","cn":"拉丁语 vertere 可追溯到原始印欧语 *wer-（第 2 条）“转、弯”，这是一个重构词根。一般认为 versus、reverse 和 convert 背后也是这个词根；重构词根没有直接文献记录。"},{"era":"16C.–19C.","en":"Adverse and averse split by prefix and by use: adverse (ad- 'toward') is turned against and applies to action and conditions; averse (ab- 'away') is turned away in feeling and applies to a person's dislike. The Century Dictionary (1906) states the rule as 'averse to feeling, adverse to action'.","cn":"adverse 与 averse 按前缀和用法分工：adverse（ad-“向”）是转过来对抗，用于行动和条件；averse（ab-“离开”）是心里转开，用于人的厌恶。1906 年的 Century Dictionary 把规则概括为“averse 管感受，adverse 管行动”。"},{"era":"MODERN ENGLISH","en":"Modern English fixes the strong collocations: adverse effect, adverse reaction, adverse conditions, adverse weather, adverse ruling. The noun adversity, from the same Latin stem, is the state of being under hostile fortune.","cn":"现代英语固定了强势搭配：adverse effect、adverse reaction、adverse conditions、adverse weather、adverse ruling。同出这一拉丁词干的名词 adversity，指身处敌意命运之下的状态。"}]},"similar":{"note":{"en":"The first group separates one-letter and one-prefix neighbours; the second group separates words that also mean bad, opposed, or harmful.","cn":"第一组区分只差一个字母或一个前缀的近邻；第二组区分同样表示“不好、对立、有害”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"averse","ipa":"/əˈvɜːs/","tag":"prefix contrast","definition":"unwilling or disliking something, used of a person's feeling. It comes from ab- 'away' plus vertere, the exact opposite prefix to adverse.","definitionCN":"不愿意、厌恶，用于人的感受。它来自 ab-“离开”加 vertere，前缀与 adverse 正相反。"},{"word":"advert","ipa":"/ədˈvɜːt/","tag":"spelling","definition":"to refer to something, mostly in British formal writing. It is a verb and has no 'bad' meaning at all.","definitionCN":"提及、谈到，多见于英式正式书面语。它是动词，完全没有“坏”的意思。"},{"word":"adversity","ipa":"/ədˈvɜːsəti/","tag":"derived form","definition":"a state of misfortune or hardship. It is the noun built on the same Latin stem, not a synonym of adverse.","definitionCN":"逆境、厄运、困难。它是同一拉丁词干构成的名词，不是 adverse 的同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unfavorable","ipa":"/ʌnˈfeɪvərəbl/","tag":"neutral judgement","definition":"not helping success. It is the plain negative of favorable and can describe conditions without implying active hostility.","definitionCN":"不利的；不帮助成功的。它只是 favorable 的否定形式，可描述条件，不暗示主动敌意。"},{"word":"hostile","ipa":"/ˈhɒstaɪl/","tag":"active enmity","definition":"actively unfriendly or opposed, often with a will to harm. It is stronger and more personal than adverse.","definitionCN":"敌对的、怀有敌意的，常带有伤害的意愿；比 adverse 更强、更针对人。"},{"word":"harmful","ipa":"/ˈhɑːmfl/","tag":"damage","definition":"causing damage or injury. It points straight at the effect and says nothing about direction or opposition.","definitionCN":"有害的；造成损害的。它直接指向后果，不涉及方向或对立。"},{"word":"contrary","ipa":"/ˈkɒntrəri/","tag":"logical opposition","definition":"opposite in fact or direction. It is the neutral logical word for two things pointing against each other.","definitionCN":"相反的；在事实或方向上对立的。它是表达两物相向对立的中立逻辑词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"adverse is ad- 'toward' plus vers- 'turn': something turned toward you as an enemy.","cn":"adverse 是 ad-“向”加 vers-“转”：转过来、以敌人的姿态对着你。"},{"en":"averse is ab- 'away' plus vers- 'turn': a feeling turned away in dislike. One letter, opposite direction.","cn":"averse 是 ab-“离开”加 vers-“转”：因厌恶而转开的感受。差一个字母，方向相反。"},{"en":"adversity is the noun for the hard times produced by adverse fortune.","cn":"adversity 是名词，指 adverse fortune 造成的艰难时期。"},{"en":"adversary and adversarial share the same 'turn against' stem, so an opponent is literally one who faces you.","cn":"adversary 和 adversarial 共享同一个“转过来对抗”的词干，所以对手字面上就是“面对你的人”。"},{"en":"adverse reaction and adverse effect are the two fixed phrases of medicine and science.","cn":"adverse reaction 和 adverse effect 是医学与科学里的两个固定搭配。"}],"abstract":[{"en":"Picture the wind turning a weather vane until it points straight at your face. That turn is the whole word.","cn":"想象风把风向标转过来，直到它直指你的脸。这个“转”，就是这个词的全部。"},{"en":"Adverse is relational before it is evaluative: first something is turned against you, then it hurts you. Modern English often skips to the hurt, but the direction is still inside the word.","cn":"adverse 先表关系，再表评价：先有东西转过来对着你，然后才伤害你。现代英语常直接跳到“伤害”，但方向仍藏在词里。"},{"en":"Because the core is 'against', the word fits wind, tides, rulings, markets and fate alike: all are forces with a direction, all can turn the wrong way.","cn":"因为核心是“对着”，这个词能同时装下风、潮水、裁决、市场和命运：它们都是有方向的力量，都可能转向错误的一边。"}]},"examples":[{"en":"The medicine may cause adverse effects in older patients.","cn":"这种药可能在老年患者身上引起不良反应。"},{"en":"They set off despite adverse weather conditions.","cn":"尽管天气条件恶劣，他们还是出发了。"},{"en":"The judge's ruling was adverse to the company.","cn":"法官的裁决对公司不利。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德沃斯”——阿德沃斯逆着风走，越走越不顺 → adverse 不利的、逆向的","word":"adverse"},"root":"源自拉丁语 adversus“转过来对着”，是 advertere“转向”的过去分词，ad-“向”+ vertere“转”；核心是“逆着、对着”。","sensesIntro":{"en":"Nine senses of adverse, all one motion: something turns toward you and blows the wrong way — a wind, a reaction, a ruling, a market, or fate.","cn":"adverse 的九个义项都是同一个动作：有东西转过来对着你，朝错误的方向吹——风、反应、裁决、市场或命运。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wind turns until it blows straight against your face.","cn":"核心意象：一阵风转过来，直直地逆着你的脸吹。"},"chain":["SAME DIRECTION","TURN","TURN AGAINST","RESIST","HARM","MISFORTUNE"],"branches":[{"senses":"01 · 06","en":"PHYSICAL OPPOSITION: wind, tide and weather are the literal forces blowing against a journey.","cn":"物理对立：风、潮水和天气是字面上逆着行程的力量。"},{"senses":"02 · 05","en":"HARM: what blows against you damages the body, the plan, or the treatment.","cn":"伤害：逆着你吹的东西损害身体、计划或治疗。"},{"senses":"03 · 08","en":"FORMAL OPPOSITION: a clause, a ruling, or an inference is turned against the other side in law and argument.","cn":"正式对立：在法律与论辩中，条款、裁决或推定转向另一方。"},{"senses":"04 · 09","en":"HOSTILITY: a person or fate turns a hostile face toward you.","cn":"敌意：人或命运把敌意的脸转向你。"},{"senses":"07","en":"ECONOMIC CURRENT: the market is a current running against growth and profit.","cn":"经济水流：市场是一股逆着增长与利润流动的水。"}]},"affixes":{"intro":{"en":"adverse is an adjective, and its family is built with adverbs, abstract nouns, and agent nouns. The prefix ad- 'toward' is the key to its difference from averse.","cn":"adverse 是形容词，其词族由副词、抽象名词和施动名词构成。前缀 ad-“向”是它区别于 averse 的关键。"},"latinIntro":{"en":"The Latin family of vertere 'to turn' is large and real: versus, reverse, convert and versatile all come from it. The PIE root *wer- is reconstructed, so the deepest link is generally accepted rather than documented.","cn":"拉丁语 vertere“转”的词族庞大而真实：versus、reverse、convert、versatile 都出自它。原始印欧语词根 *wer- 是重构形式，所以最深的联系是“一般认为是”，而不是有文献直接证明。"},"items":[{"word":"adverse event","structure":"adverse + event (compound)","meaning":"an unwanted medical occurrence during a treatment or trial","meaningCN":"不良事件（治疗或试验中出现的不希望发生的医学情况）","example":"The trial paused after three adverse events.","exampleCN":"出现三起不良事件后，试验暂停了。"},{"word":"adversely","structure":"adverse + -ly (in a ... manner)","meaning":"in a harmful or unfavorable way","meaningCN":"不利地；有害地（-ly 构成副词）","example":"The crop was adversely affected by frost.","exampleCN":"庄稼受到霜冻的不利影响。"},{"word":"adverseness","structure":"adverse + -ness (quality noun)","meaning":"the quality of being opposed or unfavorable","meaningCN":"相反性；不利性（-ness 构成性质名词）","example":"The adverseness of the climate shaped the village.","exampleCN":"气候的恶劣塑造了这个村庄。"},{"word":"adversity","structure":"adversus 'turned against' + -ity (state noun)","meaning":"a state of hardship or misfortune","meaningCN":"逆境；厄运（-ity 构成状态名词）","example":"She stayed calm in the face of adversity.","exampleCN":"面对逆境她保持冷静。"},{"word":"adversary","structure":"adversus 'turned against' + -ary (person)","meaning":"an opponent or enemy","meaningCN":"对手；敌手（-ary 表示人）","example":"He respected his old adversary.","exampleCN":"他敬重自己的老对手。"},{"word":"adversarial","structure":"adversary + -al (relating to)","meaning":"based on opposition or conflict","meaningCN":"对抗性的（-al 构成关系形容词）","example":"The two sides took an adversarial stance.","exampleCN":"双方采取了对抗姿态。"},{"word":"adversative","structure":"adversus + -ative (tending to)","meaning":"expressing contrast or opposition, as in grammar","meaningCN":"表示转折或对立的（-ative 构成倾向形容词）","example":"But and however are adversative conjunctions.","exampleCN":"but 和 however 是转折连词。"},{"word":"adversatively","structure":"adversative + -ly (in a ... manner)","meaning":"in a way that marks contrast","meaningCN":"以转折、对立的方式（-ly 构成副词）","example":"The clause was joined adversatively.","exampleCN":"这个分句是用转折方式连接的。"},{"word":"averse","structure":"ab- 'away' + vers- 'turn' + -e","meaning":"turned away in feeling; unwilling","meaningCN":"厌恶的；不愿意的（ab- 表示“离开”，与 adverse 方向相反）","example":"She is averse to risk.","exampleCN":"她不喜欢冒险。"},{"word":"aversion","structure":"averse + -ion (noun of state)","meaning":"a strong dislike","meaningCN":"厌恶；反感（-ion 构成状态名词）","example":"He has a strong aversion to noise.","exampleCN":"他非常讨厌噪音。"},{"word":"adverse possession","structure":"adverse + possession (legal compound)","meaning":"a doctrine by which long occupation of another's land can confer ownership","meaningCN":"逆权占有；时效取得（adverse + possession 法律复合词）","example":"The claim rested on adverse possession.","exampleCN":"这项主张依据的是逆权占有。"}],"latinEntries":[{"word":"versus","structure":"vertere 'turn' (past participle versus)","meaning":"turned toward; against","meaningCN":"转向；对着；对抗"},{"word":"reverse","structure":"re- 'back' + vertere 'turn'","meaning":"to turn backward; the opposite","meaningCN":"反转；相反的"},{"word":"convert","structure":"con- 'with, completely' + vertere 'turn'","meaning":"to turn around; to change form","meaningCN":"转变；转换"},{"word":"versatile","structure":"versare 'turn often' + -ile","meaning":"able to turn easily to many uses","meaningCN":"多才多艺的；多用途的"}]}},{"word":"advocate","ipa_uk":"/ˈædvəkət/ (n.) · /ˈædvəkeɪt/ (v.)","ipa_us":"/ˈædvəkət/ (n.) · /ˈædvəkeɪt/ (v.)","definition_zh":"提倡；拥护者","definition_en":"to speak publicly in support of a person, cause, or policy; also a person who does this, or a lawyer who pleads in court","core_image":"站出来，用自己的声音把某个人或某件事拉到众人面前","scene":"At the school board meeting, parent after parent advocated for a later start time.","sceneCN":"这里 advocate 是「公开提倡、为……争取」（第 5 个义项：在正式场合主张某项措施）；句意：在学校董事会上，家长们一个接一个为推迟上课时间发声。图中可辨识物件：麦克风、发言名单、举起的日程表、写着 8:30 START 的牌子。","pos":[{"tag":"vt.","zh":"提倡；拥护；主张；为……辩护"},{"tag":"n.","zh":"拥护者；倡导者；代言人；辩护律师"}],"collocations":[{"phrase":"advocate for","zh":"为……争取；为……发声"},{"phrase":"a strong advocate of","zh":"……的坚定拥护者"},{"phrase":"advocate a policy","zh":"主张一项政策"},{"phrase":"devil's advocate","zh":"唱反调的人；故意唱反调者"},{"phrase":"patient advocate","zh":"病人代言人；患者维权者"}],"forms":[{"label":"复数（名词）／三单（动词）","form":"advocates"},{"label":"过去式（动词）","form":"advocated"},{"label":"过去分词（动词）","form":"advocated"},{"label":"现在分词（动词）","form":"advocating"}],"derivatives":[{"word":"advocacy","pos":"n.","zh":"拥护；提倡；倡导活动"},{"word":"advocator","pos":"n.","zh":"提倡者；拥护者（较罕用）"},{"word":"advocative","pos":"adj.","zh":"拥护的；提倡的（较罕用）"},{"word":"advocatory","pos":"adj.","zh":"辩护的；倡导的（较罕用）"}],"senses":[{"no":"01","title":"A public supporter of a cause","titleCN":"拥护者、提倡者","definition":"a person who publicly supports a cause, idea, or policy","definitionCN":"公开支持某项事业、观点或政策的人","example":"She has been an advocate of clean energy for twenty years.","exampleCN":"二十年来她一直是清洁能源的拥护者。","why":"Latin advocatus means 'one called to aid'. The noun begins as a person summoned to stand beside someone. A supporter is exactly that: the one who shows up when a cause needs a voice.","whyCN":"拉丁语 advocatus 意为“被召来相助的人”。这个名词最初指被叫到某人身边站着的人。拥护者正是这样：当某项事业需要声音时，他到场。"},{"no":"02","title":"A voice for a voiceless group","titleCN":"代言人、维权者","definition":"a person who speaks on behalf of a group that cannot easily speak for itself","definitionCN":"为难以自行发声的群体说话的人","example":"The patient advocate helped her understand the treatment options.","exampleCN":"病人代言人帮助她理解了各种治疗方案。","why":"The 'called to aid' person moves beside the weak. The advocate does not replace the patient's voice but lends it strength, which is why hospitals and charities create such roles.","whyCN":"“被召来相助”的人来到弱者身边。代言人不替代当事人的声音，而是把自己的力气借给它，所以医院和慈善机构会设立这样的岗位。"},{"no":"03","title":"A lawyer who pleads in court","titleCN":"辩护律师、出庭律师","definition":"a lawyer who pleads a case in court, especially in Scotland or in certain maritime courts","definitionCN":"在法庭上为案件辩护的律师，尤见于苏格兰或某些海事法庭","example":"The advocate rose to cross-examine the witness.","exampleCN":"辩护律师起身交叉询问证人。","why":"This is the oldest English sense, taken from Roman law: the person called to speak for the accused. The courtroom is where 'speaking for someone' became a paid profession.","whyCN":"这是英语里最古老的义项，来自罗马法：被召来为被告说话的人。法庭正是“替人说话”变成受薪职业的地方。"},{"no":"04","title":"Recommend an idea publicly","titleCN":"公开提倡某种观念","definition":"to publicly recommend or support an idea or cause","definitionCN":"公开推荐或支持某种观念、事业","example":"The report advocates a shorter working week.","exampleCN":"这份报告提倡更短的工作周。","why":"The verb is recorded from the 1640s and was made from the noun. To be an advocate is to do what an advocate does: speak for something in front of other people.","whyCN":"动词记录于 17 世纪 40 年代，由名词转来。做 advocate，就是做拥护者做的事：在众人面前为某事物说话。"},{"no":"05","title":"Argue for a specific measure","titleCN":"主张采取某项措施","definition":"to argue in an official setting that a particular measure or policy should be adopted","definitionCN":"在正式场合论证某项措施或政策应当被采纳","example":"The committee advocated raising the minimum wage.","exampleCN":"委员会主张提高最低工资。","why":"Inside a formal body, support has to be argued into a decision. The word carries the procedural weight of a motion being pushed, not just a warm feeling about a cause.","whyCN":"在正式机构里，支持必须被论证成一项决定。这个词带着“推动一项动议”的程序分量，而不只是对某项事业的好感。"},{"no":"06","title":"Plead for a person","titleCN":"为某人辩护、替人说话","definition":"to plead or argue on behalf of a person, especially one facing accusation","definitionCN":"代表某人辩护或论证，尤指为面临指控的人","example":"Several neighbours advocated for the family at the hearing.","exampleCN":"几位邻居在听证会上为这家人说话。","why":"Here the object is a person, not a policy. The advocate stands between the accused and the judgment and takes the blows of argument on their behalf.","whyCN":"这里宾语是人，不是政策。辩护人站在被告与判决之间，替他们承受论辩的冲击。"},{"no":"07","title":"Argue a case in writing","titleCN":"在文章、报告中主张","definition":"of a book, report, or speech, to recommend a course of action","definitionCN":"指书籍、报告或演讲推荐某种行动方向","example":"The closing chapter advocates treating soil as a living system.","exampleCN":"最后一章主张把土壤当作活的系统来对待。","why":"A text can advocate too. The voice is written rather than spoken, but the direction is the same: it puts itself behind one option and against another.","whyCN":"文本也可以 advocate。声音是写下的而不是说出的，但方向相同：它把自己放在一个选项后面，与另一个选项对立。"},{"no":"08","title":"A defender of a doctrine","titleCN":"主张者、信奉者","definition":"a person who holds and defends a particular doctrine or system","definitionCN":"持有并捍卫某种学说或制度的人","example":"He is a lifelong advocate of free trade.","exampleCN":"他一生都是自由贸易的主张者。","why":"This narrows the supporter to a doctrine. The person is identified by the position they keep defending, almost as a title: advocate of free trade, advocate of reform.","whyCN":"这里把拥护者收窄到某种学说。这个人由他反复捍卫的立场来定义，几乎成了一个头衔：自由贸易的拥护者、改革的主张者。"},{"no":"09","title":"Campaign for rights or resources","titleCN":"为权利或资源奔走争取","definition":"to campaign actively for rights, funding, or recognition on behalf of a group","definitionCN":"代表某个群体积极争取权利、资金或认可","example":"The union has long advocated for safer night shifts.","exampleCN":"工会长期以来一直在为更安全的夜班争取。","why":"With for, the verb becomes a sustained campaign rather than a single opinion. It is the everyday modern use, closest to lobbying and activism.","whyCN":"与 for 连用时，动词变成持续的行动，而不是一次性的意见。这是现代最日常的用法，最接近游说与行动主义。"}],"etymology":{"intro":{"en":"Advocate came into English in the mid-14th century as a Roman-law term for the person who pleads a case, through Old French avocat from Latin advocatus 'one called to aid'. The verb is a 17th-century back-formation from the noun.","cn":"advocate 在 14 世纪中期作为罗马法术语进入英语，指在法庭上为案件辩护的人，经古法语 avocat 来自拉丁语 advocatus“被召来相助的人”。动词则是 17 世纪由名词转成。"},"items":[{"era":"MID-14C.","en":"First recorded as a noun meaning 'one whose profession is to plead cases in a court of justice', a technical term from Roman law. Middle English also used it for 'one who intercedes for another' and 'protector, champion, patron'.","cn":"最早记录为名词，意为“以在法庭上为案件辩护为职业的人”，是来自罗马法的专业术语。中世纪英语也用它表示“为他人求情的人”和“保护者、拥护者、赞助人”。"},{"era":"OLD FRENCH","en":"Old French avocat (13c.) meant 'barrister, advocate, spokesman'. It is the direct source of the English noun, and the French form lacks the Latin -d-.","cn":"古法语 avocat（13 世纪）意为“出庭律师、辩护人、代言人”。它是英语名词的直接来源，法语形式中没有拉丁语的 -d-。"},{"era":"LATIN","en":"Latin advocatus is the noun use of the past participle of advocare 'to call (as witness or adviser), summon, invite; call to aid; invoke'. It joins ad- 'to' and vocare 'to call'.","cn":"拉丁语 advocatus 是 advocare 过去分词的名词化用法；advocare 意为“召（作证人或顾问）、传唤、邀请、召来相助、祈求”。它由 ad-“向”与 vocare“叫”组成。"},{"era":"PIE","en":"Latin vocare is related to vox (genitive vocis) 'voice'. The usual reconstruction traces both to PIE *wekw- 'to speak', a reconstructed root; the connection is generally accepted rather than directly attested.","cn":"拉丁语 vocare 与 vox（属格 vocis）“声音”同源。通常的重构把两者都追溯到原始印欧语 *wekw-“说话”，这是一个重构词根；这一联系是“一般认为是”，而非有直接文献证明。"},{"era":"15C.–17C.","en":"Feminine forms advocatess and advocatrice were used in the 15c.; advocatrix appears in the 17c. Old English had glossed Latin advocatus with þingere, literally a speaker at an assembly.","cn":"15 世纪使用过阴性形式 advocatess 和 advocatrice；advocatrix 出现在 17 世纪。古英语曾用 þingere 注释拉丁语 advocatus，字面是“在集会上说话的人”。"},{"era":"1640S–MODERN","en":"The verb 'plead in favor of' is recorded from the 1640s, formed from the noun or directly from Latin advocatus. Modern English keeps both halves: the courtroom lawyer and the public campaigner, united by one act — speaking for someone else.","cn":"动词“为……辩护、主张”记录于 17 世纪 40 年代，由名词构成，或直接来自拉丁语 advocatus。现代英语保留了两半：法庭律师与公共倡导者，都由同一个动作统一起来——替别人说话。"}]},"similar":{"note":{"en":"The first group separates words built on the same 'call' root or a similar shape; the second group separates words that also mean support or recommend.","cn":"第一组区分同出“叫”词根或形近的词；第二组区分同样表示“支持、推荐”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advocacy","ipa":"/ˈædvəkəsi/","tag":"derived form","definition":"the act of publicly supporting a cause. It is the noun of action from advocate, recorded from the late 14c.","definitionCN":"公开支持某项事业的行为。它是 advocate 的行为名词，记录于 14 世纪末。"},{"word":"avocation","ipa":"/ˌævəˈkeɪʃn/","tag":"different prefix","definition":"a hobby or secondary occupation. It comes from ab- 'away' plus vocare 'call' — something that calls you away from your main work.","definitionCN":"业余爱好；副业。它来自 ab-“离开”加 vocare“叫”——把你从主业叫开的事。"},{"word":"vocation","ipa":"/vəʊˈkeɪʃn/","tag":"same root","definition":"a strong feeling of suitability for a career, or the career itself. It is from vocare 'call', a calling rather than a supporting.","definitionCN":"职业使命感；职业。它来自 vocare“叫”，是一种“被召唤”，而不是“去支持”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"champion","ipa":"/ˈtʃæmpiən/","tag":"active defence","definition":"to fight publicly for a cause or a person. It is warmer and more heroic than advocate.","definitionCN":"公开为某项事业或某人而战；比 advocate 更热血、更英雄化。"},{"word":"supporter","ipa":"/səˈpɔːtə/","tag":"general backing","definition":"a person who backs a team, party, or idea. It is the broad, neutral word and need not imply public speech.","definitionCN":"支持者；拥护者。它是最宽泛中性的词，不必包含公开讲话。"},{"word":"promote","ipa":"/prəˈməʊt/","tag":"cause advancement","definition":"to help something develop or become accepted. It stresses pushing the thing forward rather than speaking for it.","definitionCN":"促进；推广。强调把事情往前推，而不是替它发声。"},{"word":"endorse","ipa":"/ɪnˈdɔːs/","tag":"formal approval","definition":"to state publicly that you approve of something, often in an official or commercial way.","definitionCN":"公开赞同、背书；常带官方或商业色彩。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"advocate is ad- 'to' plus vocare 'call', literally 'called to someone's side'.","cn":"advocate 是 ad-“向”加 vocare“叫”，字面就是“被叫到某人身边”。"},{"en":"advocacy is the noun of action, and the pair advocate / advocacy mirrors the verb / noun split.","cn":"advocacy 是行为名词，advocate / advocacy 正好对应动词与名词的分工。"},{"en":"devil's advocate began as an official church role: a person appointed to argue against a canonization.","cn":"devil's advocate 最初是教会正式角色：被指派去反对封圣的人。"},{"en":"advocate for is the modern campaign pattern; advocate a policy is the formal proposal pattern.","cn":"advocate for 是现代“奔走争取”的搭配；advocate a policy 是正式“主张政策”的搭配。"},{"en":"vocation and avocation share vocare 'call', showing that the root is about a voice, not a vote.","cn":"vocation 和 avocation 都共享 vocare“叫”，说明这个词根关乎声音，而不是投票。"}],"abstract":[{"en":"Picture a courtroom: one person stands up, and the accused sits silent behind. The standing figure borrows the room's attention and spends it on someone else.","cn":"想象一间法庭：一个人站起来，被告沉默地坐在他身后。站着的人借来全场的注意力，并把它花在别人身上。"},{"en":"The word keeps that geometry in every sense: a voice is moved from the margin to the centre, whether the cause is a patient, a law, or an idea.","cn":"这个词在每个义项里都保留这个几何关系：声音从边缘被移到中心，无论对象是病人、法律还是观念。"},{"en":"Advocacy is not neutral description; it is deliberately one-sided. To advocate is to place your voice on one side of an argument and leave it there.","cn":"倡导不是中立的描述，而是有意偏向一方。advocate 就是把你的声音放在论辩的某一边，并让它留在那里。"}]},"examples":[{"en":"She has advocated for better mental health services for years.","cn":"多年来她一直在为更好的心理健康服务奔走。"},{"en":"The author advocates a simpler, slower way of life.","cn":"作者提倡一种更简单、更缓慢的生活方式。"},{"en":"He played devil's advocate to test the plan.","cn":"他故意唱反调来检验这个计划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德沃凯特”——阿德为沃凯特站台，大声呼吁 → advocate 提倡、拥护者","word":"advocate"},"root":"源自拉丁语 advocatus“被召来相助的人”，advocare = ad-“向”+ vocare“叫”，与 vox“声音”同源；核心是“被叫到某人身边，替他发声”。","sensesIntro":{"en":"Nine senses of advocate, all one act: a voice is called to someone's side and speaks in public — for a cause, a policy, an accused person, a patient, or a doctrine.","cn":"advocate 的九个义项都是同一个动作：一个声音被叫到某人身边，并公开说话——为一项事业、一项政策、一个被告、一位病人，或一种学说。"},"semanticMap":{"core":{"en":"CORE IMAGE: someone is called to stand beside another and speak with a public voice.","cn":"核心意象：一个人被叫到另一个人身边，用公开的声音替他说话。"},"chain":["SILENCE","CALL","STAND BESIDE","SPEAK FOR","ARGUE IN PUBLIC","DEFEND"],"branches":[{"senses":"01 · 08","en":"THE SUPPORTING PERSON: a named individual is known by the cause or doctrine they publicly back.","cn":"拥护的人：一个具体的人，由他公开支持的事业或学说来定义。"},{"senses":"02 · 03","en":"SPEAKING FOR ANOTHER: the advocate lends a voice to a voiceless group, or pleads as a lawyer in court.","cn":"替他人发声：倡导者把声音借给无法发声的群体，或作为律师在法庭上辩护。"},{"senses":"04 · 07","en":"RECOMMENDING AN IDEA: speech or writing puts itself behind one option and against another.","cn":"推荐观念：口头或书面表达把自己放在一个选项后面，与另一个选项对立。"},{"senses":"05","en":"FORMAL MEASURE: inside a committee or parliament, support must be argued into an actual decision.","cn":"正式措施：在委员会或议会里，支持必须被论证成一项实际决定。"},{"senses":"06 · 09","en":"DEFENDING PEOPLE AND GROUPS: the voice stands between the accused and judgment, or campaigns for rights and resources.","cn":"为人和群体辩护：声音站在被告与判决之间，或为权利与资源奔走。"}]},"affixes":{"intro":{"en":"advocate is both noun and verb, and its family is built with -acy, -or, -ive and -tion, plus several fixed legal and religious compounds.","cn":"advocate 兼作名词和动词，其词族由 -acy、-or、-ive、-tion 等后缀构成，另有若干固定的法律与宗教复合词。"},"latinIntro":{"en":"The Latin family of vocare 'to call' and vox 'voice' is real and productive: vocal, voice, vocation and invoke all carry the idea of a voice being called or used. The PIE root *wekw- is reconstructed.","cn":"拉丁语 vocare“叫”与 vox“声音”的词族真实且能产：vocal、voice、vocation、invoke 都带着“声音被调用或使用”的意思。原始印欧语词根 *wekw- 是重构形式。"},"items":[{"word":"patient advocate","structure":"patient + advocate (compound)","meaning":"a person who speaks up for a patient's rights and care","meaningCN":"患者权益倡导者（替病人争取权利和照护的人）","example":"A patient advocate helped the family understand the options.","exampleCN":"一位患者权益倡导者帮助这家人理解了可选方案。"},{"word":"advocacy","structure":"advocate + -acy (process or office)","meaning":"the act or work of publicly supporting a cause","meaningCN":"倡导；拥护活动（-acy 表示行为或职能）","example":"Her advocacy changed the hospital's policy.","exampleCN":"她的倡导改变了医院的政策。"},{"word":"advocator","structure":"advocate + -or (person who does)","meaning":"a person who advocates; a supporter","meaningCN":"提倡者；拥护者（-or 表示做该动作的人）","example":"He was an early advocator of the plan.","exampleCN":"他是这项计划的早期提倡者。"},{"word":"advocation","structure":"advocate + -ion (noun of action)","meaning":"the act of advocating; also a transferred legal case in Scots law","meaningCN":"倡导行为；（苏格兰法）案件移转（-ion 构成行为名词）","example":"The advocation of the case was granted.","exampleCN":"该案件的移转获得批准。"},{"word":"advocative","structure":"advocate + -ive (tending to)","meaning":"relating to or tending toward advocacy","meaningCN":"拥护的；提倡的（-ive 构成倾向形容词）","example":"The speech had an advocative tone.","exampleCN":"这篇演讲带有倡导语气。"},{"word":"advocatess","structure":"advocate + -ess (feminine, historical)","meaning":"a female advocate, used in the 15th century","meaningCN":"女辩护人（15 世纪历史用法，-ess 表示阴性）","example":"The record names an advocatess in the case.","exampleCN":"记录中提到了该案的一位女辩护人。"},{"word":"advocatrix","structure":"advocate + -trix (feminine agent, historical)","meaning":"a female advocate, recorded in the 17th century","meaningCN":"女拥护者、女辩护人（17 世纪历史用法，-trix 表示阴性施动者）","example":"Advocatrix appears in older legal texts.","exampleCN":"advocatrix 见于较古老的法律文本。"},{"word":"Advocate General","structure":"advocate + general (title compound)","meaning":"a senior legal officer who advises a court or the EU","meaningCN":"总法律顾问；欧盟法院总法务官（advocate + general 头衔复合）","example":"The Advocate General issued an opinion.","exampleCN":"总法务官发表了意见。"},{"word":"advocate depute","structure":"advocate + depute (Scots law compound)","meaning":"a senior Scottish prosecutor who acts for the Lord Advocate","meaningCN":"（苏格兰）代检察长；副辩护律师（法律复合词）","example":"An advocate depute presented the case.","exampleCN":"一位代检察长陈述了此案。"},{"word":"devil's advocate","structure":"devil + -'s + advocate (idiomatic compound)","meaning":"a person who argues against an idea for the sake of testing it","meaningCN":"唱反调的人；为检验而故意反对者（固定复合习语）","example":"She played devil's advocate at the meeting.","exampleCN":"她在会上故意唱反调。"},{"word":"self-advocacy","structure":"self- + advocacy (compound)","meaning":"speaking up for one's own rights and needs","meaningCN":"自我倡导；为自身权益发声（self- + advocacy 复合）","example":"The group teaches self-advocacy to young adults.","exampleCN":"该团体教年轻人如何为自己发声。"}],"latinEntries":[{"word":"vocal","structure":"voc- 'voice' + -al","meaning":"relating to the voice; spoken","meaningCN":"声音的；发声的"},{"word":"voice","structure":"Latin vocem 'voice' via Old French voiz","meaning":"the sound made in speaking or singing","meaningCN":"声音；嗓音"},{"word":"vocation","structure":"vocare 'call' + -ion","meaning":"a calling; a strong suitability for a career","meaningCN":"使命；职业"},{"word":"invoke","structure":"in- 'on, into' + vocare 'call'","meaning":"to call on a power, right, or authority","meaningCN":"援引；祈求"}]}},{"word":"affect","ipa_uk":"/əˈfekt/","ipa_us":"/əˈfekt/","definition_zh":"影响；使感动","definition_en":"to act on something or someone so as to produce a change — in a thing, a mind, a body, or a feeling; also, to pretend; and, as a noun, the visible tone of emotion","core_image":"一只手伸过去碰另一样东西，碰过的地方留下变化","scene":"A single late frost affected the whole orchard, turning the young blossoms black overnight.","sceneCN":"这里 affect 是「影响事物」（第 1 个义项：使庄稼、结果等发生变化）；句意：一场晚霜影响了整片果园，一夜之间把初开的花打黑了。图中可辨识物件：结霜的树枝、发黑的花瓣、果园的木栅栏、果农的手套。","pos":[{"tag":"vt.","zh":"影响；感动；侵袭（疾病）；假装；装作"},{"tag":"n.","zh":"情感；情绪状态（心理学用语，通常不可数）"}],"collocations":[{"phrase":"affect the outcome","zh":"影响结果"},{"phrase":"be affected by","zh":"受……影响；受到……波及"},{"phrase":"deeply affected","zh":"深受触动"},{"phrase":"affect an accent","zh":"故意装出某种口音"},{"phrase":"adversely affect","zh":"对……产生不利影响"}],"forms":[{"label":"三单（he/she/it，动词）","form":"affects"},{"label":"过去式（已经发生）","form":"affected"},{"label":"过去分词（完成／被动）","form":"affected"},{"label":"现在分词（进行体）","form":"affecting"},{"label":"复数（名词，心理学用法）","form":"affects"}],"derivatives":[{"word":"affected","pos":"adj.","zh":"做作的；受影响的"},{"word":"affecting","pos":"adj.","zh":"动人的；引人同情的"},{"word":"affection","pos":"n.","zh":"喜爱；爱意（同根但词义已独立）"},{"word":"affective","pos":"adj.","zh":"情感的；情绪方面的"}],"senses":[{"no":"01","title":"Affect a thing or process","titleCN":"影响事物或过程","definition":"to produce a change in something — a crop, a climate, a machine, or a result","definitionCN":"使某事物发生变化——庄稼、气候、机器或结果","example":"A late frost affected the entire orchard.","exampleCN":"一场晚霜影响了整片果园。","why":"The Latin verb afficere is ad- 'to' plus facere 'do, make'. Affect literally means 'do something to' a thing, and whatever is done to it comes out changed.","whyCN":"拉丁动词 afficere 是 ad-“向”加 facere“做、造”。affect 字面上就是“对某物做点什么”，被做了什么的那个东西，出来时就已经变了。"},{"no":"02","title":"Affect a decision or opinion","titleCN":"影响决定或看法","definition":"to influence how someone thinks, judges, or decides","definitionCN":"影响某人如何思考、判断或决定","example":"The new evidence affected how the jury read the case.","exampleCN":"新证据影响了陪审团对这起案件的解读。","why":"An opinion is not a physical object, but it can still be acted on. Information reaches the mind and shifts the balance of reasons, so the same 'do to' shape becomes mental influence.","whyCN":"看法不是实物，却仍然可以被“作用”。信息进入头脑，改变了理由之间的天平，于是同一个“对……做”的结构变成了心理上的影响。"},{"no":"03","title":"Affect someone emotionally","titleCN":"触动某人的情绪","definition":"to move someone's feelings, often with sadness, pity, or sympathy","definitionCN":"触动某人的情感，常带悲伤、怜悯或同情","example":"The final scene affected her so much that she had to leave the theater.","exampleCN":"最后一场戏让她深受触动，不得不离开放映厅。","why":"If something 'does to' you at the level of feeling, the change happens inside you. English says you are affected or deeply affected, and the older adjective affecting still means 'moving'.","whyCN":"如果某事物在情感层面“作用于你”，变化就发生在你内部。英语说 be affected / deeply affected，旧一点的形容词 affecting 至今仍表示“动人的”。"},{"no":"04","title":"A disease affects a body part","titleCN":"疾病侵袭身体部位","definition":"of an illness, to attack or damage a particular organ or part of the body","definitionCN":"指疾病侵袭或损害某个器官或身体部位","example":"The infection affected his lungs and made breathing difficult.","exampleCN":"感染侵袭了他的肺，使他呼吸困难。","why":"This is the oldest medical shade of the verb: an illness is pictured as an outside force that 'does something to' the body. Early English used affect for 'act upon, infect'.","whyCN":"这是动词最古老的医学用法：疾病被想象成一种外力，对身体“做了点什么”。早期英语就用 affect 表示“作用于、感染”。"},{"no":"05","title":"Affect an accent or manner","titleCN":"故意装出某种口音或派头","definition":"to pretend to have a quality, accent, or style, usually to impress others","definitionCN":"假装具有某种特质、口音或风格，通常为了给人留下印象","example":"He affected a French accent whenever he ordered wine.","exampleCN":"每次点葡萄酒时，他都要装出一副法国口音。","why":"This sense comes from a different Latin verb, affectare, 'to strive after'. Striving after a style means reaching for it and putting it on, which is why the modern sense carries a hint of artificiality.","whyCN":"这个义项来自另一个拉丁动词 affectare“追求、力图”。追求某种风格，就是伸手去够它、把它穿上身，所以现代义里总带一点“做作”的味道。"},{"no":"06","title":"Affect not to know or care","titleCN":"装作不知道、不在乎","definition":"to pretend that you do not know, see, or feel something","definitionCN":"假装自己不知道、没看见或不在意某事","example":"She affected not to notice the whispers behind her.","exampleCN":"她装作没听见背后的窃窃私语。","why":"Here the pretense is negative: a reaction is deliberately not shown. The same 'put on' gesture works in reverse — one wears an absence of feeling.","whyCN":"这里的假装是否定式的：明明有反应，却故意不表现出来。同一个“穿上去”的动作反着用——把“没有感觉”穿在身上。"},{"no":"07","title":"Noun: affect in psychology","titleCN":"名词：心理学中的情感状态","definition":"the visible expression of emotion, especially as studied in psychology and psychiatry","definitionCN":"情绪的外在表现，尤指心理学与精神病学研究的对象","example":"The patient spoke in a flat tone and showed little affect.","exampleCN":"病人语调平板，几乎不显露情感。","why":"The noun is stressed on the first syllable, AF-fect. It entered psychology as a translation of German Affekt, and it names the feeling-tone an observer can see, not the feeling as privately lived.","whyCN":"作名词时重音在第一个音节，AF-fect。它作为德语 Affekt 的译词进入心理学，指观察者能看见的“情感色调”，而不是当事人私下体验到的感受。"},{"no":"08","title":"Be affected by a disaster or change","titleCN":"受到灾害或变化波及","definition":"to be touched by a bad event or change so that you suffer its consequences","definitionCN":"受到坏事件或变化波及，并承受其后果","example":"More than a thousand families were affected by the flood.","exampleCN":"一千多个家庭受到洪水波及。","why":"In the passive, the action has already landed. What began as 'something does to you' ends as a condition you are in, so be affected often means 'be hit by' rather than simply 'be influenced'.","whyCN":"在被动语态里，作用已经落下来。原本是“某物对你做了什么”，最后变成你所处的状态，所以 be affected 常表示“被击中、受波及”，而不只是“受影响”。"},{"no":"09","title":"A rule affects a group","titleCN":"规定涉及某一群体","definition":"of a rule or condition, to apply to or concern a particular group of people","definitionCN":"指规则或状况适用于、涉及某一群体","example":"The new parking rule affects every resident on this street.","exampleCN":"新的停车规定涉及这条街上的每一位居民。","why":"A rule 'does something to' everyone inside its reach: it changes what they may do. The verb here marks the boundary of that reach, not a personal emotional change.","whyCN":"规则对射程内的每个人“做了点什么”：改变了他们能做什么。这里的动词标出的是规则覆盖的边界，而不是个人情感上的变化。"}],"etymology":{"intro":{"en":"Affect has two verbs and one noun behind it. All of them come from Latin afficere 'to do to', built from ad- 'to' and facere 'make, do'. The modern psychological noun came by way of German.","cn":"affect 背后有一个名词和两个动词来源，它们都出自拉丁语 afficere“对……做”，由 ad-“向”与 facere“做、造”构成。现代心理学的名词义则经由德语传入。"},"items":[{"era":"LATE 14C.","en":"The noun affect is first recorded meaning 'mental state', from Latin affectus 'disposition, mood, state of mind or body produced by some external influence'.","cn":"名词 affect 最早记录于 14 世纪末，意为“心理状态”，来自拉丁语 affectus“倾向、心境、由外部影响造成的心理或身体状态”。"},{"era":"EARLY 15C.","en":"The first verb (affect v.1) appears with the sense 'act upon, infect'. The medical idea of something acting on the body is therefore older than the modern 'influence the mind'.","cn":"第一个动词（affect v.1）出现时意为“作用于、感染”。因此“某物作用于身体”的医学观念，比现代“影响心理”的用法更早。"},{"era":"C. 1600–1630S","en":"The verb is recorded as 'attack' around 1600, then as 'make a mental impression on' in the 1630s. Influence and emotion grow out of the physical notion of acting on someone.","cn":"约 1600 年该动词记录为“攻击”，17 世纪 30 年代又记录为“在心理上留下印象”。影响与感动都是从“作用于某人”这个物理概念长出来的。"},{"era":"1590S–1660S","en":"The second verb (affect v.2) starts as 'assume the character of' in the 1590s and becomes 'make a pretense of' by the 1660s. It comes through Old French afecter/affecter from Latin affectare, a frequentative of afficere.","cn":"第二个动词（affect v.2）在 16 世纪 90 年代先表示“扮演某人的角色”，到 17 世纪 60 年代变成“假装”。它经古法语 afecter/affecter 来自拉丁语 affectare，是 afficere 的反复动词。"},{"era":"LATIN / PIE","en":"Latin afficere joins ad- 'to' and facere 'make, do'. Facere goes back to PIE *dhe- 'to set, put', the reconstructed root also behind do, deed and fact.","cn":"拉丁语 afficere 由 ad-“向”与 facere“做、造”组成。facere 可追溯到原始印欧语 *dhe-“放置、安放”，这一重构词根也见于 do、deed 和 fact。"},{"era":"MODERN ENGLISH","en":"The noun was obsolete outside philosophy until psychology revived it as a translation of German Affekt. Today the verb's main everyday senses are 'influence' and 'move emotionally', while the noun remains a technical term.","cn":"这个名词在哲学之外曾一度废弃，后来心理学把它作为德语 Affekt 的译词重新启用。今天动词的日常核心义是“影响”和“感动”，名词则仍是专业术语。"}]},"similar":{"note":{"en":"The first group separates spelling neighbours that are constantly confused; the second group separates words that also describe an effect on someone or something.","cn":"第一组区分经常被混淆的形近词；第二组区分同样表示“对人或物产生作用”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"effect","ipa":"/ɪˈfekt/","tag":"spelling / word class","definition":"a result or change produced by something, or to bring something about. It is the noun twin of affect, from ex- 'out' + facere 'do'.","definitionCN":"结果、效果；实现、造成。它是 affect 的同根名词伙伴，来自 ex-“出”+ facere“做”。"},{"word":"effort","ipa":"/ˈefət/","tag":"spelling","definition":"an attempt or the energy spent on it. The similar shape hides a different Latin source, ex- + fortis 'strong'.","definitionCN":"努力、尝试。形近但词源不同，来自 ex- + fortis“强壮”。"},{"word":"affectation","ipa":"/ˌæfekˈteɪʃən/","tag":"derived form","definition":"behavior or speech that is deliberately artificial. It is the noun of the 'pretend' verb, not of the everyday 'influence' verb.","definitionCN":"做作的行为或说话方式。它是“假装”义动词的名词，不是日常“影响”义动词的名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"effect on someone","definition":"to change how someone or something develops, often slowly and indirectly. It is broader and gentler than affect.","definitionCN":"影响某人或某事的发展，常是缓慢而间接的；比 affect 更宽、更温和。"},{"word":"impact","ipa":"/ɪmˈpækt/","tag":"strong effect","definition":"to have a strong or sudden effect on something. It suggests force and scale, where affect can be quiet.","definitionCN":"对某事物产生强烈或突然的影响；带有力度和规模感，而 affect 可以很轻微。"},{"word":"touch","ipa":"/tʌtʃ/","tag":"move emotionally","definition":"to affect someone with tenderness or sympathy. It is warmer and more personal than affect in its emotional sense.","definitionCN":"以温柔或同情打动某人；在情感义上比 affect 更暖、更个人化。"},{"word":"feign","ipa":"/feɪn/","tag":"pretend","definition":"to pretend to have a feeling or condition. It is close to the 'affect an accent' sense but sounds more literary.","definitionCN":"假装有某种感受或状态；接近 affect 的“装出口音”义，但更书面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"ad- means 'to' and facere means 'do', so affect is literally 'do to' — do something to a thing, a mind, or a body.","cn":"ad- 表示“向”，facere 表示“做”，所以 affect 字面上就是“对……做”——对某物、某人的心或身体做点什么。"},{"en":"effect is the noun twin from the same facere root; affect is usually the verb that produces the effect.","cn":"effect 是同一个 facere 词根的名词伙伴；affect 通常是产生 effect 的那个动词。"},{"en":"affection, affectation, affected and affective all grow from the same Latin family, but each has drifted.","cn":"affection、affectation、affected、affective 都出自同一个拉丁词族，但各自漂移出了不同意思。"},{"en":"be affected by is one of the most common passive patterns in news and academic writing.","cn":"be affected by 是新闻和学术写作中最常见的被动结构之一。"},{"en":"flat affect is a real clinical phrase for showing almost no emotion in voice or face.","cn":"flat affect 是真实的临床用语，指声音和脸上几乎不显露情绪。"}],"abstract":[{"en":"Picture a finger touching a pond: the water is still until contact, then rings spread outward. Affect is that contact and the rings it leaves.","cn":"想象一根手指触碰池塘：未碰之前水面平静，碰过之后涟漪向外扩散。affect 就是那次接触以及它留下的涟漪。"},{"en":"The same 'do to' can land on a crop, a jury, a heart, a lung, or a rule's audience. The target changes, the gesture does not.","cn":"同一个“对……做”可以落在庄稼、陪审团、一颗心、一片肺，或一条规定的适用人群上。对象变了，动作没变。"},{"en":"The pretense senses wear the verb inside out: instead of something acting on you, you act a part for others to see.","cn":"假装义把这个动词翻了个面：不再是某物作用于你，而是你演一个角色给别人看。"}]},"examples":[{"en":"Rising sea levels will affect the whole coastal region.","cn":"海平面上升将影响整个沿海地区。"},{"en":"The story affected him more than he expected.","cn":"这个故事对他的触动超出他的预料。"},{"en":"She affected a calm voice while her hands were shaking.","cn":"她双手发抖，却装出一副平静的嗓音。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿菲克特”——阿菲克特伸手一碰，花就谢了 → affect 影响、触动","word":"affect"},"root":"源自拉丁语 afficere“对……做”，ad-“向”+ facere“做、造”；核心是“一方作用于另一方，并在对方身上留下变化”。","sensesIntro":{"en":"Nine senses of affect, all one act of 'doing to': a frost changes an orchard, evidence changes a verdict, a scene moves a heart, illness attacks a lung, a man puts on an accent, a woman hides a reaction, and psychology names the visible tone that remains.","cn":"affect 的九个义项都是同一个“对……做”的动作：霜改变果园，证据改变裁决，一幕戏触动人心，疾病侵袭肺，一个人装上口音，一个女人藏起反应，心理学则为留下的情感色调命名。"},"semanticMap":{"core":{"en":"CORE IMAGE: one thing reaches out and acts on another; the place it touches is never quite the same again.","cn":"核心意象：一方伸过去作用于另一方；被碰过的地方再也回不到原样。"},"chain":["DO TO","REACH","ACT ON","CHANGE","STIR FEELING","LEAVE A MARK"],"branches":[{"senses":"01 · 02 · 09","en":"THINGS, MINDS AND RULES: an outside force changes a crop, a judgment, or the scope of a rule.","cn":"事物、头脑与规则：外力改变庄稼、判断，或一条规定的适用范围。"},{"senses":"03 · 08","en":"FEELING AND SUFFERING: the action reaches the heart, or lands as a disaster that leaves people suffering.","cn":"情感与受苦：作用抵达内心，或作为灾害落下来，让人承受后果。"},{"senses":"04","en":"THE BODY: illness is an outside force that attacks an organ.","cn":"身体：疾病是一种侵袭器官的外力。"},{"senses":"05 · 06","en":"PRETENSE: the verb turns around — a person acts a part for others to see.","cn":"假装：动词翻了个面——人演一个角色给别人看。"},{"senses":"07","en":"PSYCHOLOGY: the noun names the emotional tone an observer can see.","cn":"心理学：名词指观察者能看见的情感色调。"}]},"affixes":{"intro":{"en":"affect has a large and productive English family, but the prefix ad- is no longer felt as a separate English prefix. The suffixes below attach to the finished verb or to its noun forms.","cn":"affect 在英语中有一个很大且能产的词族，但前缀 ad- 已不再被当作独立的英语前缀。下面的后缀都附着在已凝固的动词或其名词形式上。"},"latinIntro":{"en":"The Latin family of afficere 'do to' is real: affectus gives the noun affect, affectio gives affection, and affectare gives affectation. Facere itself is the 'make, do' root behind fact, effect and factory.","cn":"拉丁语 afficere“对……做”的词族真实存在：affectus 产生名词 affect，affectio 产生 affection，affectare 产生 affectation。facere 本身则是 fact、effect、factory 背后的“做、造”词根。"},"items":[{"word":"affected","structure":"affect + -ed (past participle / adjective)","meaning":"artificially displayed; also 'influenced' or 'attacked by illness'","meaningCN":"做作的；也指受影响的、受疾病侵袭的（-ed 构成过去分词或形容词）","example":"She spoke in an affected drawl.","exampleCN":"她说话时装出一种拖长的腔调。"},{"word":"affecting","structure":"affect + -ing (present participle / adjective)","meaning":"having the power to move the feelings","meaningCN":"动人的；引人同情的（-ing 构成进行体或形容词）","example":"The documentary was deeply affecting.","exampleCN":"这部纪录片非常动人。"},{"word":"affection","structure":"affect + -ion (noun of state)","meaning":"fondness or love; the meaning has drifted far from 'a state produced by an influence'","meaningCN":"喜爱；爱意（-ion 构成状态名词，词义已从“受作用的状态”大幅漂移）","example":"He has a real affection for the town.","exampleCN":"他对这座小镇有真切的感情。"},{"word":"affectionate","structure":"affection + -ate (adjective)","meaning":"showing love or tenderness","meaningCN":"深情的；表示关爱的（-ate 构成形容词）","example":"She gave her son an affectionate hug.","exampleCN":"她深情地抱了抱儿子。"},{"word":"affective","structure":"affect + -ive (adjective)","meaning":"relating to emotion or mood","meaningCN":"情感的；情绪方面的（-ive 构成形容词）","example":"The study measures affective responses to music.","exampleCN":"这项研究测量人对音乐的情绪反应。"},{"word":"affectation","structure":"affect + -ation (noun of action)","meaning":"deliberately artificial behavior or speech","meaningCN":"做作；装腔作势（-ation 构成行为名词）","example":"His accent was a pure affectation.","exampleCN":"他的口音纯粹是装出来的。"},{"word":"affectless","structure":"affect + -less (without)","meaning":"showing no emotion","meaningCN":"无情感的；冷淡的（-less 表示“没有”）","example":"The character speaks in a flat, affectless voice.","exampleCN":"这个角色说话语调平板，毫无情感。"},{"word":"unaffected","structure":"un- (not) + affected","meaning":"not influenced; also natural and sincere in manner","meaningCN":"未受影响的；也指自然真挚的（un- 表示否定）","example":"The village was unaffected by the storm.","exampleCN":"这个村庄没有受到风暴影响。"},{"word":"disaffected","structure":"dis- (away) + affected","meaning":"no longer satisfied or loyal","meaningCN":"不满的；不再忠诚的（dis- 表示“离开、反向”）","example":"The reforms angered disaffected voters.","exampleCN":"这些改革激怒了心怀不满的选民。"},{"word":"disaffection","structure":"dis- (away) + affection","meaning":"estrangement or loss of loyalty","meaningCN":"疏离；不满；失去忠诚信赖（dis- 表示“离开”）","example":"Disaffection with the party grew over the year.","exampleCN":"这一年里，人们对该党的不满不断加深。"},{"word":"flat affect","structure":"flat + affect (compound)","meaning":"a clinical sign of showing almost no emotional expression","meaningCN":"情感平淡（flat + affect 复合，临床用语）","example":"Flat affect can be a symptom of depression.","exampleCN":"情感平淡可以是抑郁症的症状。"}],"latinEntries":[{"word":"affection","structure":"affect + -ion","meaning":"a feeling of fondness, or a state of being influenced","meaningCN":"喜爱；受影响的状态"},{"word":"affectation","structure":"affect + -ation","meaning":"artificial behavior meant to impress","meaningCN":"做作；装模作样"},{"word":"affective","structure":"affect + -ive","meaning":"relating to emotion or feeling","meaningCN":"情感的；情绪方面的"},{"word":"disaffected","structure":"dis- (away) + affected","meaning":"estranged or dissatisfied","meaningCN":"不满的；疏离的"}]}},{"word":"affection","ipa_uk":"/əˈfekʃən/","ipa_us":"/əˈfekʃən/","definition_zh":"喜爱；感情","definition_en":"a warm feeling of liking, love, or attachment, and sometimes its outward show; in older medical use, a disease of a body part","core_image":"心向某个人偏过去，停在那里不愿离开","scene":"The old man watched his granddaughter open the gift, and the affection in his eyes was plain to everyone at the table.","sceneCN":"这里 affection 是「亲人之间的深情」（第 2 个义项：家人之间温暖的爱）；句意：老人看着孙女拆开礼物，眼里的深情餐桌旁每个人都看得出来。图中可辨识物件：包装纸、礼物盒、餐桌、老人的老花镜。","pos":[{"tag":"n.","zh":"喜爱；爱意；眷恋；情感；（医学旧义）病症"}],"collocations":[{"phrase":"deep affection","zh":"深厚的感情"},{"phrase":"affection for","zh":"对……的喜爱"},{"phrase":"show affection","zh":"表达爱意"},{"phrase":"win the affections of","zh":"赢得……的爱慕"},{"phrase":"public display of affection","zh":"公开的亲昵举动"}],"forms":[{"label":"复数（名词）","form":"affections"}],"derivatives":[{"word":"affectionate","pos":"adj.","zh":"深情的；表示关爱的"},{"word":"affectionately","pos":"adv.","zh":"深情地；亲切地"},{"word":"affectional","pos":"adj.","zh":"情感上的；情感关系的"},{"word":"disaffection","pos":"n.","zh":"不满；疏离；失去忠诚信赖"}],"senses":[{"no":"01","title":"Fondness for someone","titleCN":"对人的喜爱","definition":"a feeling of liking and caring for someone, gentler and steadier than passion","definitionCN":"喜欢并关心某人的感情，比激情更温和、更稳定","example":"She has a deep affection for the children she teaches.","exampleCN":"她深爱着自己教的那些孩子。","why":"Latin affectio first meant a 'disposition' — the way someone is turned toward something. Warmth is that disposition leaning toward a person, so affection is liking felt as a steady leaning, not a sudden surge.","whyCN":"拉丁语 affectio 最初指“倾向”——一个人朝某物偏过去的方式。温情就是这种倾向朝某个人偏过去，所以 affection 是一种稳定的偏靠，而不是突然涌起的冲动。"},{"no":"02","title":"Love and tenderness between people","titleCN":"亲人或爱人之间的深情","definition":"the warm love that exists between family members, partners, or close friends","definitionCN":"家人、伴侣或密友之间温暖的爱","example":"He took his mother's hand with a tenderness that showed years of affection.","exampleCN":"他握住母亲的手，那份温柔里是多年的深情。","why":"The same leaning becomes mutual and lasting. English keeps affection for the steady, domestic side of love, while love itself can also mean passion.","whyCN":"同一种偏靠变成相互而持久的。英语用 affection 指爱里稳定、日常的那一面，而 love 本身还可以指激情。"},{"no":"03","title":"A show of tenderness","titleCN":"亲昵的举动","definition":"a physical or visible expression of tenderness, such as a hug, a pat, or a kind look","definitionCN":"温柔的外在表达，如拥抱、轻拍或温柔的眼神","example":"The child stroked the puppy with obvious affection.","exampleCN":"孩子明显带着爱意抚摸小狗。","why":"A feeling that stays inside is invisible; when it comes out as a touch or a look, English also calls the demonstration affection. The inner leaning and its outward sign share one word.","whyCN":"留在心里的感情看不见；当它变成一次抚摸或一个眼神，英语也用 affection 指这个表达。内在的偏靠和外在的表示共用同一个词。"},{"no":"04","title":"Attachment to a place or thing","titleCN":"对地方或旧物的眷恋","definition":"a lasting fondness for a place, object, or habit that has been part of one's life","definitionCN":"对曾经长期陪伴自己的地方、物件或习惯的持久喜爱","example":"He still speaks of his old school with real affection.","exampleCN":"他谈起母校时仍带着真切的眷恋。","why":"The leaning is now toward a thing rather than a person. Because the thing cannot love back, the word quietly emphasizes memory and familiarity rather than relationship.","whyCN":"这里的偏靠对象从人变成了物。由于物件无法回应，这个词便悄悄把重点放在记忆与熟悉感上，而不是关系。"},{"no":"05","title":"Emotion as a faculty","titleCN":"与理智相对的情感","definition":"feeling or emotion in general, especially when contrasted with reason","definitionCN":"泛指情感、感情，尤与理智相对","example":"His argument appealed to affection rather than to logic.","exampleCN":"他的论证诉诸情感，而非逻辑。","why":"In older philosophy, affection was the mind's capacity to be moved, set against cold reasoning. The word names the whole emotional side of a person, not one particular fondness.","whyCN":"在较早的哲学里，affection 指心灵被触动的那一面，与冷静的推理相对。这个词指一个人全部的情感面，而不是某一份具体的喜爱。"},{"no":"06","title":"Plural: romantic feelings","titleCN":"复数：爱慕之情","definition":"feelings of love or attraction, especially when spoken of as something one can win or lose","definitionCN":"爱意或爱慕，尤指可以被赢得或失去的感情","example":"The young pianist won the affections of the whole audience.","exampleCN":"这位年轻钢琴家赢得了全场观众的喜爱。","why":"The plural turns the general warmth into a set of feelings that can be given, won, or lost. It is the everyday way to speak of love as something exchanged between people.","whyCN":"复数把笼统的温情变成一组可以给予、赢得或失去的感情。这是日常英语里把爱说成人与人之间交换之物的方式。"},{"no":"07","title":"Medical: a disease or condition","titleCN":"医学旧义：病症","definition":"a disease or abnormal condition of a part of the body, used mainly in older medical writing","definitionCN":"身体某部位的疾病或异常状态，主要用于较早的医学文献","example":"The old report describes an affection of the liver.","exampleCN":"那份旧报告描述了一种肝脏病变。","why":"This sense grows from the neutral Latin meaning 'a state produced in the body'. A disease is exactly such a state, so doctors once wrote of an affection of the lungs or liver. The usage is now dated, and its first recorded date is uncertain.","whyCN":"这个义项来自拉丁语中性的“身体被作用后产生的状态”。疾病正是这样一种状态，所以旧时医生会写 an affection of the lungs/liver。这个用法现在已过时，它最早出现的年代来源不确定。"},{"no":"08","title":"Early sense: passion or desire","titleCN":"早期义：强烈情感或情欲","definition":"a strong emotion or desire, especially in older texts where it is contrasted with reason","definitionCN":"强烈的情感或欲望，尤见于较早文本中与理智相对","example":"In the medieval poem, affection is shown as a force that overrules the will.","exampleCN":"在那首中世纪诗歌里，情感被写成一种压过意志的力量。","why":"The earliest English sense, recorded around 1200, was 'desire, inclination, wish'. Only later did the word cool into steady fondness; the older heat survives in literary and historical writing.","whyCN":"最早的英语义项约在 1200 年记录为“欲望、倾向、愿望”。后来这个词才冷却为稳定的喜爱；旧日的热度仍留在文学与历史文本里。"}],"etymology":{"intro":{"en":"Affection entered English around 1200 from Old French afection, from Latin affectio 'disposition, state'. Its sense moved from 'inclination' to 'good disposition' and finally to 'love'. The medical sense is later and its exact date is uncertain.","cn":"affection 约在 1200 年经古法语 afection 进入英语，源头是拉丁语 affectio“倾向、状态”。词义从“倾向”走到“好感”，最后落在“爱”。医学义出现较晚，确切年代来源不确定。"},"items":[{"era":"C. 1200","en":"First recorded as affeccioun, meaning 'desire, inclination, wish, intention'. The early word is about being turned toward something, not yet about warm love.","cn":"最早记录为 affeccioun，意为“欲望、倾向、愿望、意图”。早期这个词说的是“朝某物偏过去”，还不是温暖的爱。"},{"era":"MID-14C.","en":"The sense 'an emotion of the mind, passion, lust as opposed to reason' appears. This is the hot, older meaning that later cools into fondness.","cn":"“心灵的情感、激情、情欲，与理智相对”这一义项出现。这就是后来冷却为“喜爱”的炽热旧义。"},{"era":"OLD FRENCH","en":"Old French afection (12c., Modern French affection) meant 'emotion, inclination, disposition; love, attraction, enthusiasm'. English took both the form and much of this range from it.","cn":"古法语 afection（12 世纪，现代法语 affection）意为“情感、倾向、性情；爱、吸引、热忱”。英语从它那里拿来了词形，也拿来了大部分语义范围。"},{"era":"LATIN","en":"Latin affectionem (nominative affectio) meant 'a relation, disposition; a temporary state; a frame, constitution'. It is a noun of state from the past-participle stem of afficere 'to do something to, act on', itself ad- 'to' + facere 'make, do'.","cn":"拉丁语 affectionem（主格 affectio）意为“关系、倾向；暂时状态；体质、构造”。它是 afficere“对……做、作用于”的过去分词词干构成的状态名词，而 afficere 由 ad-“向”与 facere“做、造”组成。"},{"era":"LATIN / PIE","en":"Facere goes back to PIE *dhe- 'to set, put', the reconstructed root also behind do, deed and fact. The root is not attested directly and its exact shape is reconstructed.","cn":"facere 可追溯到原始印欧语 *dhe-“放置、安放”，这一重构词根也见于 do、deed 和 fact。该词根没有直接文献记录，具体形式是重构出来的。"},{"era":"LATE 14C.–MODERN ENGLISH","en":"The sense 'love' is recorded from the late 14c. Latin had already moved from 'disposition' to 'good disposition, zealous attachment'. The medical sense 'a disease of a body part' is a later technical use whose first date is uncertain.","cn":"“爱”的义项从 14 世纪末开始记录。拉丁语里词义已从“倾向”走到“好感、热切的依恋”。医学义“身体某部位的疾病”是后来的专业用法，最早年代来源不确定。"}]},"similar":{"note":{"en":"The first group separates words that look or sound close to affection; the second group separates warmer or more specific kinds of liking.","cn":"第一组区分与 affection 形近、音近的词；第二组区分更温暖或更具体的“喜爱”类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"affect","ipa":"/əˈfekt/","tag":"same root, different word","definition":"to influence or move someone. It is the verb from the same Latin root, but it does not mean 'love'.","definitionCN":"影响、感动。它来自同一个拉丁词根的动词，但意思并不是“爱”。"},{"word":"affected","ipa":"/əˈfektɪd/","tag":"derived form","definition":"artificial in manner, or influenced by something. It is built from affect, not from affection.","definitionCN":"做作的，或受影响的。它由 affect 构成，不是由 affection 构成。"},{"word":"affectation","ipa":"/ˌæfekˈteɪʃən/","tag":"derived form","definition":"deliberately artificial behavior. It looks like affection but belongs to the 'pretend' branch.","definitionCN":"故意做作的行为。它看起来像 affection，但属于“假装”那一支。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fondness","ipa":"/ˈfɒndnəs/","tag":"liking","definition":"a gentle liking for someone or something. It is close to affection but often lighter and less deep.","definitionCN":"对人或物的温和喜爱；接近 affection，但常更轻、更浅。"},{"word":"love","ipa":"/lʌv/","tag":"strong feeling","definition":"a deep feeling of attachment and care. It is stronger and broader than affection and can include passion.","definitionCN":"深切的爱与关怀；比 affection 更强、更广，也可以包含激情。"},{"word":"attachment","ipa":"/əˈtætʃmənt/","tag":"bond","definition":"a feeling that binds you to a person, place, or thing. It stresses the bond more than the warmth.","definitionCN":"把你与某人、某地或某物连起来的情感；更强调联结，而不是温度。"},{"word":"tenderness","ipa":"/ˈtendənəs/","tag":"gentle care","definition":"gentle, protective care shown to someone. It is the soft behavior that affection often produces.","definitionCN":"对某人的温柔、保护性关怀；常是 affection 产生的柔软举动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"affection comes from affectio, 'a state produced in you' — the warm state that being acted on leaves behind.","cn":"affection 来自 affectio“在你身上形成的状态”——被触动之后留下的温暖状态。"},{"en":"affect and affection share a root but not a meaning: one is the action, the other is the warm result.","cn":"affect 与 affection 同根不同义：一个是动作，一个是温暖的结果。"},{"en":"affectionate and affectionately carry the same heart, one as an adjective and one as an adverb.","cn":"affectionate 和 affectionately 装着同一颗心，一个是形容词，一个是副词。"},{"en":"win someone's affections is a real phrase for earning another person's love.","cn":"win someone's affections 是真实短语，意为赢得某人的爱慕。"},{"en":"public display of affection, shortened to PDA, is a common modern phrase.","cn":"public display of affection（缩写 PDA）是现代英语里的常用说法。"}],"abstract":[{"en":"Picture a heart that does not rush forward but leans slowly toward a person and stays there. That lean is affection.","cn":"想象一颗心并不猛冲，而是慢慢朝一个人偏过去，然后停在那里。这个偏靠就是 affection。"},{"en":"The same lean can point at a grandmother, a puppy, an old school, or a hometown. The object changes; the direction stays.","cn":"同一个偏靠可以指向祖母、小狗、母校或故乡。对象变了，方向没变。"},{"en":"Older texts let the warmth run hot and call it passion; modern English lets it cool and calls it affection. One word keeps both temperatures.","cn":"较早的文本让这份温暖烧热，叫它激情；现代英语让它冷却，叫它 affection。同一个词保留了两个温度。"}]},"examples":[{"en":"She feels great affection for her old neighborhood.","cn":"她对旧街区怀有很深的感情。"},{"en":"He never learned to show affection easily.","cn":"他始终没学会轻易表达爱意。"},{"en":"The dog wagged its tail with affection.","cn":"那只狗亲昵地摇着尾巴。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿菲克申”——阿菲把旧手表擦了又擦，那是眷恋 → affection 喜爱、眷恋","word":"affection"},"root":"源自拉丁语 affectio“倾向、状态”，出自 afficere“对……做”；原义是“被作用后形成的偏向”，后来专指稳定而温暖的喜爱。","sensesIntro":{"en":"Eight senses of affection, all one heart leaning toward someone or something: fondness, love, a tender touch, attachment to a place, emotion itself, romantic affections, an old medical condition, and the older heat of passion.","cn":"affection 的八个义项都是同一颗心朝某人或某物偏过去：喜爱、深情、亲昵举动、对地方的眷恋、情感本身、爱慕之情、旧医学义中的病症，以及早期义里的炽热情感。"},"semanticMap":{"core":{"en":"CORE IMAGE: a heart leans toward someone or something and stays there, warm and steady.","cn":"核心意象：一颗心朝某人或某物偏过去，停在那里，温暖而稳定。"},"chain":["TOUCHED","DISPOSED","WARM FEELING","TENDER SHOW","ATTACHMENT","LOVE"],"branches":[{"senses":"01 · 02","en":"FONDNESS AND LOVE: one person is turned toward another with steady warmth.","cn":"喜爱与深情：一个人带着稳定的温度朝另一个人偏过去。"},{"senses":"03","en":"TENDER SHOW: the inner lean becomes a hug, a pat, or a kind look.","cn":"亲昵表达：内在的偏靠变成拥抱、轻拍或温柔的眼神。"},{"senses":"04","en":"ATTACHMENT: the lean settles on a place, an object, or a familiar habit.","cn":"眷恋：偏靠落在某个地方、物件或熟悉的习惯上。"},{"senses":"05 · 06","en":"EMOTION ITSELF: affection names the whole feeling side of a person, and its plural names love one can win or lose.","cn":"情感本身：affection 指一个人全部的情感面，复数则指可以赢得或失去的爱。"},{"senses":"07 · 08","en":"OLDER SENSES: the same state word covers a bodily disease and the hot passion of early texts.","cn":"较旧的义项：同一个“状态”词也覆盖身体病症与早期文本中的炽热情感。"}]},"affixes":{"intro":{"en":"affection is a noun with a real English family. Its Latin prefix ad- is no longer felt, and English builds new words with ordinary suffixes or with dis- and un-.","cn":"affection 是一个拥有真实英语词族的名词。它的拉丁前缀 ad- 已不再被感知，英语用普通后缀或 dis-、un- 来造新词。"},"latinIntro":{"en":"The Latin family of afficere 'do to' is real: affectio gives affection, affectus gives affect, and affectare gives affectation. All four Latin entries below belong to this same family.","cn":"拉丁语 afficere“对……做”的词族真实存在：affectio 产生 affection，affectus 产生 affect，affectare 产生 affectation。下面四条拉丁词条都属于同一词族。"},"items":[{"word":"affectionate","structure":"affection + -ate (adjective)","meaning":"showing love or tender care","meaningCN":"深情的；表示关爱的（-ate 构成形容词）","example":"He gave her an affectionate smile.","exampleCN":"他朝她深情地笑了笑。"},{"word":"affectionately","structure":"affectionate + -ly (adverb)","meaning":"in a loving or tender way","meaningCN":"深情地；亲切地（-ly 构成副词）","example":"She patted the dog affectionately.","exampleCN":"她亲昵地拍了拍那只狗。"},{"word":"affectional","structure":"affection + -al (adjective)","meaning":"relating to affection or emotional bonds","meaningCN":"情感上的；情感关系的（-al 构成形容词）","example":"The study looks at affectional bonds in early childhood.","exampleCN":"这项研究考察幼儿期的情感联结。"},{"word":"affectionateness","structure":"affectionate + -ness (quality noun)","meaning":"the quality of being loving and tender","meaningCN":"深情；亲切（-ness 构成性质名词）","example":"Her affectionateness made the room feel warm.","exampleCN":"她的亲切让整个房间都暖了起来。"},{"word":"disaffection","structure":"dis- (away) + affection","meaning":"loss of affection or loyalty; estrangement","meaningCN":"不满；疏离；失去忠诚信赖（dis- 表示“离开”）","example":"Disaffection with the leadership spread quickly.","exampleCN":"对领导层的不满迅速蔓延。"},{"word":"disaffected","structure":"dis- (away) + affected","meaning":"no longer loyal or satisfied","meaningCN":"不满的；不再忠诚的（dis- 表示“离开、反向”）","example":"The party lost its disaffected members.","exampleCN":"该党失去了那些心怀不满的成员。"},{"word":"unaffected","structure":"un- (not) + affected","meaning":"not influenced; also simple and sincere","meaningCN":"未受影响的；也指自然真挚的（un- 表示否定）","example":"Her kindness was genuine and unaffected.","exampleCN":"她的善意真诚而不做作。"},{"word":"affect","structure":"Latin afficere 'do to' → affect (whole-word borrowing; no English affix)","meaning":"to influence or move someone; not a synonym of affection","meaningCN":"影响、感动（整词借入，没有英语词缀；同根但已独立的一支，并不是 affection 的同义词）","example":"The news affected him deeply.","exampleCN":"这个消息深深触动了他。"},{"word":"affected","structure":"affect + -ed (past participle / adjective)","meaning":"influenced; or artificial in manner","meaningCN":"受影响的；或指做作的（-ed 构成过去分词或形容词）","example":"The crops were affected by drought.","exampleCN":"庄稼受到了干旱影响。"},{"word":"public display of affection","structure":"public + display + of + affection (compound phrase)","meaning":"a physical show of love in front of others, often shortened to PDA","meaningCN":"公开的亲昵举动（复合短语，常缩写为 PDA）","example":"The park bans public displays of affection after dark.","exampleCN":"这座公园禁止天黑后在公开场合亲昵。"},{"word":"affections","structure":"affection + -s (plural)","meaning":"feelings of love, especially ones that can be won or lost","meaningCN":"爱慕之情；感情（-s 构成复数，常指可赢得或失去的爱）","example":"He tried to win her affections.","exampleCN":"他试图赢得她的爱慕。"}],"latinEntries":[{"word":"affectionate","structure":"affection + -ate","meaning":"showing fondness or love","meaningCN":"深情的；充满爱意的"},{"word":"affectation","structure":"affect + -ation","meaning":"artificial behavior meant to impress","meaningCN":"做作；装模作样"},{"word":"affective","structure":"affect + -ive","meaning":"relating to emotion or feeling","meaningCN":"情感的"},{"word":"disaffection","structure":"dis- (away) + affection","meaning":"loss of affection or loyalty","meaningCN":"不满；疏离"}]}},{"word":"agency","ipa_uk":"/ˈeɪdʒənsi/","ipa_us":"/ˈeɪdʒənsi/","definition_zh":"代理机构；能动性","definition_en":"the capacity to act and produce an effect; the power to decide for oneself; or an organization authorized to act for others","core_image":"一个人从自己这边发力，把事情推动起来","scene":"The travel agency booked our flights, and the agent marked every connection on the printed itinerary.","sceneCN":"这里 agency 是「商业代理机构」（第 3 个义项：为他人提供旅行等服务的公司）；句意：旅行社为我们订了机票，代理人在打印好的行程单上标出了每一次转机。图中可辨识物件：行程单、登机牌、柜台、电话听筒。","pos":[{"tag":"n.","zh":"能动性；自主权；代理机构；政府机构；代理关系；中介作用"}],"collocations":[{"phrase":"travel agency","zh":"旅行社"},{"phrase":"government agency","zh":"政府机构"},{"phrase":"news agency","zh":"通讯社"},{"phrase":"through the agency of","zh":"借助……的作用"},{"phrase":"human agency","zh":"人的能动性"},{"phrase":"sole agency","zh":"独家代理权"}],"forms":[{"label":"复数（名词）","form":"agencies"}],"derivatives":[{"word":"agent","pos":"n.","zh":"代理人；动因；作用剂"},{"word":"agential","pos":"adj.","zh":"代理人的；能动者的"},{"word":"interagency","pos":"adj.","zh":"跨机构的；机构之间的"},{"word":"subagency","pos":"n.","zh":"分代理机构；下属机构"}],"senses":[{"no":"01","title":"Capacity to act","titleCN":"行动的能力","definition":"the ability of a person or group to act and make a difference in the world","definitionCN":"个人或群体采取行动并产生影响的能力","example":"The disaster reminded residents of their own agency in preparing for the next storm.","exampleCN":"这场灾难让居民意识到，自己在为下一场风暴做准备时是有行动能力的。","why":"Agency comes from Latin agere 'to drive, do'. It names the power to start an action, not the action itself. A person with agency is the source from which a change begins.","whyCN":"agency 来自拉丁语 agere“驱动、做”。它指的是启动一个行动的力量，而不是行动本身。有 agency 的人，就是变化开始的那个源头。"},{"no":"02","title":"The power to make one's own choices","titleCN":"自主决定的权力","definition":"the freedom or power to decide and act for oneself, rather than being controlled","definitionCN":"自主决定与行动的自由或权力，而非受人控制","example":"The program gives young people more agency over their own learning.","exampleCN":"这个项目让年轻人在自己的学习上有更多自主权。","why":"If agency is the capacity to act, then having agency over something means your own will, not someone else's, sets the direction. The word shifts from ability to authority.","whyCN":"如果 agency 是行动的能力，那么对某事有 agency 就意味着方向由你自己的意志、而不是别人的意志来定。词义于是从“能力”滑向“权力”。"},{"no":"03","title":"A business that acts for others","titleCN":"商业代理机构","definition":"a company that provides a service for other people or companies, such as travel, advertising, or real estate","definitionCN":"为其他人或公司提供服务的公司，如旅行社、广告公司或房产中介","example":"The travel agency booked our flights and sent a printed itinerary.","exampleCN":"旅行社为我们订了机票，还寄来一份打印好的行程单。","why":"An agency is literally 'the place where an agent acts'. The company does not sell its own goods; it acts on behalf of clients, so the name points to delegated action.","whyCN":"agency 字面上是“代理人做事的地方”。这家公司不卖自己的货，而是代表客户行动，所以这个名字指向的是“受托而做”。"},{"no":"04","title":"The agent's authority to act","titleCN":"代理关系与代理权","definition":"the legal relationship in which one person is authorized to act for another","definitionCN":"一个人被授权代表另一个人行动的法律关系","example":"The contract sets out the agency under which the manager may sign for the owner.","exampleCN":"合同规定了经理可以代表业主签字的代理关系。","why":"In law, agency is not a building but a bond: the principal grants the agent power to bind the principal by acts done on his behalf. The abstract Latin noun becomes a precise legal relation.","whyCN":"在法律里，agency 不是一栋楼，而是一种关系：委托人授予代理人权力，使其代做的行为可以约束委托人。抽象的拉丁名词在这里变成了精确的法律关系。"},{"no":"05","title":"A government body","titleCN":"政府机构","definition":"an official organization, especially one created by a government to carry out a public function","definitionCN":"官方组织，尤指政府为履行公共职能而设立的机构","example":"The environmental agency tested the water in every district.","exampleCN":"环境机构检测了每个区的水质。","why":"A government agency is an organization that acts for the public: it has been given the authority to do specific work. The 'acting for another' idea survives, with the public as the principal.","whyCN":"政府机构是为公众办事的组织：它被授予做特定工作的权力。“替他人行动”的意思仍在，只是委托人变成了公众。"},{"no":"06","title":"A local office or branch","titleCN":"代理处、分支机构","definition":"a local office through which a larger organization does business in a place","definitionCN":"较大组织在某一地方办事的本地办公室","example":"Our agency in Osaka handles all inquiries from western Japan.","exampleCN":"我们在大阪的代理处处理来自日本西部的所有询问。","why":"The office is where the acting happens locally. The parent organization is elsewhere; this place is its delegated hand.","whyCN":"办事处是“代为行动”在当地发生的地点。总部在别处，这个地方就是它伸出去的手。"},{"no":"07","title":"By means of; through the agency of","titleCN":"借助……的作用","definition":"the means or power through which something is done or a result is produced","definitionCN":"完成某事或产生结果所借助的手段或力量","example":"The metal was cleaned through the agency of a weak acid.","exampleCN":"这种金属借助弱酸的作用得到了清洁。","why":"Here agency is no longer a person or company but the active power that produces an effect. The phrase through the agency of treats something as the force by which a result is brought about.","whyCN":"这里的 agency 不再是某个人或公司，而是产生效果的作用力。through the agency of 这个短语把某事物当作“借以产生结果的力量”。"},{"no":"08","title":"Agency in sociology","titleCN":"社会学中的能动性","definition":"in social theory, the capacity of individuals to act independently of social structures","definitionCN":"社会理论中，个人相对于社会结构独立行动的能力","example":"The study asks how much agency workers have within a rigid factory system.","exampleCN":"这项研究追问，工人在僵化的工厂体系里有多大能动性。","why":"Sociology sets agency against structure. The word is still 'capacity to act', but it now asks whether a person can act against the rules and expectations that surround them.","whyCN":"社会学把 agency 与 structure（结构）相对。这个词仍是“行动能力”，但它现在追问的是：一个人能否逆着周围的规则与期待行动。"},{"no":"09","title":"A news agency","titleCN":"通讯社","definition":"an organization that gathers news and supplies it to newspapers, broadcasters, and websites","definitionCN":"采集新闻并提供给报纸、广播和网站的机构","example":"The news agency sent the first photographs of the flooded town.","exampleCN":"通讯社最先发出了被淹小镇的照片。","why":"A news agency acts for many outlets at once: it gathers in one place what others cannot gather everywhere. Its product travels under other names, which is why it is an agency rather than a newspaper.","whyCN":"通讯社同时代表许多媒体行动：它在一个地方采集别人无法到处采集的东西。它的产品以别人的名义发布，所以它是“社”而不是“报”。"}],"etymology":{"intro":{"en":"Agency entered English in the 1650s from Medieval Latin agentia, an abstract noun from agens/agentem, the present participle of Latin agere 'to drive, do'. The business sense is much later, recorded by 1861.","cn":"agency 在 17 世纪 50 年代经中世纪拉丁语 agentia 进入英语；agentia 是 agens/agentem 的抽象名词，而后者是拉丁语 agere“驱动、做”的现在分词。商业机构义出现得晚得多，1861 年才有记录。"},"items":[{"era":"1650S","en":"First recorded meaning 'active operation'. The new word named the exercise of power, not a company or an office.","cn":"最早记录时意为“积极的作用、活动”。这个新词指的是权力的施行，而不是公司或办事处。"},{"era":"1670S","en":"The sense 'a mode of exerting power or producing effect' appears. Agency is now the 'how' of an effect: the channel through which a result is produced.","cn":"“施加力量或产生效果的方式”这一义项出现。agency 这时成了效果的“如何”：结果借以产生的通道。"},{"era":"MEDIEVAL LATIN","en":"Medieval Latin agentia is an abstract noun from agentem (nominative agens), the present participle of agere, meaning 'effective, powerful' as well as 'acting'.","cn":"中世纪拉丁语 agentia 是 agentem（主格 agens）的抽象名词；agentem 是 agere 的现在分词，既指“正在行动的”，也指“有效的、有力量的”。"},{"era":"LATIN","en":"Latin agere meant 'to set in motion, drive forward; to do, perform', and figuratively 'incite to action; keep in movement'. The verb pictures a force pushing something into motion.","cn":"拉丁语 agere 意为“使启动、向前驱动；做、执行”，引申为“促使行动、使保持运动”。这个动词描绘的是一股把某物推入运动的力量。"},{"era":"PIE","en":"Agere goes back to PIE *ag- 'to drive, draw out or forth, move'. The same root is visible in Greek agein 'to lead, drive' and Sanskrit ajati 'drives'; reconstructed roots are not attested directly.","cn":"agere 可追溯到原始印欧语 *ag-“驱动、拉出、移动”。同一词根也见于希腊语 agein“引导、驱赶”和梵语 ajati“驱赶”；这类重构词根没有直接文献记录。"},{"era":"1861–MODERN ENGLISH","en":"The meaning 'establishment where business is done for another' is recorded by 1861. Government agencies, news agencies, and the sociological contrast of agency and structure all grow from that 'acting for or from' core.","cn":"“替他人办事的机构”这一义项于 1861 年有记录。政府机构、通讯社，以及社会学里 agency 与 structure 的对立，都从“代为行动／从自身发力”这个核心长出来。"}]},"similar":{"note":{"en":"The first group separates words that look or sound close to agency; the second group separates organizations and words about the power to act.","cn":"第一组区分与 agency 形近、音近的词；第二组区分机构类词和表示“行动能力”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"agenda","ipa":"/əˈdʒendə/","tag":"spelling / same root","definition":"a list of things to be done or discussed. It shares the ag- root but means 'things to be driven forward'.","definitionCN":"待办或待议事项清单。它同样含 ag- 词根，但意思是“要被推动去做的事”。"},{"word":"agent","ipa":"/ˈeɪdʒənt/","tag":"derived form","definition":"a person who acts for another, or a force that produces an effect. It is the person behind agency.","definitionCN":"代理人；动因。它是 agency 背后那个行动的人或力量。"},{"word":"agential","ipa":"/eɪˈdʒenʃəl/","tag":"derived form","definition":"relating to an agent or to agency. It is the adjective built from agency.","definitionCN":"代理人的；能动者的。它是由 agency 构成的形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"autonomy","ipa":"/ɔːˈtɒnəmi/","tag":"self-rule","definition":"the right or condition of governing oneself. It stresses independence, while agency stresses the capacity to act.","definitionCN":"自治的权利或状态；强调独立，而 agency 强调行动能力。"},{"word":"institution","ipa":"/ɪnˈstjuːʃən/","tag":"organization","definition":"an established organization or custom. It is broader than agency and need not act for anyone.","definitionCN":"已确立的机构或制度；比 agency 更宽，也不一定替谁办事。"},{"word":"bureau","ipa":"/ˈbjʊərəʊ/","tag":"office","definition":"a government department or a local office. It overlaps with agency but sounds more administrative.","definitionCN":"政府部门或办事处；与 agency 部分重叠，但更带行政色彩。"},{"word":"means","ipa":"/miːnz/","tag":"medium","definition":"a method or resource used to achieve something. It matches the 'through the agency of' sense.","definitionCN":"达到目的的方法或资源；对应 through the agency of 的“借助……作用”义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"agere means 'drive, do', so agency is the power that drives an action or the body that does it for someone.","cn":"agere 意为“驱动、做”，所以 agency 既是推动行动的力量，也是替别人做事的机构。"},{"en":"agent is the person; agency is the power or the organization. The -y turns the actor into an abstract noun.","cn":"agent 是人；agency 是力量或组织。后缀 -y 把行动者变成了抽象名词。"},{"en":"travel agency, news agency and government agency all keep the same 'acts for others' structure.","cn":"travel agency、news agency、government agency 都保留同一个“替他人行动”的结构。"},{"en":"human agency is the standard phrase for people's capacity to act on their own.","cn":"human agency 是表达“人自主行动能力”的标准短语。"},{"en":"through the agency of is a real formal phrase meaning 'by means of'.","cn":"through the agency of 是真实的正式短语，意为“借助……的作用”。"}],"abstract":[{"en":"Picture a hand pressing a switch: the hand is the agent, the current is the effect, and the capacity to press is agency.","cn":"想象一只手按下开关：手是行动者，电流是效果，而按下开关的能力就是 agency。"},{"en":"The same word points outward to an organization that acts for you, and inward to the part of you that can act at all.","cn":"同一个词既向外指替你做事的机构，也向内指你身上那个“能行动”的部分。"},{"en":"Agency is the starting point of an arrow, not the arrow's flight. It answers 'who began this?' before 'what happened?'.","cn":"agency 是箭的起点，而不是箭的飞行。它先回答“是谁开始的”，再回答“发生了什么”。"}]},"examples":[{"en":"The agency arranged visas for the whole research team.","cn":"代理机构为整个研究团队办好了签证。"},{"en":"Patients should have more agency in choosing their treatment.","cn":"病人在选择治疗方式时应有更多自主权。"},{"en":"The disease spreads through the agency of mosquitoes.","cn":"这种疾病借助蚊子的作用传播。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿真西”——阿真西开了家旅行社，专门替别人跑腿 → agency 代理机构","word":"agency"},"root":"源自拉丁语 agere“驱动、做”，经中世纪拉丁语 agentia“作用、能动”进入英语；核心是“行动者从自身发力，推动事情发生”。","sensesIntro":{"en":"Nine senses of agency, all one source of action: a person's capacity to act, the power to choose, a company that acts for clients, a legal authority, a government body, a local office, an active means, a sociological capacity, and a news organization acting for many outlets.","cn":"agency 的九个义项都指向同一个行动源头：人的行动能力、自主决定的权力、替客户做事的公司、法律上的代理权、政府机构、本地办事处、起作用的手段、社会学意义上的能动性，以及替多家媒体采集新闻的通讯社。"},"semanticMap":{"core":{"en":"CORE IMAGE: an actor pushes from its own side and sets something else in motion.","cn":"核心意象：行动者从自己这边发力，把另一件事推动起来。"},"chain":["ACTOR","DRIVE","DO","EFFECT","AUTHORITY","INSTITUTION"],"branches":[{"senses":"01 · 08","en":"CAPACITY TO ACT: a person or group can begin an action, even against surrounding structures.","cn":"行动能力：个人或群体能够启动一个行动，甚至逆着周围的结构行动。"},{"senses":"02","en":"OWN WILL: the capacity becomes the authority to decide for oneself.","cn":"自主意志：能力变成为自己决定的权力。"},{"senses":"03 · 09","en":"BUSINESS AND NEWS: a company or news organization acts on behalf of clients or outlets.","cn":"商业与新闻：公司或新闻机构代表客户或媒体行动。"},{"senses":"04 · 06","en":"LEGAL BOND AND LOCAL OFFICE: authority is granted, and a branch is the delegated hand.","cn":"法律纽带与本地办事处：权力被授予，分支机构是伸出去的手。"},{"senses":"05 · 07","en":"PUBLIC BODY AND ACTIVE MEANS: an official organization acts for the public, or a force is the means by which a result occurs.","cn":"公共机构与作用手段：官方组织为公众办事，或某种力量成为结果借以发生的媒介。"}]},"affixes":{"intro":{"en":"agency is a noun with a productive English family. Its Latin -ia became English -y, and English adds -s, -al, inter- and sub- to build new forms.","cn":"agency 是一个拥有能产英语词族的名词。拉丁语 -ia 在英语中变成 -y，英语再用 -s、-al、inter-、sub- 造新形式。"},"latinIntro":{"en":"The Latin family of agere 'drive, do' is real and very large: agent, act, action, agenda and agile all belong to it. The PIE root *ag- is reconstructed and not directly attested.","cn":"拉丁语 agere“驱动、做”的词族真实存在而且很大：agent、act、action、agenda、agile 都属于它。原始印欧语词根 *ag- 是重构出来的，没有直接文献记录。"},"items":[{"word":"agent","structure":"agere 'do' + -ent (person or thing that acts)","meaning":"a person who acts for another, or a force that produces an effect","meaningCN":"代理人；动因；作用剂（-ent 表示做该动作的人或物）","example":"The agent signed the contract for the owner.","exampleCN":"代理人代表业主签署了合同。"},{"word":"agential","structure":"agency + -al (adjective)","meaning":"relating to an agent or to agency","meaningCN":"代理人的；能动者的（-al 构成形容词）","example":"The essay studies agential power in local communities.","exampleCN":"这篇论文研究地方社区中的能动力量。"},{"word":"agencies","structure":"agency + -s (plural)","meaning":"more than one agency","meaningCN":"多个代理机构（-s 构成复数）","example":"Several agencies competed for the contract.","exampleCN":"多家机构为这份合同竞争。"},{"word":"interagency","structure":"inter- (between) + agency","meaning":"happening between or across agencies","meaningCN":"跨机构的；机构之间的（inter- 表示“在……之间”）","example":"The flood required an interagency response.","exampleCN":"这场洪水需要跨机构协同应对。"},{"word":"subagency","structure":"sub- (under) + agency","meaning":"a smaller agency under a larger one","meaningCN":"分代理机构；下属机构（sub- 表示“在下”）","example":"The subagency reports to the regional office.","exampleCN":"分代理机构向地区办事处汇报。"},{"word":"agency-wide","structure":"agency + wide (compound)","meaning":"affecting the whole agency","meaningCN":"全机构范围的（agency + wide 复合）","example":"The director announced an agency-wide review.","exampleCN":"主任宣布进行一次全机构范围的审查。"},{"word":"news agency","structure":"news + agency (compound)","meaning":"an organization that gathers news for other outlets","meaningCN":"通讯社（news + agency 复合）","example":"The news agency supplies photos to hundreds of papers.","exampleCN":"这家通讯社向数百家报纸提供照片。"},{"word":"travel agency","structure":"travel + agency (compound)","meaning":"a business that books travel for clients","meaningCN":"旅行社（travel + agency 复合）","example":"The travel agency found us a cheaper flight.","exampleCN":"旅行社替我们找到了更便宜的航班。"},{"word":"employment agency","structure":"employment + agency (compound)","meaning":"a business that helps people find jobs","meaningCN":"职业介绍所（employment + agency 复合）","example":"The employment agency matched her with a local firm.","exampleCN":"职业介绍所把她和一家本地公司匹配起来。"},{"word":"agency agreement","structure":"agency + agreement (compound)","meaning":"a contract that defines an agent's authority","meaningCN":"代理协议（agency + agreement 复合）","example":"Both sides signed the agency agreement in March.","exampleCN":"双方在三月签署了代理协议。"},{"word":"free agency","structure":"free + agency (compound)","meaning":"the state of being free to choose one's employer or team","meaningCN":"自由代理；自由球员身份（free + agency 复合）","example":"The player entered free agency after the season.","exampleCN":"赛季结束后，这名球员进入了自由球员市场。"}],"latinEntries":[{"word":"agent","structure":"agere 'do' + -ent","meaning":"a person who acts for another","meaningCN":"代理人；行动者"},{"word":"agenda","structure":"agere 'do' + -enda (things to be done)","meaning":"a list of things to be done","meaningCN":"议程"},{"word":"action","structure":"agere 'do' + -tion","meaning":"the process of doing something","meaningCN":"行动"},{"word":"agile","structure":"agere 'do' + -ile","meaning":"able to move or act quickly","meaningCN":"敏捷的"}]}},{"word":"agenda","ipa_uk":"/əˈdʒendə/","ipa_us":"/əˈdʒendə/","definition_zh":"议程；待办事项","definition_en":"a list of things to be done or discussed, especially the order of business at a meeting","core_image":"一张写满“该做的事”的清单，平放在会议桌中央","scene":"Before the board meeting, the secretary pinned the agenda to the door so everyone knew what would be discussed.","sceneCN":"这里 agenda 是「会议议程」（第 1 个义项：会议要逐项讨论的清单）；句意：董事会开始前，秘书把议程钉在门上，让大家知道要讨论什么。图中可辨识物件：门上的打印清单、会议桌、文件夹、墙上的挂钟。","pos":[{"tag":"n.","zh":"议程；待办事项；（政治、机构的）政策重点；秘密动机"}],"collocations":[{"phrase":"on the agenda","zh":"在议程上；被列入讨论事项"},{"phrase":"top of the agenda","zh":"议程首位；最优先的事"},{"phrase":"set the agenda","zh":"设定议程；决定讨论重点"},{"phrase":"hidden agenda","zh":"隐藏议程；秘密动机"},{"phrase":"agenda item","zh":"议程项目"}],"forms":[{"label":"复数（名词）","form":"agendas"}],"derivatives":[{"word":"agendum","pos":"n.","zh":"议程中的单个项目（罕用单数）"},{"word":"agenda-setting","pos":"n.","zh":"议程设置（媒体研究术语）"},{"word":"agenda-setter","pos":"n.","zh":"议程设定者"},{"word":"agenda-driven","pos":"adj.","zh":"受特定议程支配的"}],"senses":[{"no":"01","title":"Agenda for a meeting","titleCN":"会议议程","definition":"a list of the matters to be discussed or decided at a meeting, usually in a fixed order","definitionCN":"会议要讨论或决定的事项清单，通常按固定顺序排列","example":"The first item on the agenda is the annual budget.","exampleCN":"议程上的第一项是年度预算。","why":"Agenda is Latin for 'things to be done'. A meeting agenda is that idea in its most practical form: every line names one thing the group must finish before it can close the meeting.","whyCN":"agenda 在拉丁语里就是“该做的事”。会议议程是这一想法最实际的形态：每一行都写着一件小组在散会前必须处理完的事。"},{"no":"02","title":"A list of things to do","titleCN":"待办清单","definition":"a plan or list of tasks that a person intends to deal with, not necessarily at a formal meeting","definitionCN":"一个人打算处理的任务计划或清单，不一定用于正式会议","example":"My agenda for the weekend is simple: clean the garage and finish the report.","exampleCN":"我周末的待办清单很简单：清理车库，写完报告。","why":"The meeting sense narrowed the Latin plural into a document. The older, wider sense survives whenever someone speaks of their own agenda for the day: the list is private, but it is still a list of things to be done.","whyCN":"会议义把拉丁语复数收窄成一份文件。只要有人说自己当天的 agenda，更古老、更宽的含义就还在：清单是私人的，但仍是一串待办之事。"},{"no":"03","title":"Political policy programme","titleCN":"政治议程","definition":"the set of issues and policies that a government, party, or movement intends to act on","definitionCN":"政府、政党或运动打算着手处理的一系列议题和政策","example":"The new government put tax reform at the top of its political agenda.","exampleCN":"新政府把税制改革放在政治议程的首位。","why":"A political agenda is a to-do list written for a whole country. The items are not done yet; they are the things the group publicly promises to do.","whyCN":"政治议程是为一整个国家写的待办清单。这些事项尚未完成，而是这个群体公开承诺要做的事。"},{"no":"04","title":"Hidden agenda: a secret motive","titleCN":"隐藏议程：秘密动机","definition":"a secret reason or motive that someone hides behind a public explanation","definitionCN":"某人藏在公开说法背后的秘密理由或动机","example":"Voters suspected a hidden agenda behind the sudden tax cut.","exampleCN":"选民怀疑突然减税背后另有隐藏议程。","why":"When the list is public but the true purpose is private, people call it hidden. The metaphor treats motives as items that were quietly left off the printed list.","whyCN":"当清单是公开的、真正目的却是私人的，人们就说它“隐藏”。这个比喻把动机当成被悄悄从打印清单上漏掉的项目。"},{"no":"05","title":"An organization's priorities","titleCN":"机构的优先事项","definition":"the main goals or priorities that a company or institution is currently pursuing","definitionCN":"公司或机构当前着力追求的主要目标或优先事项","example":"Customer retention is now at the top of the company's agenda.","exampleCN":"留住客户现在排在公司的议程首位。","why":"A company also has things it must do. Calling them an agenda ranks them and signals that other matters can wait.","whyCN":"公司同样有必须做的事。把它们叫作 agenda，就是在给它们排序，并表明其他事情可以往后放。"},{"no":"06","title":"Agenda-setting in media","titleCN":"媒体议程设置","definition":"the power of media or political actors to decide which issues the public talks about","definitionCN":"媒体或政治行动者决定公众讨论哪些议题的能力","example":"The study examined how news outlets set the agenda during the election.","exampleCN":"这项研究考察了新闻媒体在选举期间如何设定议程。","why":"If an issue is not on the list, it is not discussed. Agenda-setting names the quiet power of choosing which items enter public conversation.","whyCN":"一个议题不在清单上，就不会被讨论。agenda-setting 指出的正是这种安静的力量：决定哪些项目进入公众谈话。"},{"no":"07","title":"Personal goals or self-interest","titleCN":"个人盘算","definition":"a person's own aims or interests, especially when they may conflict with the group's aims","definitionCN":"某人的个人目标或利益，尤指可能与群体目标冲突时","example":"He pushed the reform because it served his personal agenda.","exampleCN":"他推动这项改革，因为那符合他的个人盘算。","why":"Each person carries a private list of wants. When that list is suspected of overriding the shared list, agenda gains a slightly negative tone.","whyCN":"每个人都带着一份私人的愿望清单。当这份清单被怀疑压过共同清单时，agenda 就带上了一点贬义。"},{"no":"08","title":"The original sense: matters of practice","titleCN":"原义：实践事项","definition":"in 17th-century theology, matters of practice to be done, as opposed to credenda, matters to be believed","definitionCN":"17 世纪神学中指应当去做的实践事项，与表示“该信之事”的 credenda 相对","example":"Early theologians separated the agenda of Christian practice from its credenda of faith.","exampleCN":"早期神学家把基督教实践中该做的事，与信仰上该信的事区分开来。","why":"Agenda is a Latin gerundive plural, 'things that must be done'. The first English users kept exactly that contrast with credenda, 'things to be believed'.","whyCN":"agenda 是拉丁语 gerundive 的复数，意为“必须去做的事”。最早的英语使用者正是用它来和 credenda“必须相信的事”构成对照。"},{"no":"09","title":"Agenda view in a calendar","titleCN":"日历的议程视图","definition":"a list-style view in a calendar or app that shows upcoming events in time order","definitionCN":"日历或应用中以列表形式按时间顺序展示即将到来的事件的视图","example":"Switch to agenda view to see all of next week's meetings at once.","exampleCN":"切换到议程视图，就能一次看到下周的所有会议。","why":"Software borrowed the word because the view is again a plain ordered list of things to be done, stripped of the grid of a month page.","whyCN":"软件借用这个词，是因为这种视图又回到了一份朴素、有序的待办清单，去掉了月历页面的网格。"}],"etymology":{"intro":{"en":"Agenda entered English in the 1650s as a Latin plural, not as the plural of an English singular. It literally means 'things to be done', and its meeting sense is surprisingly late (1882).","cn":"agenda 于 17 世纪 50 年代以拉丁语复数形式进入英语，并不是某个英语单数名词的复数。它字面意为“该做的事”，而“会议议程”这一现代义项要到 1882 年才出现。"},"items":[{"era":"1650s","en":"First recorded in English in theology, meaning 'matters of practice', as opposed to credenda 'things to be believed'. It was borrowed directly from Latin agenda.","cn":"最早记录于 17 世纪 50 年代的英语神学文本，意为“实践事项”，与 credenda“该信之事”相对。它直接借自拉丁语 agenda。"},{"era":"LATIN","en":"Latin agenda is the neuter plural of agendus, the gerundive of agere 'to do, drive, act'. A gerundive is a verbal adjective meaning 'to be done' or 'must be done', so agenda means 'things that must be done'.","cn":"拉丁语 agenda 是 agendus 的中性复数，而 agendus 是 agere“做、驱动、行动”的 gerundive（动形词）。gerundive 是表示“应当被做、必须被做”的动词性形容词，因此 agenda 意为“必须去做的事情”。"},{"era":"PIE","en":"agere goes back to PIE *ag- 'to drive, draw out or forth, move'. The same root family includes act, agent, agile and the Greek agein 'to lead'.","cn":"agere 可追溯到原始印欧语 *ag-“驱赶、拉出、移动”。同一词根家族包括 act、agent、agile，以及希腊语 agein“引导”。"},{"era":"1882","en":"The modern sense 'items of business to be dealt with at a meeting' is attested by 1882. Before that, English agenda was chiefly a theological and later a general 'things to be done' term.","cn":"现代义“会议上要处理的事务项目”记录于 1882 年。在此之前，英语的 agenda 主要是神学术语，后来才泛指“待办之事”。"},{"era":"20C.","en":"During the 20th century agenda widened from a meeting list to any set of priorities: a political agenda, a reform agenda, a corporate agenda, and the suspicious hidden agenda.","cn":"20 世纪，agenda 从会议清单扩展到任何一组优先事项：政治议程、改革议程、公司议程，以及带猜疑意味的隐藏议程。"},{"era":"MODERN ENGLISH","en":"English now treats agenda as a singular countable noun with the plural agendas. The Latin singular agendum survives only as a rare technical form; agenda is not, in origin, an English plural.","cn":"现代英语把 agenda 当作可数单数名词，复数用 agendas。拉丁语单数 agendum 只作为罕用技术形式保留；从来源上说，agenda 并不是英语名词的复数。"}]},"similar":{"note":{"en":"The first group separates words close in form or root; the second group separates words that also name a plan or list. Form is checked before meaning.","cn":"第一组区分形近或同根词；第二组区分同样表示“计划、清单”的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"agendum","ipa":"/əˈdʒendəm/","tag":"derived singular","definition":"the rare Latin singular of agenda, meaning a single item to be done or discussed.","definitionCN":"agenda 罕用的拉丁语单数形式，指单个待办或待议项目。"},{"word":"agent","ipa":"/ˈeɪdʒənt/","tag":"same root","definition":"a person or thing that acts or does something. It shares the Latin root agere 'do', but is not a form of agenda.","definitionCN":"行动者；起作用的人或物。它同出拉丁语 agere“做”，但不是 agenda 的形式。"},{"word":"agency","ipa":"/ˈeɪdʒənsi/","tag":"same root","definition":"the capacity to act, or a business that acts for others. It comes from the same agere family.","definitionCN":"行动能力；代理机构。它出自同一个 agere 词族。"}]},{"heading":"NEAR MEANING","entries":[{"word":"schedule","ipa":"/ˈʃedjuːl/","tag":"timetable","definition":"a plan that lists times when events or tasks will happen. It stresses time rather than the items themselves.","definitionCN":"时间表；日程安排。它强调时间，而不是事项本身。"},{"word":"timetable","ipa":"/ˈtaɪmteɪbl/","tag":"fixed times","definition":"a detailed table of times for classes, trains, or events. It is more concrete and time-bound than agenda.","definitionCN":"课程表、时刻表。它比 agenda 更具体，更受时间约束。"},{"word":"programme","ipa":"/ˈprəʊɡræm/","tag":"list of events","definition":"a list or plan of events, especially for a performance or conference. It may include order but not necessarily tasks.","definitionCN":"节目单；活动安排。它可以有序，但不一定包含任务。"},{"word":"itinerary","ipa":"/aɪˈtɪnərəri/","tag":"travel plan","definition":"a planned route or schedule for a journey. It is tied to travel and places, not to business items.","definitionCN":"行程安排；旅行路线。它绑定旅行与地点，而不是事务项目。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"Agenda is Latin for 'things to be done', from agere 'do'; agent, act and action come from the same root.","cn":"agenda 在拉丁语里是“该做的事”，出自 agere“做”；agent、act、action 都同出这个词根。"},{"en":"agenda-setting is a real term in media studies for the power to decide which issues the public discusses.","cn":"agenda-setting 是媒体研究里的真实术语，指决定公众讨论哪些议题的权力。"},{"en":"hidden agenda is a fixed phrase for a secret motive behind a public plan.","cn":"hidden agenda 是固定短语，指公开计划背后的秘密动机。"},{"en":"Modern English pluralises it as agendas, even though the word itself arrived as a Latin plural.","cn":"现代英语把它的复数写成 agendas，尽管这个词本身是以拉丁语复数形式进来的。"},{"en":"agenda item is the standard phrase for one single line on a meeting list.","cn":"agenda item 是会议清单上单个项目的标准说法。"}],"abstract":[{"en":"Picture a sheet of paper on a table. Each line is one thing that must be done; when the last line is crossed out, the meeting can end.","cn":"想象桌上有一张纸，每一行都是一件必须完成的事；最后一行划掉，会议才能结束。"},{"en":"The word began as a Latin plural of obligation, not as a list of topics. That is why 'things to be done' and 'things to discuss' can be the same word.","cn":"这个词起初是拉丁语中表示义务的复数，而不是话题清单。这就是为什么“要做的事”和“要讨论的事”可以是同一个词。"},{"en":"An agenda can be open or hidden: the same list, depending on whether the real purpose is printed on it or kept in someone's pocket.","cn":"议程可以是公开的，也可以是隐藏的：同一张清单，区别只在于真实目的是印在纸上，还是藏在某个人的口袋里。"}]},"examples":[{"en":"The agenda for tomorrow's meeting was sent out this morning.","cn":"明天会议的议程今早已经发出。"},{"en":"Climate change is high on the government's agenda.","cn":"气候变化是政府议程上的重点。"},{"en":"She has a hidden agenda behind her friendly offer.","cn":"她友好的提议背后另有隐藏动机。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿珍打”——阿珍把待办事项一条条打在纸上，贴到会议室门口 → agenda 议程、待办清单","word":"agenda"},"root":"源自拉丁语 agenda“该做的事”，是 agere“做、驱动”的 gerundive 中性复数，不是英语原生复数。","sensesIntro":{"en":"Nine senses of agenda, all one sheet of paper: a list of things that must be done. The list can belong to a meeting, a person, a party, a company, a newspaper, or even a 17th-century theologian.","cn":"agenda 的九个义项都围绕同一张纸：一份必须去做的事情清单。这张清单可以属于一场会议、一个人、一个政党、一家公司、一家媒体，甚至一位 17 世纪的神学家。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sheet of paper headed 'things to be done', with one item on every line.","cn":"核心意象：一张写着“该做的事”的纸，每一行一个事项。"},"chain":["THINGS TO BE DONE","WRITTEN DOWN","ORDERED","SHARED WITH OTHERS","PRIORITISED","PURSUED"],"branches":[{"senses":"01 · 02","en":"LISTS OF TASKS: a meeting list and a private to-do list both write down what must be done.","cn":"任务清单：会议清单和私人待办清单都把必须做的事写下来。"},{"senses":"03 · 06","en":"POLITICAL AND MEDIA PRIORITIES: a party or newsroom decides which items enter public discussion.","cn":"政治与媒体优先事项：政党或新闻机构决定哪些事项进入公众讨论。"},{"senses":"04 · 07","en":"HIDDEN AND PERSONAL MOTIVES: a private list of wants may sit behind the public one.","cn":"隐藏与个人动机：一份私人的愿望清单可能藏在公开清单背后。"},{"senses":"05 · 09","en":"ORGANISED AND DIGITAL ORDER: a company ranks its goals, and a calendar lists events in order.","cn":"机构与数字排序：公司给目标排序，日历按顺序列出事件。"},{"senses":"08","en":"THEOLOGICAL ORIGIN: matters of practice to be done, set against matters of belief.","cn":"神学源头：应当去做的实践事项，与应当相信的信仰事项相对。"}]},"affixes":{"intro":{"en":"agenda is a borrowed Latin plural that English now treats as a singular noun. Its English family is mostly compounds built on the meeting or political sense, plus the ordinary plural and the rare Latin singular.","cn":"agenda 是一个借入的拉丁语复数，英语现在把它当作单数名词。它的英语词族主要是围绕会议义或政治义构成的复合词，再加上普通复数和罕用的拉丁语单数。"},"latinIntro":{"en":"The Latin root agere 'do, drive' is real and productive: agent, act, action, agile and agenda all descend from it. The gerundive ending -ndus is what makes agenda mean 'things that must be done'.","cn":"拉丁词根 agere“做、驱动”真实且能产：agent、act、action、agile 与 agenda 都源自它。正是 gerundive 词尾 -ndus 让 agenda 具有“必须去做的事情”之意。"},"items":[{"word":"agendas","structure":"agenda + -s (English plural)","meaning":"more than one agenda or set of priorities","meaningCN":"多个议程；多套优先事项（-s 构成英语复数）","example":"The two departments published separate agendas.","exampleCN":"两个部门公布了两份不同的议程。"},{"word":"agendum","structure":"agendum (Latin neuter singular)","meaning":"a single item on an agenda; now rare","meaningCN":"议程上的单个项目；现罕用（拉丁语中性单数）","example":"Fowler preferred agendum as the singular of agenda.","exampleCN":"福勒主张用 agendum 作为 agenda 的单数。"},{"word":"agenda item","structure":"agenda + item (compound)","meaning":"one entry on a meeting list","meaningCN":"议程项目（agenda + item 复合）","example":"The housing plan is the third agenda item.","exampleCN":"住房计划是第三个议程项目。"},{"word":"agenda-setting","structure":"agenda + setting (compound)","meaning":"the process of deciding which issues are discussed","meaningCN":"议程设置；决定讨论哪些议题的过程（复合词）","example":"Agenda-setting shapes what voters think about.","exampleCN":"议程设置塑造选民关注的内容。"},{"word":"agenda-setter","structure":"agenda + setter (compound)","meaning":"a person or group that decides the agenda","meaningCN":"议程设定者（复合词）","example":"The newspaper became the main agenda-setter in the city.","exampleCN":"这家报纸成了全城主要的议程设定者。"},{"word":"hidden agenda","structure":"hidden + agenda (compound)","meaning":"a secret motive behind a public plan","meaningCN":"隐藏议程；公开计划背后的秘密动机（复合词）","example":"They suspected a hidden agenda in the offer.","exampleCN":"他们怀疑这个提议另有隐藏动机。"},{"word":"policy agenda","structure":"policy + agenda (compound)","meaning":"the set of policies an actor intends to pursue","meaningCN":"政策议程（复合词）","example":"Health care dominates the policy agenda this year.","exampleCN":"医疗今年占据政策议程的主导位置。"},{"word":"corporate agenda","structure":"corporate + agenda (compound)","meaning":"a company's current priorities","meaningCN":"公司议程；企业优先事项（复合词）","example":"The merger fits the corporate agenda.","exampleCN":"这次并购符合公司的议程。"},{"word":"agenda-driven","structure":"agenda + -driven (compound adjective)","meaning":"controlled or shaped by a particular agenda","meaningCN":"受特定议程驱动的（复合形容词）","example":"Critics called the report agenda-driven.","exampleCN":"批评者称这份报告是被议程驱动的。"},{"word":"agenda-building","structure":"agenda + building (compound)","meaning":"the process by which an issue is placed on the public agenda","meaningCN":"议程构建；把议题推上公共议程的过程（复合词）","example":"Agenda-building takes years of campaigning.","exampleCN":"议程构建需要多年造势。"},{"word":"agenda-setting theory","structure":"agenda-setting + theory (compound)","meaning":"the media-studies theory that coverage shapes public priorities","meaningCN":"议程设置理论（复合词）","example":"Agenda-setting theory grew out of election studies.","exampleCN":"议程设置理论源自选举研究。"}],"latinEntries":[{"word":"agent","structure":"agent- (present participle of agere 'do')","meaning":"one who acts or does","meaningCN":"行动者；代理人"},{"word":"act","structure":"actus, past participle of agere 'do, drive'","meaning":"a deed; to do or perform","meaningCN":"行为；行动"},{"word":"action","structure":"actionem, noun of action from agere","meaning":"the doing of something","meaningCN":"行动；作为"},{"word":"agile","structure":"agilis 'easy to move', from agere","meaning":"able to move quickly and easily","meaningCN":"敏捷的；灵活的"}]}},{"word":"aggressive","ipa_uk":"/əˈɡresɪv/","ipa_us":"/əˈɡresɪv/","definition_zh":"好斗的；强势的","definition_en":"ready to attack or confront others, or very forceful and determined in pursuing a goal","core_image":"一只向前踏出半步、随时准备冲上去的身体","scene":"The dog bared its teeth and took an aggressive step toward the fence.","sceneCN":"这里 aggressive 是「好斗的、有攻击性的」（第 1 个义项：人或动物摆出攻击姿态）；句意：那只狗龇着牙，朝栅栏好斗地迈出一步。图中可辨识物件：龇牙的狗、竖起的背毛、铁栅栏、绷紧的牵引绳。","pos":[{"tag":"adj.","zh":"好斗的；有攻击性的；侵略的；积极进取的；强烈的"}],"collocations":[{"phrase":"aggressive behaviour","zh":"攻击性行为"},{"phrase":"aggressive marketing","zh":"强势营销"},{"phrase":"aggressive treatment","zh":"积极的强化治疗"},{"phrase":"aggressive growth","zh":"激进的增长策略"},{"phrase":"passive-aggressive","zh":"被动攻击式的"}],"forms":[{"label":"比较级（more）","form":"more aggressive"},{"label":"最高级（most）","form":"most aggressive"}],"derivatives":[{"word":"aggression","pos":"n.","zh":"侵略；攻击行为；侵犯"},{"word":"aggressor","pos":"n.","zh":"侵略者；攻击者"},{"word":"aggressively","pos":"adv.","zh":"强势地；带有攻击性地"},{"word":"aggressiveness","pos":"n.","zh":"好斗；进取心"}],"senses":[{"no":"01","title":"Ready to attack physically","titleCN":"身体上的攻击性","definition":"ready or likely to attack or fight, used of people or animals","definitionCN":"指人或动物随时可能发起攻击或打斗","example":"The dog became aggressive whenever a stranger reached the gate.","exampleCN":"只要有陌生人靠近大门，那只狗就变得好斗。","why":"The Latin verb aggredi means 'to step toward'. The first English sense is exactly that: a creature steps toward another in order to attack, not merely to stand its ground.","whyCN":"拉丁动词 aggredi 意为“朝……迈步”。最早的英语义项正是这个：一个生物朝另一个迈步，目的是攻击，而不只是守住原地。"},{"no":"02","title":"Hostile and confrontational manner","titleCN":"敌意与对抗的态度","definition":"behaving in an angry, threatening, or confrontational way in speech or attitude","definitionCN":"在言语或态度上表现出愤怒、威胁或对抗","example":"His aggressive tone made the interview uncomfortable for everyone.","exampleCN":"他咄咄逼人的语气让在场所有人都感到不适。","why":"A step forward can be verbal as well as physical. Aggressive words push into the other person's space and force a response.","whyCN":"向前一步可以是言语上的，也可以是身体上的。带攻击性的话语会挤进对方的空间，迫使对方回应。"},{"no":"03","title":"Military attack or invasion","titleCN":"军事进攻、侵略","definition":"of a country or army, acting to attack or invade another","definitionCN":"指国家或军队主动攻击、入侵他国","example":"The report condemned the country's aggressive military moves near the border.","exampleCN":"报告谴责该国在边境附近的侵略性军事行动。","why":"An army that advances into foreign territory performs the original step at national scale. Here aggression is organised and collective.","whyCN":"一支军队推进到别国领土，就是把最初那个“迈步”放大到国家尺度。这里的攻击是有组织、集体性的。"},{"no":"04","title":"Forceful business or sales tactics","titleCN":"强硬的商业或销售手段","definition":"very forceful and determined in trying to win customers, market share, or deals","definitionCN":"为赢得客户、市场份额或交易而非常强势、坚决","example":"The startup ran an aggressive marketing campaign across three cities.","exampleCN":"这家初创公司在三座城市开展了强势的营销活动。","why":"In business no one is physically attacked, but a company still pushes into the competitor's territory. The same forward step is now measured in sales.","whyCN":"商业里没有人真的被攻击，但公司仍会挤进对手的地盘。同一个“向前一步”，这里用销售额来衡量。"},{"no":"05","title":"Intensive medical treatment","titleCN":"积极的强化治疗","definition":"of medical treatment, strong and intensive, used when a disease must be fought hard","definitionCN":"指医疗手段强烈、密集，用于必须全力对抗的疾病","example":"Doctors began aggressive treatment as soon as the scan showed the tumour.","exampleCN":"扫描发现肿瘤后，医生立即开始了积极的强化治疗。","why":"Medicine borrows the word for a fight: the treatment attacks the disease with full force rather than waiting. The patient is not the target of the aggression.","whyCN":"医学借用了这个“打斗”词：治疗以全力攻击疾病，而不是等待。病人并不是攻击的对象。"},{"no":"06","title":"Bold growth or investment strategy","titleCN":"激进的增长或投资策略","definition":"aiming for rapid growth or high returns, often accepting greater risk","definitionCN":"追求快速增长或高回报，通常接受更大风险","example":"The fund follows an aggressive growth strategy focused on new technology.","exampleCN":"该基金采取聚焦新技术的激进增长策略。","why":"An investor who takes the first step into risk is aggressive in the financial sense: bold, forward, and not waiting for safety.","whyCN":"敢于先迈出一步进入风险的投资者，在金融意义上就是 aggressive：大胆、向前、不等着安全。"},{"no":"07","title":"Attacking style in sport","titleCN":"运动中的进攻风格","definition":"playing in an attacking way, always trying to score rather than defend","definitionCN":"以进攻方式比赛，始终试图得分而不是防守","example":"Their aggressive pressing forced the other team into mistakes.","exampleCN":"他们积极的前场逼抢迫使对方频频失误。","why":"A team that presses forward is literally advancing on the opponent. Sport keeps the military shape but removes the harm.","whyCN":"一支向前压迫的球队，字面上就是在向对手推进。体育保留了军事的形状，却去掉了伤害。"},{"no":"08","title":"Self-assertive, pushy personality","titleCN":"自我主张强、爱出头的性格","definition":"confident and forceful in asserting oneself, sometimes to the point of being pushy; a psychological and colloquial sense","definitionCN":"自信而强势地表达自我，有时到了爱出头的程度；心理学与口语义","example":"In meetings she is aggressive in the sense of never letting her point be ignored.","exampleCN":"开会时她很强势，意思是她绝不让自己的观点被忽略。","why":"Freud's translators used aggressive for inner drives from 1913; by 1931 English speakers had stretched it to everyday people who push their own claims forward.","whyCN":"从 1913 年起，弗洛伊德的译者用 aggressive 指内在驱力；到 1931 年，英语使用者又把它扩展到日常中爱把自己的主张往前推的人。"},{"no":"09","title":"Fast-spreading disease","titleCN":"侵袭性强的疾病","definition":"of a disease or tumour, growing or spreading quickly and needing urgent attention","definitionCN":"指疾病或肿瘤生长、扩散迅速，需要紧急处理","example":"The biopsy showed an aggressive form of the disease.","exampleCN":"活检显示这是一种侵袭性很强的疾病。","why":"A disease that invades healthy tissue behaves like an attacker. The word describes speed and force, not the patient's character.","whyCN":"侵入健康组织的疾病，行为就像一名攻击者。这个词描述的是速度与力度，而不是病人的性格。"}],"etymology":{"intro":{"en":"Aggressive is a modern English adjective, first recorded in 1791. Its Latin parts are ad- 'to' plus gradi 'step', so the word begins as 'stepping toward' someone.","cn":"aggressive 是近代英语形容词，最早记录于 1791 年。它的拉丁成分是 ad-“向”加 gradi“迈步”，所以这个词的起点是“朝某人迈过去”。"},"items":[{"era":"1791","en":"First recorded as an adjective meaning 'tending to make the first attack', formed with the English suffix -ive on the Latin stem aggress-.","cn":"最早记录于 1791 年，作形容词，意为“倾向于先发起攻击”，由英语后缀 -ive 加在拉丁词干 aggress- 上构成。"},{"era":"LATIN","en":"The stem aggress- is the past-participle stem of aggredi 'to approach, go to, attack'. Aggredi joins ad- 'to' and gradi 'to step, walk, go'.","cn":"词干 aggress- 是 aggredi“接近、走向、攻击”的过去分词词干。aggredi 由 ad-“向”与 gradi“迈步、走、去”组成。"},{"era":"LATIN / PIE","en":"gradi comes from gradus 'a step, pace, degree', from PIE *ghredh- 'to walk, go'. The same root gives grade, gradual, progress, congress and transgress.","cn":"gradi 出自 gradus“一步、步伐、等级”，再上溯到原始印欧语 *ghredh-“走、去”。同一词根还给出 grade、gradual、progress、congress 和 transgress。"},{"era":"1913","en":"The psychological sense appears in 1913, first in translations of Freud, where aggression is treated as an inner drive rather than a battlefield act.","cn":"心理学义项出现于 1913 年，最早见于弗洛伊德著作的译本；在那里，aggression 被当作内在驱力，而不是战场上的行为。"},{"era":"1931","en":"The colloquial sense 'self-assertive, pushy' is recorded from 1931. It moves the word from physical attack to social behaviour.","cn":"口语义“自我主张强、爱出头”记录于 1931 年。这个词由此从身体攻击转向社交行为。"},{"era":"MID-20TH–PRESENT","en":"Later uses spread to business (aggressive marketing), medicine (aggressive treatment), sport and finance. Modern English can use it to praise drive or condemn violence; context decides.","cn":"此后这个词扩展到商业（强势营销）、医学（积极治疗）、体育和金融。现代英语既可以用它称赞干劲，也可以用它谴责暴力，全看语境。"}]},"similar":{"note":{"en":"The first group separates words close in form or root; the second group separates words with a nearby meaning. Form is checked before meaning.","cn":"第一组区分形近或同根词；第二组区分意思相近的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aggression","ipa":"/əˈɡreʃn/","tag":"derived noun","definition":"the noun from aggressive: an attack or hostile act, or a strong inner drive.","definitionCN":"aggressive 派生的名词：攻击行为、侵犯，或强烈的内在驱力。"},{"word":"aggressor","ipa":"/əˈɡresə/","tag":"same root","definition":"the person or country that starts an attack. It marks the one who steps toward the other.","definitionCN":"发起攻击的人或国家；标记那个朝对方迈步的一方。"},{"word":"regressive","ipa":"/rɪˈɡresɪv/","tag":"opposite direction","definition":"moving backward or returning to an earlier state. It shares the -gressive shape but reverses the direction.","definitionCN":"后退的；退回早前状态的。它与 aggressive 共享 -gressive 外形，却方向相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hostile","ipa":"/ˈhɒstaɪl/","tag":"attitude","definition":"unfriendly and opposed. It names the feeling or stance more than the forward movement.","definitionCN":"敌对的；不友好的。它更强调敌意态度，而不是向前推进的动作。"},{"word":"assertive","ipa":"/əˈsɜːtɪv/","tag":"confidence","definition":"confident in stating one's views without attacking others. It is the positive cousin of sense 8.","definitionCN":"自信表达观点的；坚定而不攻击他人。它是第 8 个义项正面的近亲。"},{"word":"forceful","ipa":"/ˈfɔːsfl/","tag":"strength","definition":"using great strength or pressure to get a result. It stresses power, not hostility.","definitionCN":"强有力的；用大力气达成结果。它强调力量，而不强调敌意。"},{"word":"belligerent","ipa":"/bəˈlɪdʒərənt/","tag":"warlike","definition":"eager to fight or arguing aggressively. It is more openly warlike than aggressive.","definitionCN":"好战的；爱吵架的。它比 aggressive 更公开地带有战争意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"aggress + -ive: the suffix makes an adjective of 'stepping toward', and aggression is its noun.","cn":"aggress + -ive：后缀把“朝前迈步”变成形容词，名词则是 aggression。"},{"en":"aggressor is the one who steps first; the word keeps the Latin picture of a body moving toward another.","cn":"aggressor 是先迈步的那一方；这个词保留了拉丁语里身体朝另一个人移动的画面。"},{"en":"passive-aggressive is a real compound from psychology: hostility expressed indirectly instead of openly.","cn":"passive-aggressive 是心理学里的真实复合词：敌意不公开表达，而是间接流露。"},{"en":"microaggression is a modern coinage for a small, often unintended slight.","cn":"microaggression 是现代新造词，指微小、往往无意的冒犯。"},{"en":"gradus 'step' also gives grade, degree and progress, so aggressive shares a root with going forward step by step.","cn":"gradus“一步”还给出 grade、degree、progress，所以 aggressive 与“一步步向前”同根。"}],"abstract":[{"en":"Picture a body taking half a step toward another body. The step can be a fist, a word, a sales pitch, or a disease invading tissue.","cn":"想象一个身体朝另一个身体迈出半步。这一步可以是一只拳头、一句话、一次推销，也可以是疾病侵入组织。"},{"en":"The word always joins two parts: direction toward, and a step. Without the step there is only hostility; with it, there is aggression.","cn":"这个词始终由两部分拼成：朝向，以及一步。没有那一步，只剩敌意；有了那一步，才成为攻击。"},{"en":"Modern English splits the same energy in two: a forward, determined drive that wins markets, and a violent push that hurts people.","cn":"现代英语把同一股能量分成两半：赢得市场的向前干劲，和伤害他人的暴力推进。"}]},"examples":[{"en":"The animal becomes aggressive when it feels trapped.","cn":"动物感到被困住时会变得好斗。"},{"en":"The company adopted an aggressive strategy to double its market share.","cn":"公司采取了激进策略，力争把市场份额翻倍。"},{"en":"The doctor recommended aggressive treatment to stop the infection.","cn":"医生建议采用积极的强化治疗来控制感染。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“啊，格瑞西五”——啊，格瑞西往前五步就冲了上去 → aggressive 好斗的、有攻击性的","word":"aggressive"},"root":"源自拉丁语 aggredi“走向、攻击”，由 ad-“向”+ gradi“迈步”构成；核心是“朝对方迈出一步”。","sensesIntro":{"en":"Nine senses of aggressive, all one forward step: a body attacks, a voice confronts, an army invades, a company pushes, a treatment fights, an investor risks, a team presses, a person asserts, a disease spreads.","cn":"aggressive 的九个义项都是同一个“向前一步”：身体攻击、言语对抗、军队入侵、公司强推、治疗强攻、投资者冒险、球队压迫、个人主张、疾病扩散。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body takes a step toward another body, ready to strike.","cn":"核心意象：一个身体朝另一个身体迈出一步，随时准备出手。"},"chain":["STAND APART","STEP TOWARD","MAKE CONTACT","APPLY FORCE","TAKE GROUND","KEEP PUSHING"],"branches":[{"senses":"01 · 02","en":"PHYSICAL AND SOCIAL ATTACK: a person or animal steps toward conflict, with body or voice.","cn":"身体与社交攻击：人或动物朝冲突迈步，用身体或言语。"},{"senses":"03 · 07","en":"ORGANISED OFFENCE: an army or a team pushes into the opponent's ground.","cn":"有组织的进攻：军队或球队推进到对手的地盘。"},{"senses":"04 · 06","en":"FORCE IN BUSINESS AND FINANCE: a company or investor pushes hard for share, growth and return.","cn":"商业与金融的强势：公司或投资者为份额、增长和回报强力推进。"},{"senses":"05 · 09","en":"MEDICAL INTENSITY: a treatment fights a disease with full force, or a disease invades tissue fast.","cn":"医学强度：治疗全力对抗疾病，或疾病快速侵入组织。"},{"senses":"08","en":"PSYCHOLOGICAL SELF-ASSERTION: a person pushes their own claims forward in a group.","cn":"心理上的自我主张：一个人在群体中把自己的主张往前推。"}]},"affixes":{"intro":{"en":"aggressive has a productive English family. Most forms attach ordinary suffixes to aggressive or to its noun aggression; the compound words are real modern coinages in psychology and media writing.","cn":"aggressive 有能产的英语词族。多数形式是在 aggressive 或其名词 aggression 后加普通后缀；复合词则是心理学和媒体写作中真实存在的现代新造词。"},"latinIntro":{"en":"The Latin root gradi 'to step' is real and productive: grade, gradual, progress, congress and transgress all descend from gradus. Aggredi adds ad- 'to' to the same step.","cn":"拉丁词根 gradi“迈步”真实且能产：grade、gradual、progress、congress、transgress 都源自 gradus。aggredi 只是给同一步加上 ad-“向”。"},"items":[{"word":"aggression","structure":"aggress + -ion (noun of action)","meaning":"an attack or hostile act; also a strong drive","meaningCN":"侵略；攻击行为；攻击性（-ion 构成行为名词）","example":"The invasion was condemned as aggression.","exampleCN":"这次入侵被谴责为侵略。"},{"word":"aggressor","structure":"aggress + -or (person who acts)","meaning":"a person or country that starts an attack","meaningCN":"侵略者；攻击者（-or 表示施动者）","example":"The aggressor refused to withdraw its troops.","exampleCN":"侵略方拒绝撤军。"},{"word":"aggressively","structure":"aggressive + -ly (adverb)","meaning":"in a forceful or hostile way","meaningCN":"强势地；带有攻击性地（-ly 构成副词）","example":"The firm marketed its app aggressively.","exampleCN":"这家公司强势推广它的应用。"},{"word":"aggressiveness","structure":"aggressive + -ness (quality noun)","meaning":"the quality of being aggressive","meaningCN":"好斗；进取性（-ness 构成性质名词）","example":"The test measures aggressiveness in dogs.","exampleCN":"这项测试测量狗的攻击性。"},{"word":"aggress","structure":"back-formation from aggression","meaning":"to attack or begin a quarrel (rare verb)","meaningCN":"攻击；挑起争端（罕用动词，由 aggression 逆构）","example":"He did not want to aggress against his neighbour.","exampleCN":"他不想对邻居挑起事端。"},{"word":"nonaggressive","structure":"non- (not) + aggressive","meaning":"not aggressive; calm or harmless","meaningCN":"不具攻击性的；温和的（non- 表示否定）","example":"The breed is known as nonaggressive.","exampleCN":"这个犬种以温顺著称。"},{"word":"overaggressive","structure":"over- (too much) + aggressive","meaning":"too forceful or too ready to attack","meaningCN":"过度激进的；过于好斗的（over- 表示过度）","example":"Overaggressive drivers cause many crashes.","exampleCN":"过度强势的司机造成许多事故。"},{"word":"passive-aggressive","structure":"passive + aggressive (compound)","meaning":"showing hostility indirectly rather than openly","meaningCN":"被动攻击式的；以间接方式表现敌意（复合词）","example":"He answered with a passive-aggressive remark.","exampleCN":"他用一句被动攻击式的话回应。"},{"word":"microaggression","structure":"micro- (small) + aggression","meaning":"a small, often unintended slight against a group","meaningCN":"微冒犯；对某群体的细微、常无意的冒犯（micro- 表示微小）","example":"The comment was widely criticised as a microaggression.","exampleCN":"这句话被广泛批评为微冒犯。"},{"word":"autoaggression","structure":"auto- (self) + aggression","meaning":"aggression directed against oneself, in psychiatry","meaningCN":"自我攻击（精神病学中指向自身的攻击）（auto- 表示自身）","example":"Autoaggression can accompany severe depression.","exampleCN":"自我攻击可能伴随重度抑郁。"},{"word":"aggressivity","structure":"aggressive + -ity (quality)","meaning":"the quality of being aggressive; a rare synonym of aggressiveness","meaningCN":"攻击性；好斗性（-ity 构成性质名词，较罕用）","example":"The study rated the patients' aggressivity.","exampleCN":"这项研究评估了病人的攻击性。"}],"latinEntries":[{"word":"grade","structure":"gradus 'step, degree'","meaning":"a step, level, or rank","meaningCN":"等级；级别；分数"},{"word":"progress","structure":"pro- 'forward' + gradi 'step'","meaning":"to move forward step by step","meaningCN":"前进；进展"},{"word":"congress","structure":"con- 'together' + gradi 'step'","meaning":"a coming together; a formal assembly","meaningCN":"国会；代表大会"},{"word":"transgress","structure":"trans- 'across' + gradi 'step'","meaning":"to step across a limit; to violate","meaningCN":"越界；违犯"}]}},{"word":"agriculture","ipa_uk":"/ˈæɡrɪkʌltʃə/","ipa_us":"/ˈæɡrɪkʌltʃər/","definition_zh":"农业；耕作","definition_en":"the practice or science of farming, including growing crops and raising animals","core_image":"一块被犁开的田，种子落进笔直的垄沟","scene":"The valley's economy depends on agriculture, with wheat fields and dairy farms side by side.","sceneCN":"这里 agriculture 是「农业」（第 1 个义项：耕作土地、种植作物与饲养家畜的整体生产活动）；句意：这个山谷的经济依赖农业，麦田和奶牛场并排分布。图中可辨识物件：犁沟、麦穗、奶牛、红色谷仓。","pos":[{"tag":"n.","zh":"农业；农耕；农学（不可数）"}],"collocations":[{"phrase":"agriculture sector","zh":"农业部门"},{"phrase":"sustainable agriculture","zh":"可持续农业"},{"phrase":"modern agriculture","zh":"现代农业"},{"phrase":"agriculture and forestry","zh":"农林"}],"forms":[{"label":"不可数（无复数形式）","form":"agriculture（无屈折变化）"}],"derivatives":[{"word":"agricultural","pos":"adj.","zh":"农业的；农艺的"},{"word":"agriculturist","pos":"n.","zh":"农学家；务农者"},{"word":"agribusiness","pos":"n.","zh":"农业综合企业"},{"word":"agronomy","pos":"n.","zh":"农学；农艺学"}],"senses":[{"no":"01","title":"Farming as a practice and industry","titleCN":"农业：耕作与养殖的总称","definition":"the practice or business of growing crops and raising animals for food, fibre, or other products","definitionCN":"种植作物、饲养家畜以获取食物、纤维或其他产品的生产活动或行业","example":"Agriculture employs nearly half the people in the region.","exampleCN":"农业雇用了该地区近一半的人。","why":"The Latin phrase agri cultura means 'cultivation of the field'. English shortened it into one word for the whole work of making land produce.","whyCN":"拉丁短语 agri cultura 意为“对田地的耕作”。英语把它缩成一个词，指让土地产出的一切劳作。"},{"no":"02","title":"Cultivation of the land","titleCN":"土地的耕作","definition":"the act of preparing and working the soil to grow crops","definitionCN":"翻整、耕作土壤以种植作物的行为","example":"The first settlers brought agriculture to the river valley.","exampleCN":"最早的定居者把农耕带到了河谷。","why":"Before it named an industry, agriculture named an action: tilling the ground. The field is the object, and cultura supplies the idea of tending.","whyCN":"在指一个行业之前，agriculture 指的是一个动作：耕整土地。田地是对象，cultura 提供“照料、耕作”的意思。"},{"no":"03","title":"The science of farming","titleCN":"农学","definition":"the scientific study of farming, including soil, crops, and animal production","definitionCN":"研究耕作的科学，包括土壤、作物与动物生产","example":"She studied agriculture at the state university.","exampleCN":"她在州立大学学习农学。","why":"From about 1600 the word also named the systematic knowledge behind farming, not just the labour. A science can be taught, tested and improved.","whyCN":"约从 1600 年起，这个词也指耕作背后的系统知识，而不只是体力劳动。科学可以被教授、检验和改进。"},{"no":"04","title":"Subsistence agriculture","titleCN":"自给农业","definition":"farming that produces mainly enough food for the farmer's own family, with little left to sell","definitionCN":"主要生产足够农户自家食用的粮食、几乎没有余粮出售的农业","example":"Most families here depend on subsistence agriculture.","exampleCN":"这里大多数家庭依靠自给农业。","why":"When the harvest is eaten rather than sold, the purpose of farming is survival. The word names the scale and goal, not a different activity.","whyCN":"当收成是被吃掉而不是卖掉时，耕作的目的就是生存。这个词描述的是规模与目标，而不是另一种活动。"},{"no":"05","title":"Commercial agriculture","titleCN":"商业农业","definition":"farming organised to sell produce in markets for profit","definitionCN":"以在市场出售产品获利为目的而组织的农业","example":"Commercial agriculture replaced small family farms in the plains.","exampleCN":"在平原地区，商业农业取代了小型家庭农场。","why":"The same land and crops, but the harvest now enters a market. Agriculture becomes a business whose output is measured in sales.","whyCN":"同样的土地和作物，但收成现在进入市场。农业变成一门生意，产出用销售额来衡量。"},{"no":"06","title":"Sustainable agriculture","titleCN":"可持续农业","definition":"farming that meets present needs without damaging soil, water, and future production","definitionCN":"在不损害土壤、水源与未来生产能力的前提下满足当前需求的农业","example":"The programme teaches sustainable agriculture to reduce chemical use.","exampleCN":"该项目教授可持续农业，以减少化学品使用。","why":"A newer goal is added to the old word: the land must keep producing. Sustainable marks farming that does not exhaust the field it depends on.","whyCN":"一个更新的目标被加到旧词上：土地必须持续产出。sustainable 标记的是不耗尽所依赖田地的耕作方式。"},{"no":"07","title":"Intensive agriculture","titleCN":"集约农业","definition":"farming that uses large amounts of labour, capital, or chemicals on a small area to raise output","definitionCN":"在较小面积上投入大量劳动力、资本或化学品以提高产量的农业","example":"Intensive agriculture can feed more people from less land.","exampleCN":"集约农业能用更少的土地养活更多的人。","why":"Intensity is force concentrated on one place. Intensive farming presses more inputs onto each hectare, the opposite of spreading out over large areas.","whyCN":"强度就是把力量集中在一点。集约农业把更多投入压到每公顷土地上，与在大片区域粗放铺开正好相反。"},{"no":"08","title":"Urban agriculture","titleCN":"都市农业","definition":"growing food inside or around cities, on rooftops, yards, or community plots","definitionCN":"在城市内部或周边，利用屋顶、庭院或社区地块种植食物","example":"Urban agriculture has turned empty lots into vegetable gardens.","exampleCN":"都市农业把空地变成了菜园。","why":"The word's root is ager 'field'. Putting agriculture in a city stretches that root to its limit: the plot replaces the field, but the act of cultivation remains.","whyCN":"这个词的词根是 ager“田地”。把 agriculture 放进城市，就是把词根拉到极限：地块取代了田野，但耕作行为仍在。"},{"no":"09","title":"Agriculture as an economic sector","titleCN":"作为经济部门的农业","definition":"the sector of a national economy that produces crops and livestock, often measured as a share of GDP or employment","definitionCN":"国民经济中生产作物与牲畜的部门，常以占 GDP 或就业的比例衡量","example":"Agriculture accounts for about five percent of the country's GDP.","exampleCN":"农业约占该国 GDP 的百分之五。","why":"Statistics need a name for the whole sector. Agriculture becomes a column in the economy, beside industry and services.","whyCN":"统计需要一个名字来指整个部门。农业于是成为经济表中的一栏，与工业和服务业并列。"}],"etymology":{"intro":{"en":"Agriculture was borrowed in the mid-15th century from Latin agricultura, a contraction of agri cultura 'cultivation of the field'. Its first English uses were figurative.","cn":"agriculture 于 15 世纪中期借自拉丁语 agricultura，而 agricultura 是 agri cultura“对田地的耕作”的缩合形式。它最早的英语用法是比喻性的。"},"items":[{"era":"MID-15C.","en":"First recorded in English in the mid-15th century, at first in figurative use, especially of God's cultivation of the soul.","cn":"最早记录于 15 世纪中期的英语，起初是比喻用法，尤其指上帝对灵魂的耕耘。"},{"era":"LATE LATIN","en":"From Late Latin agricultura 'cultivation of the land', a contraction of agri cultura 'cultivation of the field'.","cn":"来自晚期拉丁语 agricultura“对土地的耕作”，它是 agri cultura“对田地的耕作”的缩合形式。"},{"era":"LATIN","en":"agri is the genitive of ager 'field, land'; cultura comes from colere 'to tend, guard, till, cultivate'.","cn":"agri 是 ager“田地、土地”的属格；cultura 出自 colere“照料、守护、耕种、栽培”。"},{"era":"PIE","en":"ager goes back to PIE *agro- 'field'. Colere is also the source of culture, cultivate and colony, so 'cultivating a field' and 'cultivating the mind' share one root.","cn":"ager 可追溯到原始印欧语 *agro-“田地”。colere 同样是 culture、cultivate、colony 的来源，因此“耕作田地”和“培养心智”共享一个词根。"},{"era":"C. 1600","en":"By about 1600 agriculture was used for 'the science or practice of farming the land', close to the modern sense.","cn":"约到 1600 年，agriculture 已用于表示“耕作土地的科学或实践”，接近现代义。"},{"era":"MODERN ENGLISH","en":"Old English expressed the idea with eorðtilþ, and Middle English with lond-tilling or husbonding; the Latin-derived word won out. Modern agriculture also covers agribusiness and agricultural science.","cn":"古英语用 eorðtilþ 表达这一概念，中古英语用 lond-tilling 或 husbonding；最终拉丁来源的词胜出。现代 agriculture 还覆盖农业综合企业与农业科学。"}]},"similar":{"note":{"en":"The first group separates words close in form or root; the second group separates words with a nearby meaning. Form is checked before meaning.","cn":"第一组区分形近或同根词；第二组区分意思相近的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"agricultural","ipa":"/ˌæɡrɪˈkʌltʃərəl/","tag":"derived adjective","definition":"relating to agriculture; the everyday adjective built from the noun.","definitionCN":"农业的；由名词 agriculture 构成的日常形容词。"},{"word":"agribusiness","ipa":"/ˈæɡrɪbɪznəs/","tag":"compound","definition":"large-scale farming treated as an industry, including supply, processing and distribution.","definitionCN":"把大规模农业当作产业，包括供应、加工与流通。"},{"word":"agrarian","ipa":"/əˈɡreəriən/","tag":"same field","definition":"relating to land, especially farmland or land ownership. It is an adjective, not a form of agriculture.","definitionCN":"土地的，尤指农田或土地所有权；是形容词，并非 agriculture 的形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"farming","ipa":"/ˈfɑːmɪŋ/","tag":"plain activity","definition":"the activity of growing crops or raising animals. It is the plain everyday word behind agriculture.","definitionCN":"耕种或饲养家畜的活动；是 agriculture 背后最朴素的日常词。"},{"word":"cultivation","ipa":"/ˌkʌltɪˈveɪʃn/","tag":"working the soil","definition":"the act of preparing land and growing crops, or of developing a skill. It stresses the action more than the industry.","definitionCN":"耕作土地、种植作物，或培养技能；比 agriculture 更强调动作。"},{"word":"husbandry","ipa":"/ˈhʌzbəndri/","tag":"careful management","definition":"the careful management of soil, crops, or animals. It is an older word for skilled farming.","definitionCN":"对土壤、作物或动物的精心管理；是表示精细农作的较老词。"},{"word":"agronomy","ipa":"/əˈɡrɒnəmi/","tag":"science","definition":"the science of crop production and soil management. It is the scientific side of agriculture, from Greek nomos 'law'.","definitionCN":"作物生产与土壤管理的科学；是 agriculture 的科学侧面，出自希腊语 nomos“法则”。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"agri- comes from ager 'field' and culture from colere 'till', so agriculture is literally 'field-tilling'.","cn":"agri- 出自 ager“田地”，culture 出自 colere“耕作”，所以 agriculture 字面就是“耕田”。"},{"en":"agricultural is the everyday adjective for farms, policy and land.","cn":"agricultural 是农场、政策与土地话题中最常用的形容词。"},{"en":"agribusiness joins agri- with business, naming farming as an industry.","cn":"agribusiness 把 agri- 与 business 拼在一起，把农业命名为一门产业。"},{"en":"agronomy is the science of farming, from Greek nomos 'law'; it is agriculture studied as rules.","cn":"agronomy 是农学，出自希腊语 nomos“法则”；它是把农业当作规则来研究。"},{"en":"culture first meant tilling land before it meant the arts, so agriculture and culture share a root.","cn":"culture 在指艺术之前，先指耕作土地，所以 agriculture 与 culture 同根。"}],"abstract":[{"en":"Picture a plough opening one straight line in the soil. The line is agri 'field'; the care that keeps it producing is cultura.","cn":"想象犁在土壤里开出一条笔直的沟。这条线是 agri“田地”；让它持续产出的照料就是 cultura。"},{"en":"The word starts as an action, becomes an industry, then a science, then a column in the national accounts.","cn":"这个词从一个动作开始，变成一门行业，再成为一门科学，最后成为国民账户里的一栏。"},{"en":"Agriculture is always a bargain with the land: take a harvest now, but keep the field able to give another one later.","cn":"农业始终是与土地的一笔交易：现在拿走一季收成，但要让田地以后还能再给一季。"}]},"examples":[{"en":"Agriculture remains the backbone of the local economy.","cn":"农业仍是当地经济的支柱。"},{"en":"They are studying how climate change affects agriculture.","cn":"他们正在研究气候变化如何影响农业。"},{"en":"Sustainable agriculture protects both soil and farmers' incomes.","cn":"可持续农业既保护土壤，也保护农民收入。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“爱格瑞靠茶”——爱格瑞一家靠种茶过日子 → agriculture 农业、农耕","word":"agriculture"},"root":"源自拉丁语 agri cultura“对田地的耕作”，agri 是 ager“田地”的属格，cultura 出自 colere“耕种、照料”。","sensesIntro":{"en":"Nine senses of agriculture, all one field being worked: a practice, an action, a science, a way of surviving, a business, a promise to the future, a city plot, and a line in the economy.","cn":"agriculture 的九个义项都围绕同一块被耕作的田：一种实践、一个动作、一门科学、一种生存方式、一门生意、对未来的承诺、城市里的一块地，以及经济表中的一行。"},"semanticMap":{"core":{"en":"CORE IMAGE: a plough opens a straight furrow, and seed falls into it.","cn":"核心意象：犁开出一条笔直的垄沟，种子落进沟里。"},"chain":["FIELD","TILL","SOW","HARVEST","FEED PEOPLE","KEEP THE LAND WORKING"],"branches":[{"senses":"01 · 02","en":"WORKING THE LAND: the whole practice and the single act of tillage are the same work.","cn":"耕作土地：整套实践与单次耕作是同一件事。"},{"senses":"03","en":"SCIENCE: farming becomes knowledge that can be studied and taught.","cn":"科学：耕作变成可以研究、教授的知识。"},{"senses":"04 · 05 · 07","en":"SCALE AND PURPOSE: subsistence, commercial and intensive farming differ in who eats the harvest and how hard the land is pushed.","cn":"规模与目的：自给、商业与集约农业的差别，在于收成给谁吃、土地被压得多紧。"},{"senses":"06 · 08","en":"SUSTAINABILITY AND THE CITY: farming must preserve the field, and it can now happen on a city plot.","cn":"可持续与城市：耕作必须养护田地，如今也能发生在城市地块上。"},{"senses":"09","en":"ECONOMIC SECTOR: the whole activity becomes a measurable part of the national economy.","cn":"经济部门：整套活动变成国民经济中可衡量的一部分。"}]},"affixes":{"intro":{"en":"agriculture is an uncountable noun, so it has no plural. Its English family is built from the adjective agricultural, the agent noun agriculturist, and the combining form agri- meaning 'field, farming'.","cn":"agriculture 是不可数名词，因此没有复数形式。它的英语词族由形容词 agricultural、施动名词 agriculturist，以及表示“田地、农业”的构词成分 agri- 组成。"},"latinIntro":{"en":"The Latin roots are real: ager 'field' gives agri- and agrarian; colere 'till, tend' gives culture, cultivate and colony. Agriculture joins the two.","cn":"拉丁词根真实存在：ager“田地”给出 agri- 与 agrarian；colere“耕种、照料”给出 culture、cultivate 与 colony。agriculture 把两者拼在一起。"},"items":[{"word":"agricultural","structure":"agriculture + -al (adjective)","meaning":"relating to farming or farmland","meaningCN":"农业的；农艺的（-al 构成形容词）","example":"Agricultural exports rose last year.","exampleCN":"农业出口去年增长。"},{"word":"agriculturally","structure":"agricultural + -ly (adverb)","meaning":"in relation to agriculture","meaningCN":"在农业方面；从农业角度（-ly 构成副词）","example":"The region is agriculturally rich but industrially poor.","exampleCN":"该地区农业丰富，工业薄弱。"},{"word":"agriculturist","structure":"agriculture + -ist (person)","meaning":"a person skilled in farming or agricultural science","meaningCN":"农学家；务农者（-ist 表示从事某活动的人）","example":"The agriculturist tested a new drought-resistant wheat.","exampleCN":"这位农学家试验了一种新的抗旱小麦。"},{"word":"agriculturalist","structure":"agricultural + -ist (person)","meaning":"a specialist in agriculture; a variant of agriculturist","meaningCN":"农业专家；agriculturist 的变体（-ist 表示人）","example":"Agriculturalists welcomed the soil survey.","exampleCN":"农业专家欢迎这次土壤调查。"},{"word":"agribusiness","structure":"agri- (field, farming) + business","meaning":"the farming industry and its supply, processing and distribution","meaningCN":"农业综合企业；农业产业（agri- 表示农业 + business）","example":"Agribusiness now controls much of the seed market.","exampleCN":"农业综合企业现在控制着很大一部分种子市场。"},{"word":"agritourism","structure":"agri- (farming) + tourism","meaning":"tourism based on visiting farms or rural areas","meaningCN":"农业旅游；乡村旅游（agri- + tourism）","example":"Agritourism brings extra income to small farms.","exampleCN":"农业旅游为小农场带来额外收入。"},{"word":"agrichemical","structure":"agri- (farming) + chemical","meaning":"a chemical used in farming, such as fertiliser or pesticide","meaningCN":"农用化学品（化肥、农药等）（agri- + chemical）","example":"The law limits several agrichemicals.","exampleCN":"法律限制了几种农用化学品。"},{"word":"agriscience","structure":"agri- (farming) + science","meaning":"the scientific study of agriculture","meaningCN":"农业科学（agri- + science）","example":"Agriscience students learn soil and plant biology.","exampleCN":"农业科学的学生学习土壤与植物生物学。"},{"word":"agri-food","structure":"agri- (farming) + food","meaning":"the food produced by farming and its processing industry","meaningCN":"农产食品；农业食品产业（agri- + food）","example":"The province promotes its agri-food sector.","exampleCN":"该省推广它的农产食品产业。"},{"word":"nonagricultural","structure":"non- (not) + agricultural","meaning":"not connected with farming","meaningCN":"非农业的（non- 表示否定）","example":"Most new jobs are in nonagricultural sectors.","exampleCN":"大多数新工作属于非农业部门。"},{"word":"pre-agricultural","structure":"pre- (before) + agricultural","meaning":"of the period before farming began","meaningCN":"农业出现之前的（pre- 表示在……之前）","example":"Pre-agricultural societies were mostly nomadic.","exampleCN":"农业出现前的社会大多游牧。"}],"latinEntries":[{"word":"agrarian","structure":"ager 'field' + -arian","meaning":"relating to land or farming","meaningCN":"土地的；农业的"},{"word":"agronomy","structure":"ager 'field' + -nomy (management)","meaning":"the science of crop production","meaningCN":"农学"},{"word":"acre","structure":"Old English æcer, from PIE *agro- 'field'","meaning":"a unit of land area","meaningCN":"英亩"},{"word":"agribusiness","structure":"agri- (field) + business","meaning":"the business side of farming","meaningCN":"农业综合企业"}]}},{"word":"aid","ipa_uk":"/eɪd/","ipa_us":"/eɪd/","definition_zh":"帮助；援助","definition_en":"to help a person or group in difficulty, or the help, supplies, or device that makes this possible","core_image":"一只手伸出去，扶住一个快要倒下的人","scene":"Volunteers delivered food and medicine to aid families cut off by the flood.","sceneCN":"这里 aid 是「帮助、援助」（第 1 个义项：用行动帮助陷入困境的人）；句意：志愿者送去食物和药品，帮助被洪水围困的家庭。图中可辨识物件：上涨的洪水、被围困的房屋、穿救生衣的志愿者、食品箱、药箱。","pos":[{"tag":"vt.","zh":"帮助；援助；有助于"},{"tag":"n.","zh":"帮助；援助；辅助器具；助手"}],"collocations":[{"phrase":"first aid","zh":"急救"},{"phrase":"foreign aid","zh":"外国援助"},{"phrase":"aid and abet","zh":"协助并教唆"},{"phrase":"come to someone's aid","zh":"前来帮助某人"},{"phrase":"in aid of","zh":"为资助……"}],"forms":[{"label":"三单（he/she/it，动词）","form":"aids"},{"label":"过去式（已经发生）","form":"aided"},{"label":"过去分词（完成／被动）","form":"aided"},{"label":"现在分词（进行体）","form":"aiding"},{"label":"复数（名词）","form":"aids"}],"derivatives":[{"word":"aide","pos":"n.","zh":"助手；副官"},{"word":"aided","pos":"adj.","zh":"得到帮助的；有辅助的"},{"word":"unaided","pos":"adj.","zh":"未受协助的；独立的"},{"word":"aidless","pos":"adj.","zh":"无帮助的；无人援助的"}],"senses":[{"no":"01","title":"Help someone in trouble","titleCN":"帮助陷入困境的人","definition":"to help a person or group that is in difficulty, danger, or urgent need","definitionCN":"帮助处于困难、危险或紧急需要中的个人或群体","example":"Volunteers delivered food and medicine to aid families cut off by the flood.","exampleCN":"志愿者送去食物和药品，帮助被洪水围困的家庭。","why":"The Latin verb adiuvare joins ad- 'to' and iuvare 'help, give strength'. The picture is not a distant donation but a hand reaching directly toward someone who cannot manage alone.","whyCN":"拉丁语动词 adiuvare 由 ad-“向”和 iuvare“帮助、给力”组成。画面不是我站在远处捐钱，而是把手直接伸向一个独自撑不住的人。"},{"no":"02","title":"Help viewed as a thing","titleCN":"帮助、援助（名词）","definition":"help or support given to someone, especially in the form of money, food, or services","definitionCN":"给予某人的帮助或支持，尤指金钱、食物或服务的形式","example":"The village received aid from the government after the landslide.","exampleCN":"山体滑坡后，这个村庄收到了政府的援助。","why":"When the action is viewed as a thing, help becomes a package that can be sent, counted, and received. The noun keeps the same hand, but now the hand is holding supplies.","whyCN":"当动作被看成一件事物时，帮助就变成可以发送、计量和接收的一包东西。名词保留了同一只手，只是手里拿的是物资。"},{"no":"03","title":"Medical first aid","titleCN":"急救","definition":"immediate medical help given to a sick or injured person before full treatment is available","definitionCN":"在正式治疗到位之前，对病人或伤者立即进行的医疗救助","example":"A nurse gave first aid to the cyclist until the ambulance arrived.","exampleCN":"护士给骑车的人做了急救，直到救护车赶到。","why":"First aid is the first hand laid on the injury. It is help at the earliest moment, not a complete cure, and the fixed phrase marks exactly that moment.","whyCN":"first aid 是落在伤口上的第一只手。它是最早时刻的帮助，不是完整治疗，这个固定短语标记的正是那个时间点。"},{"no":"04","title":"A device or tool that helps","titleCN":"辅助器具","definition":"a device or tool that makes a task easier, especially one that supports a sense or a skill","definitionCN":"使某项任务更容易的装置或工具，尤指支持某种感官或技能的器具","example":"She uses a hearing aid in both ears.","exampleCN":"她双耳都戴助听器。","why":"A hearing aid is literally 'an aid for hearing'. The hand is replaced by a device, but the function is the same: to steady a weak capacity.","whyCN":"助听器字面上就是“听力的帮助”。手换成了装置，但功能没变——扶住一个衰弱的能力。"},{"no":"05","title":"A person who assists","titleCN":"助手；副官","definition":"a person who helps another, especially an assistant to someone in authority","definitionCN":"帮助他人的人，尤指有权者身边的助手","example":"The general's aide carried the maps and relayed orders.","exampleCN":"将军的副官拿着地图，传达命令。","why":"The old noun aide came from the same French word as aid. A person could be called 'an aid' because he embodied the help; the spelling aide now keeps that role visible.","whyCN":"旧名词 aide 与 aid 来自同一个法语词。一个人可以被称为“一份帮助”，因为他本身就是那只伸出的手；现在的拼写 aide 让这个身份一眼可见。"},{"no":"06","title":"Help a process happen","titleCN":"有助于某个过程","definition":"to make a process or effect easier or more likely to happen","definitionCN":"使某个过程或效果更容易发生、更可能发生","example":"Walking after dinner can aid digestion.","exampleCN":"晚饭后散步有助于消化。","why":"Here the one being helped is not a person but a natural process. The hand is still there, only now it clears an obstacle so the body can do its own work.","whyCN":"这里被帮的不是人，而是一个自然过程。手仍在，只是它挪开障碍，让身体自己完成该做的事。"},{"no":"07","title":"Aid to a country","titleCN":"对外援助","definition":"money, food, or military supplies given by one country or organization to another","definitionCN":"一国或组织提供给另一国的资金、食物或军事物资","example":"The drought-stricken region depends on foreign aid for clean water.","exampleCN":"这个遭受旱灾的地区依靠外国援助获得清洁饮用水。","why":"Aid becomes a flow between nations. The helping hand is now an institution, and what it carries is not a single gesture but a continuing supply.","whyCN":"aid 变成国家之间的流动。那只援手现在是一个机构，手里拿的不是一次性的动作，而是持续不断的供给。"},{"no":"08","title":"Aid and abet in law","titleCN":"协助并教唆（法律）","definition":"in law, to help or encourage someone to commit a crime","definitionCN":"在法律上，帮助或鼓励某人实施犯罪","example":"He was charged with aiding and abetting the fraud.","exampleCN":"他被控协助并教唆这起诈骗。","why":"The same helping hand is pointed at a forbidden act. The law treats assistance as part of the crime because the hand makes the act possible.","whyCN":"同一只援手被指向了违法的行为。法律把协助算作犯罪的一部分，因为这只手让行为得以发生。"},{"no":"09","title":"In aid of a cause","titleCN":"为资助某项事业","definition":"in order to raise money for a charity or a public purpose","definitionCN":"为慈善或公共事业筹款","example":"They held a concert in aid of the children's hospital.","exampleCN":"他们举办了一场音乐会，为儿童医院筹款。","why":"The phrase turns aid into a purpose: everything done at the event is meant to reach the people who need help. The hand is extended through the event.","whyCN":"这个短语把 aid 变成一个目的：活动上所做的一切，都是为了抵达需要帮助的人。手通过这场活动伸了出去。"}],"etymology":{"intro":{"en":"Aid comes from Old French aide (noun) and aidier (verb), both from Latin adiuvare 'to help'. The deeper origin of iuvare is uncertain; sources only suggest a possible link with iuvenis 'young person'.","cn":"aid 来自古法语 aide，再往上为拉丁语 adiuvare“帮助”。iuvare 的更早来源不确定，资料只是提出它可能与 iuvenis“年轻人”有关。"},"items":[{"era":"C. 1400","en":"First recorded as the English verb aiden, 'to assist, help', borrowed through Old French aidier (Modern French aider).","cn":"最早记录为英语动词 aiden，意为“协助、帮助”，经古法语 aidier（现代法语 aider）借入。"},{"era":"EARLY 15C.","en":"The noun aide appears, first meaning 'war-time tax', and also 'help, support, assistance'. The tax sense shows that aid could already mean material support raised for a collective need.","cn":"名词 aide 出现，最初意为“战时税”，同时也表示“帮助、支持、援助”。征税义说明 aid 早已能指为集体需要而筹集的物质支持。"},{"era":"OLD FRENCH","en":"Old French aide, earlier aiudha, meant 'aid, help, assistance'. The verb aidier 'help, assist' is the direct source of English aid.","cn":"古法语 aide（更早写作 aiudha）意为“援助、帮助、协助”。动词 aidier“帮助、协助”是英语 aid 的直接来源。"},{"era":"LATE LATIN / LATIN","en":"Late Latin adiuta is a noun use of the feminine past participle of adiuvare 'to give help to'. Adiuvare joins ad- 'to' and iuvare 'help, give strength, support'. The verb adiutare was its frequentative.","cn":"晚期拉丁语 adiuta 是 adiuvare“给予帮助”的阴性过去分词的名词化用法。adiuvare 由 ad-“向”和 iuvare“帮助、给力、支撑”组成；动词 adiutare 是它的反复体。"},{"era":"LATIN / PIE","en":"The origin of iuvare is uncertain. Etymological dictionaries suggest a PIE source perhaps related to iuvenis 'young person' and the root *yeu- 'vital force', but this is only a possible connection, not an established derivation.","cn":"iuvare 的来源不确定。词源词典提出它可能来自与 iuvenis“年轻人”及词根 *yeu-“生命力”有关的原始印欧语来源，但这只是一种可能联系，并非已确立的派生关系。"},{"era":"16C.–20C.","en":"The sense 'thing by which assistance is given' is recorded from the 1590s and 'person who assists' from the 1560s. The modern sense 'material help given by one country to another' appears in 1940.","cn":"“用来提供帮助的东西”这一义项记录于 16 世纪 90 年代，“提供帮助的人”记录于 16 世纪 60 年代。现代义“一国给予另一国的物质援助”出现于 1940 年。"}]},"similar":{"note":{"en":"The first group separates words that look or sound close to aid; the second group separates words that also mean helping. Form is checked before meaning.","cn":"第一组区分与 aid 形近或音近的词；第二组区分同样表示“帮助”的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aide","ipa":"/eɪd/","tag":"same sound","definition":"a person who helps an important person, especially a military or political assistant. It sounds exactly like aid but names only the person.","definitionCN":"帮助重要人物的人，尤指军事或政治助手。它与 aid 完全同音，但只指“人”。"},{"word":"ail","ipa":"/eɪl/","tag":"near sound","definition":"to trouble or make someone ill. The vowel is close, but the word ends in -l and has nothing to do with help.","definitionCN":"使苦恼；使生病。元音相近，但结尾是 -l，与“帮助”无关。"},{"word":"aim","ipa":"/eɪm/","tag":"near sound","definition":"a purpose or target, or to point at a target. It ends in -m and belongs to a different idea.","definitionCN":"目的；目标；瞄准。它结尾是 -m，属于完全不同的概念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assist","ipa":"/əˈsɪst/","tag":"formal, hands-on help","definition":"to help someone do something, often as a secondary person. It is more formal than help and usually suggests direct participation.","definitionCN":"帮助某人做某事，常以辅助者身份。它比 help 正式，通常暗示亲自参与。"},{"word":"help","ipa":"/help/","tag":"general word","definition":"the broad everyday verb for making someone's task easier. Aid is more formal and often suggests urgent or institutional support.","definitionCN":"使别人的事更容易做的日常通用动词。aid 更正式，常暗示紧急或机构性的支持。"},{"word":"support","ipa":"/səˈpɔːt/","tag":"ongoing backing","definition":"to hold someone up over time, financially or emotionally. Aid is usually a specific act or supply, while support can be continuous.","definitionCN":"在金钱或情感上长期托住某人。aid 通常是具体行动或物资，而 support 可以是持续的。"},{"word":"relief","ipa":"/rɪˈliːf/","tag":"emergency supply","definition":"money, food, or help sent to people in a disaster. It stresses the emergency and the removal of suffering.","definitionCN":"送往灾区的钱、食物或帮助。它强调紧急状态和解除痛苦。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"aide and aid sound the same: aide is the person, aid is the help or the verb.","cn":"aide 与 aid 同音：aide 是那个人，aid 是帮助或动词。"},{"en":"first aid is the fixed phrase for the first help given at an accident.","cn":"first aid 是事故现场“第一时间施救”的固定说法。"},{"en":"Band-Aid is a brand name that became the everyday American word for a small adhesive bandage.","cn":"Band-Aid 是一个品牌名，后来在美国英语里成了小创可贴的日常叫法。"},{"en":"aid and abet is a legal doublet: both old verbs mean 'help', and together they name helping a crime.","cn":"aid and abet 是法律里的双词组合：两个旧动词都表示“帮助”，合起来指协助犯罪。"},{"en":"hearing aid, teaching aid and visual aid all use aid as 'a thing that helps a sense or a lesson'.","cn":"hearing aid、teaching aid、visual aid 都把 aid 用作“帮助某种感官或课程的东西”。"}],"abstract":[{"en":"Picture a hand reaching out and closing around another person's arm just before a fall. Every sense of aid repeats that steadying contact.","cn":"想象一只手伸出去，在别人跌倒前握住他的手臂。aid 的每个义项都在重复这个“扶住”的接触。"},{"en":"Aid is strength transferred from one side to another: sometimes a grip, sometimes food, sometimes money, sometimes a device.","cn":"aid 是把力量从一边传到另一边：有时是一握，有时是食物，有时是钱，有时是一个装置。"},{"en":"The same word covers a private gesture and an institutional flow because both answer one question: who reaches the person who cannot manage alone?","cn":"同一个词能覆盖私人动作和机构流动，因为两者都在回答同一个问题：谁来接近那个独自撑不住的人？"}]},"examples":[{"en":"She aided the elderly man across the icy street.","cn":"她扶着那位老人走过结冰的街道。"},{"en":"The charity sends aid to families after earthquakes.","cn":"地震之后，这家慈善机构向家庭运送援助物资。"},{"en":"A teacher's aide helped the children with their reading.","cn":"一位助教帮助孩子们阅读。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“爱得”——爱得深，就伸手扶他一把 → aid 帮助、援助","word":"aid"},"root":"源自拉丁语 adiuvare“帮助”，ad-“向”+ iuvare“帮助、给力”；核心是“把手伸向需要支撑的人”。","sensesIntro":{"en":"Nine senses of aid, all built on one gesture: a hand reaches toward someone or something that cannot manage alone. The hand may carry a grip, food, money, medicine, a device, or a legal warning.","cn":"aid 的九个义项都建立在同一个动作上：一只手伸向独自撑不住的人或事物。这只手可能带来搀扶、食物、金钱、药物、器具，也可能带来法律上的警告。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand reaches out and steadies someone who is falling.","cn":"核心意象：一只手伸出去，扶住一个正在倒下的人。"},"chain":["TROUBLE","REACH OUT","STEADY","SUPPORT","SHARE THE LOAD","HELP ARRIVES"],"branches":[{"senses":"01 · 06","en":"DIRECT HELP: a person is steadied, or a natural process is cleared so it can proceed.","cn":"直接帮助：人被扶住，或者一个自然过程被清出障碍，得以继续。"},{"senses":"02 · 07","en":"MATERIAL HELP: money, food, medicine or military supplies move from one side to another.","cn":"物质帮助：钱、食物、药物或军需从一边流向另一边。"},{"senses":"03","en":"MEDICAL EMERGENCY: the first hand is laid on an injury before full treatment.","cn":"医疗紧急：在完整治疗之前，第一只手先落在伤口上。"},{"senses":"04","en":"TOOL AS HELP: a device takes the place of the hand and supports a sense or skill.","cn":"器具即帮助：装置取代手的位置，支撑某种感官或技能。"},{"senses":"05 · 08 · 09","en":"PEOPLE AND PURPOSE: a helper embodies the aid, the law names help given to a crime, and a cause turns aid into a purpose.","cn":"人与目的：助手把帮助具体化，法律命名对犯罪的协助，而一项事业把 aid 变成一个目的。"}]},"affixes":{"intro":{"en":"aid is a short borrowed word with a large family of English compounds. The suffixes below are ordinary English endings; the compounds all keep the core meaning 'help'.","cn":"aid 是一个简短的借词，却有庞大的英语复合词家族。下面的后缀都是普通英语词尾；复合词都保留“帮助”这个核心义。"},"latinIntro":{"en":"The Latin iuvare family is real but not productive in English. Adiuvare produced aid, and the technical words adjuvant and coadjutor survive as learned borrowings; ordinary English does not build new words from iuvare, so no productive Latin list is given here.","cn":"拉丁语 iuvare 词族真实存在，但在英语里不能产。adiuvare 产生了 aid，技术词 adjuvant 和 coadjutor 作为学术借词留存；普通英语并不会用 iuvare 造新词，所以这里不列能产的拉丁同族词。"},"items":[{"word":"aide","structure":"aide (French-derived noun)","meaning":"a person who helps an important person","meaningCN":"助手；副官（来自法语的同音名词，不是加后缀构成）","example":"The senator's aide took notes during the meeting.","exampleCN":"参议员的助手在会中做记录。"},{"word":"aided","structure":"aid + -ed (past participle / adjective)","meaning":"helped, or equipped with an aid","meaningCN":"得到帮助的；有辅助的（-ed 构成过去分词或形容词）","example":"The aided schools received new computers.","exampleCN":"受资助的学校收到了新电脑。"},{"word":"aiding","structure":"aid + -ing (present participle / gerund)","meaning":"the act of helping","meaningCN":"帮助（-ing 构成进行体或动名词）","example":"Aiding a neighbour is a simple kindness.","exampleCN":"帮助邻居是一种朴素的善意。"},{"word":"unaided","structure":"un- (not) + aided","meaning":"done without help","meaningCN":"未受协助的；独立的（un- 表示否定）","example":"He climbed the wall unaided.","exampleCN":"他无人协助地爬上了墙。"},{"word":"aidless","structure":"aid + -less (without)","meaning":"having no help or support","meaningCN":"无帮助的；无人援助的（-less 表示“没有”）","example":"The aidless village waited for the rescue team.","exampleCN":"那个得不到援助的村庄等待救援队。"},{"word":"first aid","structure":"first + aid (compound)","meaning":"the first immediate help given to an injured person","meaningCN":"急救（first + aid 复合）","example":"Every hiker should know basic first aid.","exampleCN":"每个徒步者都该懂基本急救。"},{"word":"first-aid","structure":"first + aid (attributive compound)","meaning":"used before a noun for emergency medical supplies or training","meaningCN":"急救的（first + aid 复合，作定语）","example":"She opened the first-aid kit.","exampleCN":"她打开了急救箱。"},{"word":"hearing aid","structure":"hearing + aid (compound)","meaning":"a small device that helps a person hear","meaningCN":"助听器（hearing + aid 复合）","example":"His new hearing aid makes conversation easier.","exampleCN":"他的新助听器让交谈容易多了。"},{"word":"teaching aid","structure":"teaching + aid (compound)","meaning":"a tool or material used to help teaching","meaningCN":"教具（teaching + aid 复合）","example":"The teacher brought a map as a teaching aid.","exampleCN":"老师带了一张地图作为教具。"},{"word":"visual aid","structure":"visual + aid (compound)","meaning":"a picture, chart or object used to support a talk or lesson","meaningCN":"视觉辅助工具（visual + aid 复合）","example":"The slides were only a visual aid, not the whole lesson.","exampleCN":"幻灯片只是视觉辅助，不是整堂课。"},{"word":"aid worker","structure":"aid + worker (compound)","meaning":"a person who works for an organization giving humanitarian help","meaningCN":"援助工作者（aid + worker 复合）","example":"The aid worker stayed in the camp for six months.","exampleCN":"这名援助工作者在营地待了六个月。"}],"latinEntries":[]}},{"word":"allocate","ipa_uk":"/ˈæləkeɪt/","ipa_us":"/ˈæləkeɪt/","definition_zh":"分配；拨出","definition_en":"to give or set aside a share of money, time, space, or resources for a particular person or purpose","core_image":"把一堆资源分成若干份，在每一份旁边插上写着用途的牌子","scene":"The city allocated half of its annual budget to repairing the old bridge.","sceneCN":"这里 allocate 是「拨出、分配」（第 2 个义项：在预算中为特定用途留出资金）；句意：这座城市把年度预算的一半拨给了老桥维修。图中可辨识物件：预算册、计算器、老桥、写有 BRIDGE REPAIR 的拨款单。","pos":[{"tag":"vt.","zh":"分配；拨出；划拨；分派"}],"collocations":[{"phrase":"allocate resources","zh":"分配资源"},{"phrase":"allocate funds","zh":"拨出资金"},{"phrase":"allocate time","zh":"分配时间"},{"phrase":"allocate seats","zh":"分配座位"},{"phrase":"allocate tasks","zh":"分派任务"}],"forms":[{"label":"三单（he/she/it）","form":"allocates"},{"label":"过去式（已经发生）","form":"allocated"},{"label":"过去分词（完成／被动）","form":"allocated"},{"label":"现在分词（进行体）","form":"allocating"}],"derivatives":[{"word":"allocation","pos":"n.","zh":"分配；拨款；配置"},{"word":"allocator","pos":"n.","zh":"分配者；分配程序"},{"word":"reallocate","pos":"v.","zh":"重新分配；再划拨"},{"word":"allocable","pos":"adj.","zh":"可分配的；可划拨的"}],"senses":[{"no":"01","title":"Give out a share","titleCN":"分配一份","definition":"to give a share of something to a person, group, or purpose","definitionCN":"把某物的一份分给某个人、群体或用途","example":"The teacher allocated one worksheet to each group.","exampleCN":"老师给每个小组分配了一份练习纸。","why":"Allocate is ad- 'to' plus locare 'to place', from locus 'place'. The first move is to put each share in its own place, not simply to hand it out at random.","whyCN":"allocate 是 ad-“向”加 locare“放置”，后者来自 locus“地方”。第一个动作是把每一份放到它该在的位置，而不是随手发出去。"},{"no":"02","title":"Set aside money for a purpose","titleCN":"拨出资金","definition":"to set aside a sum of money for a particular use in a budget","definitionCN":"在预算中为特定用途留出一笔钱","example":"The council allocated two million dollars to road repairs.","exampleCN":"市议会拨出两百万美元用于道路维修。","why":"In Medieval Latin, allocate was the opening word of writs authorizing payment. The money was not merely divided; it was placed under a named purpose before it could be spent.","whyCN":"在中世纪拉丁语里，allocate 是批准付款的公文开头的词。钱不只是被分开，而是在花出去之前就被放到了一个写明的用途之下。"},{"no":"03","title":"Allocate time","titleCN":"分配时间","definition":"to decide how much time each person or task will receive","definitionCN":"决定每个人或每项任务能分到多少时间","example":"The coach allocated twenty minutes to each drill.","exampleCN":"教练给每个训练项目分配了二十分钟。","why":"Time is treated as a measurable block. To allocate it is to cut the day into slices and place one slice beside each task.","whyCN":"时间被当作可计量的块。分配时间就是把一天切成片，在每项任务旁边放上一片。"},{"no":"04","title":"Allocate space or seats","titleCN":"分配空间或座位","definition":"to give a particular room, seat, or area to someone or something","definitionCN":"把特定的房间、座位或区域分给某人或某物","example":"The airline allocated us seats near the emergency exit.","exampleCN":"航空公司把我们安排在了紧急出口附近的座位。","why":"Here locus is almost literal: a seat has a place, and allocating it means putting a person into that place.","whyCN":"这里的 locus 几乎是字面义：座位有一个位置，分配座位就是把一个人放进那个位置。"},{"no":"05","title":"Allocate tasks or roles","titleCN":"分派任务或角色","definition":"to assign particular duties or roles to particular people","definitionCN":"把具体职责或角色分派给具体的人","example":"The manager allocated the customer calls among the new staff.","exampleCN":"经理把客户来电分派给新员工处理。","why":"The thing being placed is now a duty. Each person receives the task that fits his or her place in the team.","whyCN":"被放置的东西现在是职责。每个人都收到一项与自己团队位置相配的任务。"},{"no":"06","title":"Allocate computing resources","titleCN":"分配计算资源","definition":"to give memory, processing power, or bandwidth to a program or user","definitionCN":"把内存、处理能力或带宽分配给某个程序或用户","example":"The server allocates memory to each application as it starts.","exampleCN":"服务器在应用程序启动时为其分配内存。","why":"A computer has finite resources, so the system must place each block where a program can reach it. The old 'place' idea becomes a technical assignment.","whyCN":"计算机资源有限，系统必须把每个块放到程序能取用的位置。古老的“放置”观念于是变成了技术上的分配。"},{"no":"07","title":"Allocate blame or responsibility","titleCN":"归咎、归责","definition":"to say which person or cause should carry the blame or responsibility for something","definitionCN":"指出应由哪个人或哪个原因承担某事的责任或过错","example":"The report allocated blame to several departments, not just one.","exampleCN":"报告把责任归给了好几个部门，而不只是一个。","why":"Responsibility is treated as a burden that must be placed somewhere. Allocating blame is putting that burden on a particular pair of shoulders.","whyCN":"责任被当作一份必须放下的担子。归咎就是把这份担子放到某一副肩膀上。"},{"no":"08","title":"Allocate costs","titleCN":"分摊成本","definition":"in accounting, to spread a cost among departments, products, or periods","definitionCN":"在会计中把一项成本分摊到各部门、产品或各期间","example":"The firm allocates overhead costs across all its branches.","exampleCN":"这家公司把管理费用分摊到所有分支机构。","why":"A shared cost has no single owner, so it is divided and placed in several accounts. The word's 'place' core becomes accounting logic.","whyCN":"共同成本没有唯一主人，所以要被切分并放到好几个账目里。这个词的“放置”核心变成了会计逻辑。"},{"no":"09","title":"Allocate energy in biology","titleCN":"分配能量（生物学）","definition":"of a living thing, to direct limited energy toward growth, reproduction, or survival","definitionCN":"指生物把有限的能量投向生长、繁殖或生存","example":"The plant allocates more energy to roots when water is scarce.","exampleCN":"缺水时，这种植物会把更多能量分配给根。","why":"An organism cannot do everything at once. Energy is a budget, and allocating it means choosing which function gets the next unit.","whyCN":"生物不可能同时做所有事。能量是一份预算，分配能量就是决定下一个能量单位给哪项功能。"}],"etymology":{"intro":{"en":"Allocate entered English in the 1630s from Medieval Latin allocate, the opening word of payment writs. Its Latin core is locare 'to place', from locus 'place', and the deeper origin of locus is uncertain.","cn":"allocate 于 17 世纪 30 年代从中世纪拉丁语 allocate 进入英语，那是付款公文开头的词。它的拉丁核心是 locare“放置”，来自 locus“地方”，而 locus 的更早来源并不确定。"},"items":[{"era":"1630s","en":"First recorded as an English verb meaning 'to set aside for a special purpose'. An adjective use is attested from the mid-15c. in legal language.","cn":"最早记录为英语动词，意为“为特定目的留出”。形容词用法在 15 世纪中期的法律语言中已有记录。"},{"era":"MEDIEVAL LATIN","en":"Allocate is the imperative plural of allocare 'allocate, allot', and was the common first word of writs authorizing payment. The form was borrowed whole, which is why English keeps the Latin-looking -ate.","cn":"allocate 是 allocare“分配、分拨”的祈使式复数，也是批准付款的公文常见的第一个词。整个形式被借入，所以英语保留了看起来像拉丁语的 -ate。"},{"era":"LATIN","en":"Allocare joins ad- 'to' and locare 'to place', from locus 'a place, spot, position'. The sense is to place something toward a particular spot, hence to assign it.","cn":"allocare 由 ad-“向”和 locare“放置”组成，后者来自 locus“地方、位置、地点”。意思就是把某物朝一个特定位置放过去，因此引申为“指派、分配”。"},{"era":"OLD LATIN / UNKNOWN","en":"Locus goes back to Old Latin stlocus, a word of uncertain origin. It is not safely traced to a known PIE root, so the chain stops at 'place' rather than at a reconstructed root.","cn":"locus 可上溯到古拉丁语 stlocus，但来源不确定。它无法可靠地追溯到某个已知的原始印欧语词根，所以这条链到“地方”为止，不再往重构词根上推。"},{"era":"OLD FRENCH / ALLOW","en":"Allocate is a twin of allow. Old French aloer/alloiier 'to place, allot, assign' came from Latin allocare, but it merged with allaudare 'to praise', and English allow took the 'permit' sense.","cn":"allocate 与 allow 是一对孪生词。古法语 aloer/alloiier“放置、分配、指派”来自拉丁语 allocare，但它与 allaudare“赞扬”混同，英语 allow 走的是“允许”这一支。"},{"era":"MODERN ENGLISH","en":"From the 17c. the verb extends from money to time, space, duties, blame, costs, computing memory and biological energy. The structure stays the same: a limited pool is measured, divided and placed.","cn":"从 17 世纪起，这个动词从金钱扩展到时间、空间、职责、责任、成本、计算机内存和生物能量。结构始终不变：有限的资源被计量、切分并放置。"}]},"similar":{"note":{"en":"The first group separates look-alike words, including a historical twin; the second group separates words that also involve giving out shares.","cn":"第一组区分形近词，其中包括一个历史孪生词；第二组区分同样涉及“分份给出去”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"allot","ipa":"/əˈlɒt/","tag":"spelling and meaning","definition":"to give a share of something, often by lot or by plan. It looks and sounds close to allocate but comes from a- + lot, not from locus.","definitionCN":"分配一份，常按抽签或计划分。它形音都接近 allocate，但来自 a- + lot，不是 locus。"},{"word":"allow","ipa":"/əˈlaʊ/","tag":"historical twin","definition":"to permit or let something happen. It is a historical twin of allocate, both from Latin allocare, but allow took the 'approve, permit' path.","definitionCN":"允许、让某事发生。它是 allocate 的历史孪生词，两者都来自拉丁语 allocare，但 allow 走了“赞同、允许”这一支。"},{"word":"locate","ipa":"/ləˈkeɪt/","tag":"same root","definition":"to find or place something in a position. It shares locus 'place' but does not mean dividing shares.","definitionCN":"找到或把某物放在某个位置。它共享 locus“地方”，但不表示分份。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assign","ipa":"/əˈsaɪn/","tag":"official giving","definition":"to give a task, role, or share to someone, often officially. It stresses the person receiving the duty.","definitionCN":"把任务、角色或份额正式交给某人，常强调接到职责的人。"},{"word":"distribute","ipa":"/dɪˈstrɪbjuːt/","tag":"spread out","definition":"to spread something among many people or places. It stresses the spreading, not the measured placing of each share.","definitionCN":"把东西分散给许多人或地方。它强调分散，而不是每一份被计量后放到某处。"},{"word":"apportion","ipa":"/əˈpɔːʃən/","tag":"fair division","definition":"to divide and give out in fair shares. It is formal and emphasizes fairness or proportion.","definitionCN":"按公平的份额划分并分发。它偏正式，强调公平或比例。"},{"word":"budget","ipa":"/ˈbʌdʒɪt/","tag":"planning","definition":"to plan how money will be spent. Allocate is the act of assigning the shares inside that plan.","definitionCN":"规划钱怎么花。allocate 是在这份计划内部把份额指派出去的动作。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"ad- means 'to' and locare means 'to place', so allocate is literally 'place each share toward its spot'.","cn":"ad- 表示“向”，locare 表示“放置”，所以 allocate 字面就是“把每一份放到它该在的位置”。"},{"en":"allocation is the noun you meet in budgets, office space and computer memory.","cn":"allocation 是你在预算、办公空间和计算机内存里都会遇到的名词。"},{"en":"allow is its historical twin; both come from Latin allocare, but allow took the 'permit' path.","cn":"allow 是它的历史孪生词；两者都来自拉丁语 allocare，但 allow 走了“允许”这一支。"},{"en":"locus means 'place'; local, locate and locality all show the same place root.","cn":"locus 意为“地方”；local、locate、locality 都显示同一个“地方”词根。"},{"en":"reallocate is what happens when a plan changes and the shares are placed again.","cn":"reallocate 就是计划改变后，把份额重新放一遍。"}],"abstract":[{"en":"Picture a long table with a pile of coins at one end and a row of labelled boxes at the other. Allocation is the careful walk from pile to box.","cn":"想象一张长桌，一端是一堆硬币，另一端是一排写着标签的盒子。分配就是从钱堆走向盒子的那段小心路程。"},{"en":"Every allocation assumes scarcity: if there were enough for everyone, no one would need to measure and place the shares.","cn":"每一次分配都默认资源稀缺：如果人人都够，就不需要计量并放置份额。"},{"en":"The verb is about placing before giving. That is why a budget, a timetable and a computer all use the same word: each has a limited pool and a set of slots.","cn":"这个动词的重点是“先放好，再给出”。预算、时间表和计算机都用同一个词，因为每者都有一个有限的池子和一排槽位。"}]},"examples":[{"en":"The school allocates a small budget to each club.","cn":"学校给每个社团拨出一小笔预算。"},{"en":"We need to allocate more time to the final review.","cn":"我们需要给最终审核分配更多时间。"},{"en":"The program allocates memory only when it is needed.","cn":"这个程序只在需要时才分配内存。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“爱了凯特”——爱了凯特，就把预算一份份分给她 → allocate 分配、拨出","word":"allocate"},"root":"源自拉丁语 allocare“分配、放置”，ad-“向”+ locare“放置”（来自 locus“地方”）；核心是“把有限资源分份并放到对应位置”。","sensesIntro":{"en":"Nine senses of allocate, all one operation: a limited pool is measured, cut into shares, and each share is placed beside a named person or purpose.","cn":"allocate 的九个义项都是同一个操作：有限的资源被计量、切成份，每一份被放到一个写明的人或用途旁边。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pile of resources is divided into measured shares, each tagged for a purpose.","cn":"核心意象：一堆资源被分成有量的一份份，每一份都挂上用途标签。"},"chain":["POOL","MEASURE","DIVIDE","PLACE","TAG PURPOSE","USE"],"branches":[{"senses":"01 · 02","en":"MONEY: a budget is split, and each sum is placed under a named use before it is spent.","cn":"金钱：预算被切开，每一笔在花出去之前就被放到一个写明的用途下。"},{"senses":"03 · 04","en":"TIME AND SPACE: the day is cut into slices, and seats or rooms are assigned to people.","cn":"时间与空间：一天被切成片，座位或房间被指派给人。"},{"senses":"05 · 07","en":"DUTIES AND BLAME: tasks and responsibility are treated as loads placed on particular shoulders.","cn":"职责与责任：任务和责任被当作担子，放到特定的肩膀上。"},{"senses":"06 · 08","en":"TECHNICAL POOLS: computing memory and shared costs are finite blocks that must be placed in the right account.","cn":"技术池：计算机内存和共同成本都是有限的块，必须放进正确的账目。"},{"senses":"09","en":"BIOLOGICAL ENERGY: a living thing spends its limited energy on growth, reproduction, or survival.","cn":"生物能量：生物把有限的能量花在生长、繁殖或生存上。"}]},"affixes":{"intro":{"en":"allocate is a learned Latin verb with a productive modern family. The suffixes below form nouns, adjectives and technical verbs; the prefixes re- and de- are living English prefixes.","cn":"allocate 是一个学术性的拉丁动词，在现代英语里有能产的词族。下面的后缀构成名词、形容词和技术动词；前缀 re- 和 de- 是活的英语前缀。"},"latinIntro":{"en":"The Latin locus 'place' family is real and productive: local, locate, locality and locus itself all carry the 'place' idea. The deeper origin of locus is uncertain, so no PIE root is claimed.","cn":"拉丁语 locus“地方”的词族真实且能产：local、locate、locality 以及 locus 本身都带着“地方”的意思。locus 的更早来源不确定，所以不宣称某个原始印欧语词根。"},"items":[{"word":"allocated","structure":"allocate + -ed (past participle / adjective)","meaning":"given out or set aside for a purpose","meaningCN":"已分配的；已拨出的（-ed 构成过去分词或形容词）","example":"The allocated funds must be spent this year.","exampleCN":"已拨出的资金必须在今年用完。"},{"word":"allocating","structure":"allocate + -ing (present participle / gerund)","meaning":"the act of giving out shares","meaningCN":"分配（-ing 构成进行体或动名词）","example":"Allocating seats takes longer than people expect.","exampleCN":"分配座位比人们想的更费时。"},{"word":"allocation","structure":"allocate + -ion (noun of action)","meaning":"the act or result of allocating; a share given out","meaningCN":"分配；拨款；配置（-ion 构成行为名词）","example":"The allocation of resources is decided in June.","exampleCN":"资源分配在六月决定。"},{"word":"allocator","structure":"allocate + -or (person or thing that does)","meaning":"a person or program that allocates","meaningCN":"分配者；分配程序（-or 表示执行动作的人或物）","example":"The memory allocator gave each app a block.","exampleCN":"内存分配程序给每个应用一个块。"},{"word":"allocable","structure":"allocate + -able (can be ...ed)","meaning":"able to be allocated","meaningCN":"可分配的；可划拨的（-able 表示“能够被……”）","example":"Only allocable costs appear in this account.","exampleCN":"只有可分摊的成本才出现在这个账目里。"},{"word":"allocative","structure":"allocate + -ive (adjective)","meaning":"relating to allocation, especially in economics","meaningCN":"分配的；配置的（-ive 构成形容词）","example":"The study examines allocative efficiency.","exampleCN":"这项研究考察配置效率。"},{"word":"unallocated","structure":"un- (not) + allocated","meaning":"not yet given out or assigned","meaningCN":"未分配的；尚未划拨的（un- 表示否定）","example":"The unallocated funds were returned to the treasury.","exampleCN":"未分配的资金被退回财政。"},{"word":"reallocate","structure":"re- (again) + allocate","meaning":"to allocate again in a different way","meaningCN":"重新分配；再划拨（re- 表示“再一次”）","example":"We had to reallocate staff after two people left.","exampleCN":"两个人离开后，我们不得不重新分配员工。"},{"word":"reallocation","structure":"re- + allocation","meaning":"a second or different allocation","meaningCN":"重新分配（re- + -ion 构成名词）","example":"The reallocation of seats caused some complaints.","exampleCN":"座位的重新分配引发了一些抱怨。"},{"word":"deallocate","structure":"de- (reverse) + allocate","meaning":"to release previously allocated memory or resources","meaningCN":"释放已分配的内存或资源（de- 表示“反向、解除”）","example":"The system deallocates the buffer after the task ends.","exampleCN":"任务结束后，系统释放缓冲区。"},{"word":"deallocation","structure":"de- + allocation","meaning":"the act of releasing allocated resources","meaningCN":"释放已分配资源（de- + -ion 构成名词）","example":"A memory leak is a missing deallocation.","exampleCN":"内存泄漏就是缺少一次释放。"}],"latinEntries":[{"word":"local","structure":"locus 'place' + -al","meaning":"relating to a particular place","meaningCN":"地方的；当地的"},{"word":"locate","structure":"locus + -ate","meaning":"to find or place something","meaningCN":"定位；安置"},{"word":"locality","structure":"local + -ity","meaning":"a particular area or neighborhood","meaningCN":"地区；地点"},{"word":"location","structure":"locus + -tion","meaning":"a place or position","meaningCN":"位置；地点"}]}},{"word":"alter","ipa_uk":"/ˈɔːltə(r)/","ipa_us":"/ˈɔːltər/","definition_zh":"改变；修改","definition_en":"to change something, usually in a limited or partial way, without replacing it completely","core_image":"同一件衣服被改短了袖口：它还是那件衣服，却已不是原样","scene":"The tailor altered the sleeves of the jacket so they fit her arms.","sceneCN":"这里 alter 是「改动衣服」（第 2 个义项：改变衣物的尺寸或合身程度）；句意：裁缝把夹克的袖子改了，让它合她的手臂。图中可辨识物件：裁缝、缝纫机、卷尺、夹克袖子、别针。","pos":[{"tag":"vt.","zh":"改变；改动；修改；改建"},{"tag":"vi.","zh":"变化；变得不同"}],"collocations":[{"phrase":"alter course","zh":"改变航向／方向"},{"phrase":"alter behavior","zh":"改变行为"},{"phrase":"alter the fact","zh":"改变事实"},{"phrase":"alter a garment","zh":"改衣服"},{"phrase":"alter the meaning","zh":"改变含义"}],"forms":[{"label":"三单（he/she/it）","form":"alters"},{"label":"过去式（已经发生）","form":"altered"},{"label":"过去分词（完成／被动）","form":"altered"},{"label":"现在分词（进行体）","form":"altering"}],"derivatives":[{"word":"alteration","pos":"n.","zh":"改动；修改；改建"},{"word":"alterable","pos":"adj.","zh":"可改变的"},{"word":"unaltered","pos":"adj.","zh":"未改变的；原样的"},{"word":"alterer","pos":"n.","zh":"改动者；修改者"}],"senses":[{"no":"01","title":"Change something partly","titleCN":"部分改变某物","definition":"to change something, usually in a limited way, without replacing it completely","definitionCN":"改变某事物，通常是有限度的改动，而不是彻底替换","example":"A small adjustment altered the tone of the whole painting.","exampleCN":"一处小小的调整改变了整幅画的色调。","why":"Alter comes from Latin alter, 'the other of two'. The object is still the same object, but it has been turned toward its 'other' version.","whyCN":"alter 来自拉丁语 alter“两者中的另一个”。物件还是同一个物件，只是被转向了它的“另一个版本”。"},{"no":"02","title":"Alter a garment","titleCN":"改衣服","definition":"to change the size, shape, or fit of a piece of clothing","definitionCN":"改变衣物的尺寸、形状或合身程度","example":"The tailor altered the waist of the dress by two centimetres.","exampleCN":"裁缝把裙子的腰围改小了两厘米。","why":"Clothes give the clearest picture: the cloth remains, but the cut is moved. That is why alteration often means a small, skilled change rather than a new garment.","whyCN":"衣服给出最清楚的画面：布还是那块布，只是剪裁被挪动了。所以 alteration 常指精细的小改动，而不是做一件新衣服。"},{"no":"03","title":"Alter course or plan","titleCN":"改变路线或计划","definition":"to change the direction of a journey, project, or plan","definitionCN":"改变行程、项目或计划的方向","example":"The ship altered course to avoid the storm.","exampleCN":"那艘船改变了航向以避开风暴。","why":"A course is a line drawn ahead. To alter it is to bend that line toward another direction while keeping the same journey.","whyCN":"航线是向前画出的一条线。改变航线，就是让这条线弯向另一个方向，但旅程仍是同一段。"},{"no":"04","title":"Alter behavior or attitude","titleCN":"改变行为或态度","definition":"to make a person's or group's way of acting or thinking different","definitionCN":"使人或群体的行事方式或想法变得不同","example":"The training program altered the way the staff handled complaints.","exampleCN":"这个培训项目改变了员工处理投诉的方式。","why":"Behaviour is a pattern, and altering it means shifting the pattern rather than erasing the person. The old self continues, with a different setting.","whyCN":"行为是一种模式，改变行为是把模式挪一挪，而不是把人抹掉。旧的自我还在，只是设定变了。"},{"no":"05","title":"Alter text or meaning","titleCN":"改动文字或含义","definition":"to change the wording of a text, or to change what something means","definitionCN":"改动文本的措辞，或改变某事物的含义","example":"One altered word in the contract changed its legal meaning.","exampleCN":"合同里改动的一个词改变了它的法律含义。","why":"A text is a fixed arrangement. Altering one part changes the whole reading, because meaning lives in the relation between words.","whyCN":"文本是一个固定的排列。改动其中一处就会改变整体读法，因为意义活在词与词的关系里。"},{"no":"06","title":"Alter the fact or outcome","titleCN":"改变事实或结果","definition":"to make a fact or result different, often used in the negative to say something cannot be changed","definitionCN":"使事实或结果变得不同，常用于否定式表示某事无法改变","example":"Nothing can alter the fact that the deadline was missed.","exampleCN":"截止日期已被错过，这个事实无法改变。","why":"A fact is treated as solid ground. To alter it is to try to move that ground; the negative form reminds us that some things are already fixed.","whyCN":"事实被当作坚实的地面。改变事实就是试图挪动这块地；否定式提醒我们，有些东西已经定住了。"},{"no":"07","title":"Alter a building or space","titleCN":"改建建筑或空间","definition":"to change the structure or appearance of a building or room","definitionCN":"改变建筑或房间的结构或外观","example":"They altered the old warehouse into a gallery.","exampleCN":"他们把旧仓库改建成了画廊。","why":"A building keeps its footprint while its interior is rearranged. Alteration is change inside an existing frame.","whyCN":"建筑保留原来的轮廓，内部却被重新安排。alteration 就是在既有框架内做改变。"},{"no":"08","title":"Become different","titleCN":"自身发生变化","definition":"to become different over time, without an outside agent","definitionCN":"随时间自身变得不同，不需要外部施动者","example":"Her voice had altered noticeably since the operation.","exampleCN":"手术之后，她的声音明显变了。","why":"The intransitive sense, recorded in the 1580s, turns the verb around: the thing itself moves toward its other state. No hand is needed.","whyCN":"不及物义记录于 16 世纪 80 年代，把动词转了个方向：事物自己走向它的另一个状态，不需要一只手来推动。"},{"no":"09","title":"Alter genes or chemistry","titleCN":"改变基因或化学性质","definition":"to change the genetic or chemical makeup of a living thing or substance","definitionCN":"改变生物或物质的基因组成或化学性质","example":"The edit altered a single gene in the plant's DNA.","exampleCN":"这次编辑改变了这种植物 DNA 中的一个基因。","why":"At the smallest scale, alteration is still a local change inside a whole. One unit is swapped, and the system's behaviour may change with it.","whyCN":"在最小的尺度上，alteration 仍是整体内部的一处局部改动。一个单位被换掉，整个系统的行为就可能随之改变。"}],"etymology":{"intro":{"en":"Alter comes from Old French alterer and Medieval Latin alterare, from Latin alter 'the other of two'. The Latin word is reconstructed from PIE *al- 'beyond' plus a comparative suffix, so the deeper root is a reconstruction, not an attested form.","cn":"alter 来自古法语 alterer 和中世纪拉丁语 alterare，再往上为拉丁语 alter“两者中的另一个”。这个拉丁词被重构为原始印欧语 *al-“越过”加比较级后缀，所以更深的词根是构拟形式，并非有文献直接记录的词。"},"items":[{"era":"LATE 14C.","en":"First recorded as an English verb meaning 'to change (something), make different in some way'.","cn":"最早记录为英语动词，意为“改变某物、使在某方面不同”。"},{"era":"OLD FRENCH","en":"Old French alterer (Modern French altérer) meant 'to change, alter'. English took the verb from French rather than directly from Latin.","cn":"古法语 alterer（现代法语 altérer）意为“改变、改动”。英语是从法语借入这个动词的，而不是直接从拉丁语借入。"},{"era":"MEDIEVAL LATIN","en":"Medieval Latin alterare 'to change' is a verb built on Latin alter 'the other (of the two)'. The medieval form adds the ordinary verb ending -are.","cn":"中世纪拉丁语 alterare“改变”是在拉丁语 alter“两者中的另一个”之上构成的动词，加上了普通的动词词尾 -are。"},{"era":"LATIN / PIE","en":"Latin alter is reconstructed as PIE *al- 'beyond' plus the comparative suffix *-ter (as in other). These forms are reconstructed, not directly attested; the reconstruction is standard but not certain in every detail.","cn":"拉丁语 alter 被重构为原始印欧语 *al-“越过、在那边”加比较级后缀 *-ter（如同 other）。这些形式是构拟，没有直接文献记录；这套重构是通行的，但并非每个细节都确定。"},{"era":"1580s","en":"The intransitive sense 'to become otherwise, change by itself' is recorded by the 1580s, extending the verb from an outside act to an internal process.","cn":"不及物义“变成另一种样子、自身发生变化”记录于 16 世纪 80 年代，把这个动词从外部动作扩展到内部过程。"},{"era":"MODERN ENGLISH","en":"Modern English uses alter for small changes to clothes, buildings, plans, texts, behaviour and genes. The related noun alteration and the phrase alter ego keep the 'other self' image alive.","cn":"现代英语用 alter 指对衣服、建筑、计划、文本、行为和基因的小幅改动。相关名词 alteration 和短语 alter ego 让“另一个自我”的画面延续下来。"}]},"similar":{"note":{"en":"The first group separates look-alike words, including one built on the same root; the second group separates verbs that also mean changing. Form is checked before meaning.","cn":"第一组区分形近词，其中包括一个同根词；第二组区分同样表示“改变”的动词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"altar","ipa":"/ˈɔːltə/","tag":"same sound","definition":"a raised table used in worship. It sounds like alter in many varieties but is a completely different word, often confused in writing.","definitionCN":"用于礼拜的祭坛。它在许多口音里与 alter 同音，但完全是另一个词，写作时常被混淆。"},{"word":"altercation","ipa":"/ˌɔːltəˈkeɪʃən/","tag":"same root","definition":"an angry argument or dispute. It comes from Latin altercari 'to dispute with another', a different branch of the alter family.","definitionCN":"愤怒的争吵、争执。它来自拉丁语 altercari“与另一个争论”，是 alter 词族的另一分支。"},{"word":"alternative","ipa":"/ɔːlˈtɜːnətɪv/","tag":"same root","definition":"a different choice or option. It is built on alter 'the other', but it names the other choice, not the act of changing something.","definitionCN":"另一个选择或备选方案。它建立在 alter“另一个”之上，但命名的是“另一个选择”，不是“改变某物”的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"change","ipa":"/tʃeɪndʒ/","tag":"general word","definition":"the broad verb for becoming or making different. Alter usually suggests a partial or careful change rather than a total transformation.","definitionCN":"表示“变成”或“使不同”的通用动词。alter 通常暗示部分、细致的改动，而不是彻底转变。"},{"word":"modify","ipa":"/ˈmɒdɪfaɪ/","tag":"adjust for a purpose","definition":"to change something slightly, especially to improve it or make it suit a purpose.","definitionCN":"轻微改变某物，尤指为了改进或使其适合某个目的。"},{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"fit or setting","definition":"to change something so that it fits, works, or feels right. It often implies a small practical correction.","definitionCN":"调整某物使其合适、正常或舒服。它常暗示一次小的实际校正。"},{"word":"amend","ipa":"/əˈmend/","tag":"formal correction","definition":"to change a text, law, or agreement formally, usually to make it better or more accurate.","definitionCN":"正式修改文本、法律或协议，通常是为了让它更好或更准确。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"alter ego is Latin for 'other I' — the second self that the same person can also be.","cn":"alter ego 是拉丁语“另一个我”——同一个人也可以是的第二个自我。"},{"en":"alteration is the everyday noun for a change, especially one made by a tailor or a builder.","cn":"alteration 是表示“改动”的日常名词，尤指裁缝或建筑工人做的修改。"},{"en":"altar and alter sound alike, but altar is a sacred table; keep the -a- in altar.","cn":"altar 与 alter 同音，但 altar 是祭坛；写 altar 时要保留那个 -a-。"},{"en":"alternate and alternative both grow from alter 'other'; they are the 'other' branch of the family.","cn":"alternate 和 alternative 都从 alter“另一个”长出来；它们是这个词族的“另一个”分支。"},{"en":"unaltered means untouched; the un- makes the change visible by denying it.","cn":"unaltered 表示“未被动过”；un- 通过否定让“改变”这件事反而变得可见。"}],"abstract":[{"en":"Picture the same jacket on a hanger: the cloth is identical, but the sleeves are shorter. Alter is that small movement inside an unchanged identity.","cn":"想象衣架上还是那件夹克：布完全相同，但袖子短了。alter 就是“身份未变、内部挪动”的那一小步。"},{"en":"Alter is not replace. Replacement makes a new thing; alteration makes the old thing take another form.","cn":"alter 不是 replace。替换造出一个新东西；改动让旧东西换一种形态。"},{"en":"The Latin alter means 'the other of two', so every altered thing is imagined as swinging toward a second version of itself rather than becoming a stranger.","cn":"拉丁语 alter 意为“两者中的另一个”，所以每个被 alter 的东西都被想象成摆向自己的第二个版本，而不是变成陌生人。"}]},"examples":[{"en":"The new evidence altered our understanding of the case.","cn":"新证据改变了我们对这个案件的理解。"},{"en":"She altered the dress to fit her daughter.","cn":"她把裙子改成了适合女儿的尺寸。"},{"en":"The village has altered little in fifty years.","cn":"这个村庄五十年来几乎没有变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“奥特”——奥特曼把袖子改短一截 → alter 改动、改变","word":"alter"},"root":"源自拉丁语 alter“两者中的另一个”，经古法语 alterer 进入英语；核心是“同一个东西转向自己的另一个版本”。","sensesIntro":{"en":"Nine senses of alter, all one idea: the same thing is moved toward another version of itself. The change may be in cloth, direction, behaviour, wording, facts, buildings, the thing itself, or a gene.","cn":"alter 的九个义项都是同一个观念：同一个事物被转向自己的另一个版本。改动可能发生在布料、方向、行为、措辞、事实、建筑、事物本身或基因上。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same object, now turned toward 'the other' — one detail differs, identity remains.","cn":"核心意象：同一个物件被转向“另一个”——某个细节不同了，身份仍在。"},"chain":["SAME THING","OTHER FORM","SMALL SHIFT","NEW STATE","STILL ITSELF","CHANGED"],"branches":[{"senses":"01 · 02 · 07","en":"PHYSICAL FORM: cloth, buildings and objects keep their identity while their shape is adjusted.","cn":"物理形态：布料、建筑和物件保留身份，只调整形状。"},{"senses":"03 · 04","en":"PATH AND HABIT: a course or a pattern of behaviour is bent toward another direction.","cn":"路径与习惯：航线或行为模式被弯向另一个方向。"},{"senses":"05 · 06","en":"TEXT AND FACT: a word or a fact is shifted, and the meaning or the record changes with it.","cn":"文本与事实：一个词或一条事实被挪动，含义或记录随之改变。"},{"senses":"08","en":"INTRANSITIVE: the thing itself moves toward its other state, with no outside hand.","cn":"不及物：事物自己走向另一个状态，没有外部的手。"},{"senses":"09","en":"NATURE AT SMALL SCALE: a gene or a chemical unit is swapped inside a whole system.","cn":"小尺度的本性：一个基因或化学单位在整体系统内部被换掉。"}]},"affixes":{"intro":{"en":"alter is a Latin verb with a productive English family. The suffixes below build nouns and adjectives; un- and in- negate the idea of change; alter ego is a frozen Latin phrase.","cn":"alter 是一个拉丁动词，在英语里有能产的词族。下面的后缀构成名词和形容词；un- 和 in- 否定“改变”；alter ego 是一个凝固的拉丁短语。"},"latinIntro":{"en":"The Latin alter 'other' family is real and productive: alternate, alternative, alternation and altruism all descend from it. The deeper PIE *al- is a reconstruction, not an attested root.","cn":"拉丁语 alter“另一个”的词族真实且能产：alternate、alternative、alternation、altruism 都出自它。更深的原始印欧语 *al- 是构拟形式，不是有文献直接记录的词根。"},"items":[{"word":"altered","structure":"alter + -ed (past participle / adjective)","meaning":"changed, or made different","meaningCN":"已改变的；被改动的（-ed 构成过去分词或形容词）","example":"The altered document was sent back for review.","exampleCN":"被改动的文件被退回审核。"},{"word":"altering","structure":"alter + -ing (present participle / gerund)","meaning":"the act of changing something","meaningCN":"改变（-ing 构成进行体或动名词）","example":"Altering the plan at this stage is risky.","exampleCN":"在这个阶段改动计划有风险。"},{"word":"alteration","structure":"alter + -ation (noun of action)","meaning":"a change made to something","meaningCN":"改动；修改；改建（-ation 构成行为名词）","example":"The alterations to the house took three months.","exampleCN":"这栋房子的改建花了三个月。"},{"word":"alterable","structure":"alter + -able (can be ...ed)","meaning":"able to be changed","meaningCN":"可改变的（-able 表示“能够被……”）","example":"The schedule is alterable if necessary.","exampleCN":"如有必要，日程可以调整。"},{"word":"unalterable","structure":"un- (not) + alterable","meaning":"impossible to change","meaningCN":"不可改变的（un- 表示否定）","example":"The law was described as unalterable.","exampleCN":"这条法律被说成不可更改。"},{"word":"unaltered","structure":"un- (not) + altered","meaning":"not changed; still in the original state","meaningCN":"未改变的；原样的（un- 表示否定）","example":"The room remained unaltered for decades.","exampleCN":"这个房间几十年没有变过。"},{"word":"alterability","structure":"alterable + -ity (quality)","meaning":"the quality of being changeable","meaningCN":"可改变性（-ity 构成性质名词）","example":"The alterability of the design was its main advantage.","exampleCN":"这个设计可修改，是它的主要优点。"},{"word":"alterer","structure":"alter + -er (person who does)","meaning":"a person who alters something","meaningCN":"改动者；修改者（-er 表示做该动作的人）","example":"The alterer left clear marks on the manuscript.","exampleCN":"修改者在手稿上留下了清楚的痕迹。"},{"word":"alterant","structure":"alter + -ant (doing or causing)","meaning":"a substance or agent that alters something","meaningCN":"改变物；致变剂（-ant 表示“引起……的”）","example":"The alterant was added to change the colour.","exampleCN":"加入这种致变剂是为了改变颜色。"},{"word":"alterative","structure":"alter + -ative (adjective / noun)","meaning":"having the power to change; a remedy once believed to change body processes","meaningCN":"有改变作用的；变质药（-ative 构成形容词或名词）","example":"Alterative treatment was an old medical idea.","exampleCN":"变质疗法是一个旧医学观念。"},{"word":"alter ego","structure":"Latin alter 'other' + ego 'I' (frozen phrase)","meaning":"a second self or a very close deputy","meaningCN":"另一个自我；知己；全权代表（凝固的拉丁短语）","example":"The manager sent her alter ego to the meeting.","exampleCN":"经理派她的全权代表去开会。"}],"latinEntries":[{"word":"alternate","structure":"alter 'other' + -ate","meaning":"to take turns; every other one","meaningCN":"交替；间隔的"},{"word":"alternation","structure":"alternare + -tion","meaning":"the act of alternating","meaningCN":"交替；轮换"},{"word":"altruism","structure":"alter 'other' + -ism","meaning":"concern for others","meaningCN":"利他主义"},{"word":"alteration","structure":"alter + -ation","meaning":"a change or modification","meaningCN":"改动；修改"}]}},{"word":"alternative","ipa_uk":"/ɔːlˈtɜːnətɪv/","ipa_us":"/ɔːlˈtɜːrnətɪv/","definition_zh":"替代方案；替代的","definition_en":"something that can be chosen instead of another thing, or an adjective describing a choice that replaces the usual one","core_image":"岔路口并排两块路牌：一块通向常规，另一块也真能到达","scene":"With the motorway closed, the drivers took an alternative route along the coast.","sceneCN":"这里 alternative 是「备选的、替代的」（第 5 个义项：替代通常路线的）；句意：高速公路封闭后，司机们改走了沿海的一条替代路线。图中可辨识物件：封闭的高速公路、绕行标志、海岸公路、汽车。","pos":[{"tag":"n.","zh":"替代方案；备选方案；选择"},{"tag":"adj.","zh":"替代的；备选的；另类的"}],"collocations":[{"phrase":"an alternative to","zh":"……的替代方案"},{"phrase":"alternative energy","zh":"替代能源"},{"phrase":"alternative route","zh":"替代路线"},{"phrase":"have no alternative","zh":"别无选择"},{"phrase":"viable alternative","zh":"可行的替代方案"}],"forms":[{"label":"复数（名词）","form":"alternatives"},{"label":"比较级（形容词）","form":"more alternative"},{"label":"最高级（形容词）","form":"most alternative"}],"derivatives":[{"word":"alternatively","pos":"adv.","zh":"或者；作为替代"},{"word":"alternativeness","pos":"n.","zh":"替代性；备选性"},{"word":"alternativism","pos":"n.","zh":"另类主义"},{"word":"alternativist","pos":"n.","zh":"另类主义者"}],"senses":[{"no":"01","title":"A choice between two","titleCN":"二者之间的选择","definition":"a situation in which one of two possible choices must be taken","definitionCN":"必须在两个可能选择中取其一的情形","example":"The hikers faced the alternative of waiting for dawn or turning back.","exampleCN":"徒步者面临两个选择：等天亮，或者原路返回。","why":"The word begins as rhetoric: an alternative proposition offers two statements, and accepting one means rejecting the other. The structure is a fork with two prongs.","whyCN":"这个词最初是修辞学术语：选言命题给出两个陈述，接受一个就意味着否定另一个。它的结构就是一把两齿的叉。"},{"no":"02","title":"A backup option","titleCN":"备选方案","definition":"one of two or more things that can be chosen instead of the first","definitionCN":"可以作为首选之外的另一个选择的事物","example":"We kept a second venue as an alternative in case of rain.","exampleCN":"我们另留了一个场地作为备选，以防下雨。","why":"Once the fork is in daily life, the second prong becomes a backup. It is not the main road, but it is still a real road.","whyCN":"当这把叉进入日常生活，第二个齿就成了备选。它不是主路，但仍然是一条真路。"},{"no":"03","title":"A substitute or replacement","titleCN":"替代品","definition":"something that takes the place of another thing and performs the same function","definitionCN":"取代另一事物并承担相同功能的东西","example":"The clinic offers herbal alternatives to some painkillers.","exampleCN":"这家诊所提供某些止痛药的草本替代品。","why":"Here the second option is chosen not alongside the first but in its place. The 'other' becomes a stand-in, and the original may be left unused.","whyCN":"这里的第二个选项不是与第一个并列，而是占据它的位置。“另一个”变成了替身，原来的东西可能被搁在一边。"},{"no":"04","title":"Other than the usual","titleCN":"替代的、另外的","definition":"used as an adjective for something that is different from the usual or established one","definitionCN":"作形容词，指不同于通常或既定做法的","example":"The school offers an alternative schedule for working parents.","exampleCN":"学校为上班族父母提供了另一套时间安排。","why":"As an adjective, alternative simply marks the second path. It does not yet judge it better or worse; it only says 'not the usual one'.","whyCN":"作形容词时，alternative 只是标记第二条路。它暂时不判断好坏，只说“不是通常那条”。"},{"no":"05","title":"Alternative route or energy","titleCN":"备选路线、替代能源","definition":"describing a route, source, or method that can replace the usual one","definitionCN":"描述可以取代通常路线、来源或方法的","example":"Cyclists are encouraged to use alternative routes during the roadworks.","exampleCN":"施工期间，骑行者被鼓励使用替代路线。","why":"Practical life makes the adjective concrete: a road is closed, an energy source is dirty, so another path or source is placed beside it.","whyCN":"现实生活让这个形容词具体起来：一条路封了，一种能源有污染，于是在旁边放上另一条路、另一个来源。"},{"no":"06","title":"Alternative medicine","titleCN":"另类疗法","definition":"medical treatment that is not part of conventional scientific medicine","definitionCN":"不属于常规科学医学的医疗方法","example":"She tried alternative medicine after the standard treatment failed.","exampleCN":"常规治疗无效后，她尝试了另类疗法。","why":"The 'other' path is now measured against an established institution. Alternative medicine is defined by standing outside the mainstream, not by being new.","whyCN":"这里的“另一条路”是相对一个既定体系来衡量的。另类疗法是由“站在主流之外”来定义的，而不是因为它新。"},{"no":"07","title":"Alternative lifestyle or music","titleCN":"另类生活方式或音乐","definition":"describing a way of life or style of music that deliberately differs from the mainstream","definitionCN":"描述有意区别于主流的生活方式或音乐风格","example":"The festival celebrates alternative music and independent art.","exampleCN":"这个音乐节推崇另类音乐和独立艺术。","why":"From the 1970s and 1980s, alternative became a label for culture that chooses the other path on purpose. Difference turns into identity.","whyCN":"从 20 世纪 70、80 年代起，alternative 成了有意选择另一条路的文化标签。差异本身变成了一种身份。"},{"no":"08","title":"Have no alternative","titleCN":"别无选择","definition":"to have no other course of action available","definitionCN":"没有其他可行的做法","example":"With the last train gone, we had no alternative but to walk.","exampleCN":"末班车已经走了，我们别无选择，只能走路。","why":"When only one prong remains, the fork collapses into a single path. The phrase uses the word for choice to name the absence of choice.","whyCN":"当只剩下一个齿，那把叉就塌成一条路。这个短语用“选择”的词来命名“没有选择”。"},{"no":"09","title":"Alternative investments","titleCN":"另类投资","definition":"in finance, investments outside the traditional categories of stocks, bonds, and cash","definitionCN":"金融中指股票、债券和现金等传统类别之外的投资","example":"The fund put a quarter of its money into alternative investments.","exampleCN":"该基金把四分之一的资金投入了另类投资。","why":"Finance repeats the same move: assets are sorted into mainstream and other. Alternative investments are defined by where they are not, not by what they are.","whyCN":"金融重复了同一个动作：资产被分成主流与其它。另类投资是由“它不在哪里”来定义的，而不是由“它是什么”来定义的。"}],"etymology":{"intro":{"en":"Alternative is built on Latin alter 'the other'. The adjective appears in the 1580s, the noun in the 1620s, and the modern senses of counter-culture and alternative energy arrived in the 1970s and 1980s.","cn":"alternative 建立在拉丁语 alter“另一个”之上。形容词出现于 16 世纪 80 年代，名词出现于 17 世纪 20 年代，而反文化与替代能源等现代义直到 20 世纪 70、80 年代才出现。"},"items":[{"era":"1580s","en":"The adjective is first recorded meaning 'offering one or the other of two'. The choice is strictly binary at this stage.","cn":"形容词最早记录，意为“提供两者中的一个或另一个”。在这个阶段，选择仍是严格二元的。"},{"era":"1620s","en":"The noun appears in rhetoric: 'a proposition involving two statements, the acceptance of one implying the rejection of the other'.","cn":"名词出现在修辞学中，意为“包含两个陈述的命题，接受一个就意味着否定另一个”。"},{"era":"MEDIEVAL LATIN","en":"From Medieval Latin alternativus, from Latin alternatus, past participle of alternare 'do one thing and then another, do by turns', from alternus 'one after the other, alternate'.","cn":"来自中世纪拉丁语 alternativus，再往上为拉丁语 alternatus，即 alternare“做一件再做另一件、轮流做”的过去分词，后者来自 alternus“一个接一个、交替的”。"},{"era":"LATIN / PIE","en":"Alternus comes from alter 'the other (of two)', reconstructed as PIE *al- 'beyond' plus the comparative suffix *-ter. The PIE form is a reconstruction, not an attested word.","cn":"alternus 来自 alter“两者中的另一个”，后者被重构为原始印欧语 *al-“越过”加比较级后缀 *-ter。这个原始印欧语形式是构拟，不是有文献记录的词。"},{"era":"19C.","en":"Of courses of action the noun is recorded from 1814; of objects that may be chosen, from 1836. The word moves from logic to ordinary decisions.","cn":"名词指“行动方案”的记录始于 1814 年；指“可供选择的对象”的记录始于 1836 年。这个词从逻辑学走进了日常决定。"},{"era":"20C.–MODERN","en":"The adjective 'purporting to be a superior choice to what is in general use' is current by 1970. Alternative energy is from 1975, and alternative music from 1984.","cn":"形容词义“自称比通用选择更优越”到 1970 年已通行。alternative energy 始于 1975 年，alternative music 始于 1984 年。"}]},"similar":{"note":{"en":"The first group separates look-alike words, including the verb that shares this root; the second group separates words that also name a choice. Form is checked before meaning.","cn":"第一组区分形近词，其中包括共享词根的动词；第二组区分同样表示“选择”的词。先看词形，再看词义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"alternate","ipa":"/ˈɔːltənət/ (adj.), /ˈɔːltəneɪt/ (v.)","tag":"same root, different meaning","definition":"happening by turns, or to take turns. It shares the altern- stem but describes rotation, not a choice between options.","definitionCN":"轮流发生的；轮流做。它共享 altern- 词干，但描述的是轮换，不是选项之间的选择。"},{"word":"alternately","ipa":"/ˈɔːltənətli/","tag":"derived form","definition":"in turns, one after the other. It is not the same as alternatively, which means 'as another possibility'.","definitionCN":"轮流地、一个接一个地。它不同于 alternatively“作为另一种可能”。"},{"word":"alter","ipa":"/ˈɔːltə/","tag":"same root","definition":"to change something. It is the verb underneath alternative, but it names the act of change, not the choice that results from it.","definitionCN":"改变某物。它是 alternative 底下的动词，但命名的是改变的动作，不是改变后产生的选择。"}]},{"heading":"NEAR MEANING","entries":[{"word":"option","ipa":"/ˈɒpʃən/","tag":"neutral choice","definition":"one of the things you can choose. It is neutral and does not suggest a second-best path.","definitionCN":"可以选择的项目之一。它语气中性，不暗示这是次优路径。"},{"word":"choice","ipa":"/tʃɔɪs/","tag":"general word","definition":"the act of choosing, or the range of things to choose from. It is broader and warmer than alternative.","definitionCN":"选择的行为，或可供选择的范围。它比 alternative 更宽泛、更温暖。"},{"word":"substitute","ipa":"/ˈsʌbstɪtjuːt/","tag":"replacement","definition":"a person or thing that takes the place of another. It stresses replacement rather than the existence of a second option.","definitionCN":"取代另一人或另一物的替代者。它强调替换，而不是“存在第二个选项”。"},{"word":"backup","ipa":"/ˈbækʌp/","tag":"reserve","definition":"a spare person or thing kept ready in case the first fails. It is more concrete and informal than alternative.","definitionCN":"为防第一个失败而备好的人或物。它比 alternative 更具体、更口语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real word parts, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实短语和真实同族词，而不是编造的顺口溜。"},"normal":[{"en":"alternative energy is energy from a source other than the usual fossil fuels.","cn":"alternative energy 是来自化石燃料之外其它来源的能源。"},{"en":"alternative medicine is defined by standing outside mainstream medicine, not by being new.","cn":"另类疗法是由“站在主流医学之外”来定义的，而不是因为它新。"},{"en":"alternatively means 'as another possibility', while alternately means 'in turns' — keep the two adverbs apart.","cn":"alternatively 意为“作为另一种可能”，而 alternately 意为“轮流地”——要把这两个副词分开。"},{"en":"an alternative to something is the standard phrase: 'Is there an alternative to this plan?'","cn":"an alternative to something 是标准搭配：“这个计划有替代方案吗？”"},{"en":"alternate, alternation and alternative all carry the 'other / by turns' idea from alter.","cn":"alternate、alternation、alternative 都带着来自 alter 的“另一个／轮流”观念。"}],"abstract":[{"en":"Picture a fork in a road with two signs of equal size. One says USUAL, the other says ALSO POSSIBLE. Alternative is the second sign.","cn":"想象岔路口两块同样大的路牌：一块写“常规”，另一块写“也可行”。alternative 就是第二块牌子。"},{"en":"The word does not always mean the second is worse. It only says another path exists; the judgement comes from context.","cn":"这个词并不总意味着第二个更差。它只说还有另一条路；好坏判断来自上下文。"},{"en":"In culture and finance, alternative becomes an identity: a deliberate choice to stand outside the mainstream, not merely a spare option.","cn":"在文化和金融里，alternative 变成一种身份：有意站在主流之外，而不只是一个备用选项。"}]},"examples":[{"en":"Is there an alternative to this expensive plan?","cn":"这个昂贵的计划有替代方案吗？"},{"en":"The doctor suggested an alternative treatment.","cn":"医生建议了一种替代疗法。"},{"en":"We had no alternative but to cancel the trip.","cn":"我们别无选择，只能取消旅行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“奥特拿替夫”——奥特拿一个替夫（替身）出来 → alternative 替代方案、备选","word":"alternative"},"root":"源自拉丁语 alter“两者中的另一个”，经 alternus、alternare 到中世纪拉丁语 alternativus；核心是“另一条也可走的路”。","sensesIntro":{"en":"Nine senses of alternative, all one image: two paths stand side by side, and the second is still open. It can be a choice, a backup, a replacement, another route, a counter-cultural label, or a financial category.","cn":"alternative 的九个义项都是同一个画面：两条路并排，第二条仍然通。它可以是选择、备选、替代品、另一条路线、反主流标签，或一个金融类别。"},"semanticMap":{"core":{"en":"CORE IMAGE: two paths stand side by side; one is the usual road, the other is still open.","cn":"核心意象：两条路并排；一条是常规路线，另一条仍然通。"},"chain":["ONE PATH","OTHER PATH","CHOICE","REPLACEMENT","DIFFERENT WAY","STILL VALID"],"branches":[{"senses":"01 · 08","en":"CHOICE LOGIC: two options exist, and taking one may exclude the other; when only one remains, choice turns into necessity.","cn":"选择逻辑：两个选项存在，取一个可能排除另一个；当只剩一个，选择就变成了必然。"},{"senses":"02 · 03","en":"REPLACEMENT: the second path is kept ready as a backup or used in place of the first.","cn":"替换：第二条路被备好，或直接占据第一条路的位置。"},{"senses":"04 · 05","en":"PRACTICAL OTHER: a schedule, route or energy source is described as the non-usual one.","cn":"实际替代：时间安排、路线或能源被描述为“不是通常那个”。"},{"senses":"06 · 07","en":"COUNTER-CULTURE: alternative medicine, lifestyle and music define themselves by standing outside the mainstream.","cn":"反主流文化：另类疗法、生活方式和音乐通过“站在主流之外”来定义自己。"},{"senses":"09","en":"FINANCE: alternative investments are the assets placed outside the traditional categories.","cn":"金融：另类投资是被放在传统类别之外的资产。"}]},"affixes":{"intro":{"en":"alternative is a learned Latin adjective and noun. The suffixes below build adverbs and nouns; the compounds are common modern labels in energy, medicine, music and finance.","cn":"alternative 是一个学术性的拉丁形容词兼名词。下面的后缀构成副词和名词；复合词是能源、医疗、音乐和金融领域的常见现代标签。"},"latinIntro":{"en":"The Latin alter 'other' family is productive: alternate, alternation and altruism all descend from it, and alter itself is the verb 'to change'. The PIE *al- is reconstructed, not attested.","cn":"拉丁语 alter“另一个”的词族能产：alternate、alternation、altruism 都出自它，alter 本身是动词“改变”。原始印欧语 *al- 是构拟形式，并非有文献直接记录。"},"items":[{"word":"alternatively","structure":"alternative + -ly (adverb)","meaning":"as another possibility; or else","meaningCN":"或者；作为替代（-ly 构成副词）","example":"We could, alternatively, meet on Friday.","exampleCN":"或者，我们也可以周五见面。"},{"word":"alternativeness","structure":"alternative + -ness (quality noun)","meaning":"the quality of being alternative or optional","meaningCN":"替代性；备选性（-ness 构成性质名词）","example":"The alternativeness of the plan was its appeal.","exampleCN":"这个计划的备选性正是它的吸引力。"},{"word":"alternativity","structure":"alternative + -ity (quality noun)","meaning":"the state of being an alternative","meaningCN":"替代性；另类性（-ity 构成名词）","example":"The term alternativity appears in logic and design.","exampleCN":"alternativity 这个词出现在逻辑学和设计领域。"},{"word":"alternativism","structure":"alternative + -ism (doctrine or movement)","meaning":"a preference for alternative or non-mainstream forms","meaningCN":"另类主义；偏好非主流形式（-ism 表示学说、主义）","example":"The gallery was known for its alternativism.","exampleCN":"这家画廊以另类主义闻名。"},{"word":"alternativist","structure":"alternativism + -ist (person)","meaning":"a supporter of alternative or non-mainstream forms","meaningCN":"另类主义者（-ist 表示信奉某主张的人）","example":"As an alternativist, he avoided major labels.","exampleCN":"作为另类主义者，他避开大厂牌。"},{"word":"alternative energy","structure":"alternative + energy (compound)","meaning":"energy from sources other than fossil fuels","meaningCN":"替代能源（alternative + energy 复合）","example":"Solar power is a common form of alternative energy.","exampleCN":"太阳能是常见的替代能源。"},{"word":"alternative medicine","structure":"alternative + medicine (compound)","meaning":"treatment outside conventional scientific medicine","meaningCN":"另类疗法（alternative + medicine 复合）","example":"Acupuncture is often classed as alternative medicine.","exampleCN":"针灸常被归为另类疗法。"},{"word":"alternative rock","structure":"alternative + rock (compound)","meaning":"rock music outside the mainstream commercial style","meaningCN":"另类摇滚（alternative + rock 复合）","example":"The band started in small alternative rock clubs.","exampleCN":"这支乐队从小型另类摇滚俱乐部起步。"},{"word":"alternative route","structure":"alternative + route (compound)","meaning":"another way to reach a place when the usual road is closed","meaningCN":"替代路线（alternative + route 复合）","example":"The app found an alternative route around the traffic.","exampleCN":"应用找到了一条绕过堵车的替代路线。"},{"word":"alternative investment","structure":"alternative + investment (compound)","meaning":"an investment outside stocks, bonds and cash","meaningCN":"另类投资（alternative + investment 复合）","example":"Hedge funds are a type of alternative investment.","exampleCN":"对冲基金是一种另类投资。"},{"word":"alternative dispute resolution","structure":"alternative + dispute + resolution (compound)","meaning":"methods of settling a dispute outside court","meaningCN":"替代性纠纷解决机制（复合名词）","example":"The contract requires alternative dispute resolution first.","exampleCN":"合同要求先走替代性纠纷解决程序。"}],"latinEntries":[{"word":"alternate","structure":"alter 'other' + -ate","meaning":"to take turns; every other one","meaningCN":"交替；间隔的"},{"word":"alternately","structure":"alternate + -ly","meaning":"in turns","meaningCN":"交替地"},{"word":"alternation","structure":"alternare + -tion","meaning":"the act of alternating","meaningCN":"交替"},{"word":"altruism","structure":"alter 'other' + -ism","meaning":"concern for others","meaningCN":"利他主义"}]}}]);
